-- 중독백과 남은 122개 항목 본문(body)·심화(advanced) 일괄 주입
-- 물질32 + 기전26 + 심리20 + 진단16 + 정책10 + 프로그램6 + 인물8 + 사회4 = 122
-- definition(요약) 미변경. id 기준 UPDATE. 주석은 -- 만 사용.
-- 실행: psql -h localhost -U postgres -d addiction_news -f inject_all_remaining.sql
BEGIN;
-- ===== substance =====
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "물질중독은 알코올, 니코틴, 아편류, 자극제, 진정제 등 정신활성물질의 반복 사용으로 뇌의 보상·동기 회로가 변형되어 사용 통제력을 잃는 상태다. 물질마다 작용 방식과 위험은 다르지만, ''해가 되는 줄 알면서도 멈추지 못한다''는 통제 상실이 공통 핵심이다."}, {"h": "어떻게 진단하나", "p": "DSM-5-TR은 남용·의존이라는 이분법 대신 ''물질사용장애''로 통합하고, 통제력 상실·사회적 손상·위험한 사용·약리적 지표(내성·금단) 등 증상 개수에 따라 경도·중등도·고도로 심각도를 구분한다. 진단의 초점은 사용량 자체가 아니라 기능 손상과 통제 상실이다."}, {"h": "어떻게 진행되나", "p": "대개 실험적·사교적 사용에서 시작해, 점차 사용량이 늘고(내성), 중단 시 불편이 생기며(금단), 해로운 결과에도 지속하는 강박적 사용으로 넘어간다. 초기의 쾌락 추구가 후기의 고통 회피로 바뀌는 전환이 물질중독의 전형적 경로다."}, {"h": "회복", "p": "물질중독은 만성·재발성 질환으로 이해되며, 약물치료·심리치료·자조모임·사회적 지원의 결합으로 관리된다. 물질에 따라 효과적인 치료가 다르므로(예: 아편류의 약물보조치료), 개인과 물질에 맞춘 접근과 충분한 기간, 지속 관리가 회복을 좌우한다."}]'::jsonb, advanced='[{"h": "공통 기전", "p": "서로 다른 물질도 결국 뇌의 보상회로(중뇌변연계 도파민 경로)를 활성화하고, 반복 노출로 신경적응을 일으켜 내성·금단·갈망을 만든다. 이 공통 기전이 다양한 물질을 하나의 ''물질사용장애''로 묶는 근거다. 다만 물질별 약리·위험 프로파일의 차이도 임상적으로 중요하다."}, {"h": "스펙트럼으로서의 이해", "p": "물질중독은 ''있다/없다''의 이분법이 아니라 심각도의 연속선으로 이해된다. 이는 조기 개입과 단계적 대응의 근거가 되며, 경도 사용장애에서 고도 의존까지 서로 다른 개입이 필요함을 시사한다."}, {"h": "낙인과 언어", "p": "물질중독은 도덕적 결함으로 오해되기 쉬워, ''중독자'' 같은 낙인적 언어 대신 ''물질사용장애를 가진 사람''처럼 사람 중심 언어를 쓰는 것이 권장된다. 언어의 전환이 치료 접근과 회복 태도에 영향을 준다는 인식이 확산되고 있다."}]'::jsonb, updated_at=now() WHERE id='substance-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "펜타닐은 모르핀보다 수십 배에서 백 배가량 강력한 합성 아편류로, 원래 강한 통증 치료에 쓰인다. 극소량으로도 치명적일 수 있어, 최근 북미를 중심으로 약물 과용 사망의 주된 원인이 되었다."}, {"h": "왜 위험한가", "p": "펜타닐은 다른 약물(헤로인·위조 알약 등)에 몰래 섞이는 경우가 많아, 사용자가 인지하지 못한 채 치명적 용량에 노출된다. 균일하게 섞이지 않아 같은 봉지에서도 치사량 편차가 크다. 이 ''보이지 않는 위험''이 과용 사망을 급증시켰다."}, {"h": "새로운 위협", "p": "최근에는 진정제 자일라진(''트랭크'')이나 다른 합성물질과 혼합되는 사례가 늘어, 날록손만으로 되돌리기 어려운 과용이 문제로 부상했다. 합성 아편류 시장이 계속 변형되며 대응을 어렵게 한다."}, {"h": "대응", "p": "과용을 되돌리는 날록손의 광범위한 보급, 성분을 확인하는 약물 검사, 안전소비시설, 약물보조치료 확대가 핵심 대응으로 꼽힌다. 전 세계 확산이 우려되는 공중보건 현안이다."}]'::jsonb, advanced='[{"h": "과용 위기의 ''제4의 물결''", "p": "북미 아편류 위기는 처방약 → 헤로인 → 펜타닐 → 펜타닐+자극제/진정제 혼합으로 이어지는 국면 변화로 설명된다. 펜타닐은 이 위기를 치명성 면에서 근본적으로 바꿔놓았다."}, {"h": "날록손의 한계", "p": "펜타닐은 강력해 여러 번의 날록손 투여가 필요할 수 있고, 자일라진 혼합 시 아편류 길항제가 듣지 않는 부분이 생긴다. 이에 고용량 제형과 새로운 대응 전략이 요구된다."}, {"h": "공급 측 대응의 딜레마", "p": "합성 아편류는 소량으로 대량 효과를 내 밀거래 단속이 어렵고, 전구물질 규제도 제조자가 화학구조를 바꾸며 우회한다. 공급 차단만으로는 한계가 크다는 점이 보건 중심 접근의 필요를 부각한다."}]'::jsonb, updated_at=now() WHERE id='fentanyl-synthetic-opioids';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "전자담배·베이핑은 니코틴 등을 액체에서 증기 형태로 만들어 흡입하는 기기 및 그 사용을 가리킨다. 연소를 거치지 않아 일부 유해물질이 적다는 점에서 금연 보조 수단으로 논의되는 한편, 청소년 유입이라는 우려도 크다."}, {"h": "피해감소인가 관문인가", "p": "성인 흡연자의 금연을 돕는 상대적으로 덜 해로운 대안이라는 주장과, 청소년을 니코틴 중독으로 이끄는 관문이라는 우려가 정면으로 충돌한다. 두 주장 모두 부분적 근거가 있어 정책적 균형이 어렵다."}, {"h": "무엇이 문제인가", "p": "고농도 니코틴 팟형 제품과 니코틴 파우치의 빠른 확산으로 청소년 니코틴 노출이 늘었고, 특정 첨가물로 인한 급성 폐손상 사례도 보고됐다. 장기 건강 영향은 아직 충분히 규명되지 않았다."}, {"h": "규제", "p": "각국은 향(맛) 규제, 연령 제한, 니코틴 농도 상한, 광고 제한 등으로 대응한다. 금연 지원과 청소년 보호라는 두 목표 사이의 조율이 핵심 과제다."}]'::jsonb, advanced='[{"h": "근거의 불확실성", "p": "전자담배의 금연 효과와 장기 안전성에 대한 근거는 아직 진화 중이다. 상대적 위해 감소는 인정되나 ''무해''가 아니며, 비흡연 청소년에게는 순위험이 될 수 있다는 점에서 대상별로 평가가 갈린다."}, {"h": "EVALI와 제품 다양화", "p": "2019년 특정 첨가물(비타민E 아세테이트 등)과 연관된 급성 폐손상(EVALI) 사례는 제품 성분 규제의 중요성을 부각했다. 니코틴 파우치 등 새로운 무연 제품의 확산은 규제의 대상을 계속 넓히고 있다."}, {"h": "담배 정책과의 관계", "p": "전자담배는 수십 년간 축적된 담배 규제 정책에 새로운 변수를 던졌다. 피해감소 논리를 담배 산업이 전략적으로 활용한다는 비판도 있어, 공중보건·산업·규제의 이해관계가 복잡하게 얽혀 있다."}]'::jsonb, updated_at=now() WHERE id='vaping-ecigarettes';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "대마는 THC·CBD 등을 함유한 식물로, THC는 도취·지각 변화를, CBD는 비도취성 효과를 낸다. 여러 국가·지역이 의료용·기호용 사용을 합법화하는 흐름이 세계적으로 진행 중이다."}, {"h": "합법화 흐름", "p": "의료용에서 시작해 기호용으로 확대되는 합법화가 북미 등에서 진행됐다. 형사처벌의 폐해를 줄이고 시장을 규제·과세하려는 목적이지만, 그 사회·보건적 효과는 지역·기간에 따라 평가가 엇갈린다."}, {"h": "높아진 THC 농도", "p": "재배·추출 기술 발달로 제품의 THC 농도가 과거보다 크게 높아졌다. 이는 대마사용장애, 청소년기 뇌 발달 영향, 정신증 위험에 대한 우려를 키우며, ''예전의 대마와 다르다''는 지적으로 이어진다."}, {"h": "무엇을 봐야 하나", "p": "대마는 상대적으로 위험이 낮다는 인식과, 고농도·조기 사용의 위험이라는 우려가 공존한다. 합법화의 편익(형사처벌 감소, 규제 가능)과 위험(사용 증가·청소년 영향)을 함께 저울질하는 균형 잡힌 시각이 필요하다."}]'::jsonb, advanced='[{"h": "대마사용장애", "p": "대마도 사용장애를 일으킬 수 있으며, 특히 조기·고빈도·고농도 사용에서 위험이 높다. ''중독되지 않는다''는 통념과 달리 금단·통제 상실이 나타날 수 있다는 점이 임상적으로 강조된다."}, {"h": "정신증 논쟁", "p": "고농도 THC의 조기·빈번한 사용과 정신증 위험의 연관이 보고되지만, 인과인지 취약성의 발현인지에 대한 논쟁이 있다. 유전·환경적 취약성과의 상호작용이 핵심 변수로 지목된다."}, {"h": "합법화의 자연 실험", "p": "여러 지역의 합법화는 정책의 효과를 관찰하는 ''자연 실험''을 제공한다. 청소년 사용, 사고, 세수, 불법시장 축소 등 다양한 지표에서 결과가 엇갈려, 단순한 성공·실패 서사보다 다면적 평가가 요구된다."}]'::jsonb, updated_at=now() WHERE id='cannabis';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "케타민은 해리성 마취제로, 낮은 용량에서 해리·환각 효과를 낸다. 오락적 오남용의 대상인 동시에, 난치성 우울증 치료제(에스케타민 비강 스프레이 등)로 승인·활용되는 이중적 성격을 지닌다."}, {"h": "치료제로서", "p": "기존 항우울제에 반응하지 않는 우울증에서 빠른 효과를 보여, 통제된 의료 환경에서 치료제로 쓰인다. 자살 위험이 높은 우울에서 신속한 개선을 준다는 점이 주목받는다."}, {"h": "오남용의 위험", "p": "오락적으로 반복 사용하면 방광 손상(케타민 방광), 인지 문제, 심리적 의존이 나타날 수 있다. 해리 상태에서 위험 인지가 둔해져 사고 위험도 커진다."}, {"h": "균형", "p": "케타민은 ''통제된 치료''와 ''오락적 오남용''이라는 두 얼굴을 지녀, 치료적 가능성을 살리면서 남용 위험을 관리하는 균형이 관건이다. 치료 접근성 확대와 오남용 예방을 함께 고려해야 한다."}]'::jsonb, advanced='[{"h": "작용 기제", "p": "케타민은 NMDA 수용체 길항 등 기존 항우울제와 다른 경로로 작용하며, 신경가소성 촉진이 빠른 항우울 효과의 기전으로 제시된다. 이 독특한 기제가 치료 저항성 우울에서의 가치를 설명한다."}, {"h": "치료와 남용의 경계", "p": "의료용 에스케타민은 통제된 환경에서 감독하에 투여되는 반면, 오락적·비의료적 사용은 전혀 다른 위험을 수반한다. 치료의 대중적 관심이 이 경계를 흐리고 자가 사용을 부추길 위험이 지적된다."}, {"h": "사이키델릭 치료와의 관계", "p": "케타민은 넓게는 의식 변형 물질을 치료에 활용하는 흐름의 일부로 논의되며, 사이키델릭 보조치료 연구와 문제의식을 공유한다. 다만 약리·규제 지위가 달라 별도로 다뤄진다."}]'::jsonb, updated_at=now() WHERE id='ketamine';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "크라톰은 동남아시아 원산 식물로, 저용량에서는 자극제, 고용량에서는 아편류 유사 효과를 낸다. 통증 완화나 아편류 금단의 자가치료 목적으로 쓰이기도 한다."}, {"h": "왜 논쟁적인가", "p": "''자연 물질''이라는 인식과 달리 의존 가능성과 안전성 논란이 있으며, 성분·효력이 제품마다 일정치 않아 위험 예측이 어렵다. 규제 공백 속에서 국가·지역별로 합법성이 크게 엇갈린다."}, {"h": "자가치료의 딜레마", "p": "아편류를 끊으려 크라톰을 쓰다가 크라톰 자체에 의존하게 되는 사례가 있다. 접근 가능한 대안이라는 측면과, 검증되지 않은 위험이라는 측면이 공존한다."}, {"h": "무엇을 봐야 하나", "p": "크라톰은 잠재적 유용성과 위험이 모두 불확실한 물질이다. 표준화·품질관리·연구가 부족한 상태에서, 과도한 기대와 무분별한 규제 사이의 균형 잡힌 접근이 요구된다."}]'::jsonb, advanced='[{"h": "약리적 이중성", "p": "크라톰의 주요 알칼로이드(미트라기닌 등)는 용량에 따라 자극·진정 효과를 내며 아편류 수용체에도 작용한다. 이 복합적 약리 때문에 ''아편류인가 아닌가''라는 단순 분류가 어렵다."}, {"h": "규제의 딜레마", "p": "엄격히 금지하면 자가치료 수단을 잃고 불법시장으로 밀려나며, 방치하면 품질·안전 관리가 안 된다. 성분 표준화가 어려워 규제 설계 자체가 까다로운 물질이다."}, {"h": "근거의 부족", "p": "크라톰의 효능·위험에 대한 통제된 연구가 부족해, 개별 사례 보고에 의존하는 상황이다. 근거 공백이 과장된 기대와 과장된 위험 양쪽을 부추긴다."}]'::jsonb, updated_at=now() WHERE id='kratom';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "아편류는 양귀비에서 유래하거나 이를 본떠 합성한 진통·진정 계열 물질군으로, 뇌의 아편류 수용체에 작용해 통증을 줄이고 강한 도취감을 준다. 천연(모르핀)·반합성(헤로인·옥시코돈)·합성(펜타닐·메타돈)으로 나뉜다."}, {"h": "왜 위험한가", "p": "의존성이 강하고, 과용 시 호흡을 억제해 사망에 이를 수 있다. 내성이 빠르게 생겨 사용량이 늘고, 금단 회피 동기가 사용을 지속시킨다. 이 조합이 아편류를 가장 치명적인 물질군 중 하나로 만든다."}, {"h": "의료와 위기 사이", "p": "아편류는 통증 치료에 필수적이면서 동시에 세계 약물 위기의 중심이다. 통증 관리의 필요와 의존·과용 위험 사이의 균형이 아편류를 둘러싼 핵심 긴장이다."}, {"h": "치료", "p": "아편류 사용장애는 메타돈·부프레노르핀 같은 약물보조치료로 효과적으로 관리되며, 과용 대응(날록손)과 피해감소가 생명을 지킨다. 아편류는 근거 기반 치료가 가장 잘 확립된 물질군에 속한다."}]'::jsonb, advanced='[{"h": "내인성 아편류 체계", "p": "아편류는 몸이 스스로 만드는 엔도르핀 등 내인성 아편류 체계에 작용한다. 이 체계가 통증·보상·정서 조절에 관여하기에, 외부 아편류가 강력한 진통과 도취를 동시에 일으킨다."}, {"h": "아편류 위기의 구조", "p": "처방 아편류의 과잉 공급에서 시작해 헤로인, 펜타닐로 이어진 위기는 의료·산업·규제·불법시장이 얽힌 구조적 문제다. 단일 원인이 아니라 여러 요인의 상호작용으로 이해된다."}, {"h": "통증 치료와의 긴장", "p": "아편류 위기에 대한 반작용으로 처방이 위축되면서, 정당한 통증 환자가 치료를 받지 못하는 문제도 발생했다. 과소·과잉 처방 사이의 균형이 임상·정책의 지속적 과제다."}]'::jsonb, updated_at=now() WHERE id='opioids';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "자극제는 중추신경계를 각성시켜 각성도·에너지·자신감을 높이는 물질군으로, 도파민·노르에피네프린 활동을 증가시킨다. 코카인·암페타민·메스암페타민·카페인·니코틴 등이 포함된다."}, {"h": "어떻게 작동하나", "p": "자극제는 뇌의 각성·보상 신호를 증폭해 짧고 강한 고양감을 준다. 효과가 끝나면 급격한 붕괴(''크래시'')가 오고, 이 격차를 메우려 반복 사용하게 되는 것이 자극제 사용의 전형적 패턴이다."}, {"h": "위험", "p": "과용 시 심혈관 위험(부정맥·심정지·뇌졸중)과 급성 정신증(편집·환각)을 일으킬 수 있다. 장기 사용은 인지 손상과 심한 신체 쇠약으로 이어진다."}, {"h": "치료의 공백", "p": "아편류·알코올과 달리 자극제 사용장애에는 승인된 효과적 약물치료가 없다. 이 때문에 유관관리 같은 행동 치료가 가장 근거 있는 개입으로 부각된다."}]'::jsonb, advanced='[{"h": "도파민 재흡수와 방출", "p": "자극제는 도파민 재흡수를 막거나(코카인) 방출을 촉진해(암페타민류) 시냅스 도파민을 급증시킨다. 이 급격한 증폭이 강한 보상과 함께 신경적응·손상을 유발한다."}, {"h": "자극제 위기의 부상", "p": "아편류 위기에 가려졌으나, 메스암페타민·코카인 관련 과용과 아편류와의 혼합 사용이 늘며 자극제 문제가 재부상하고 있다. 효과적 약물치료의 부재가 대응을 어렵게 한다."}, {"h": "치료·수행 향상 논쟁", "p": "일부 자극제는 ADHD 치료제로 쓰이며, 비의료적 ''인지 향상'' 목적의 오남용이 문제된다. 치료적 사용과 남용의 경계, 처방 관리가 쟁점이다."}]'::jsonb, updated_at=now() WHERE id='stimulants';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "억제제(진정제)는 중추신경계 활동을 늦춰 진정·이완·수면을 유도하는 물질군으로, 주로 GABA 신경전달을 강화한다. 알코올·벤조디아제핀·바르비투르산염 등이 포함된다."}, {"h": "왜 위험한가", "p": "여러 억제제를 함께 쓰거나 아편류와 병용하면 호흡억제가 가중되어 치명적일 수 있다. 특히 알코올과 진정제, 아편류의 혼합이 과용 사망의 흔한 원인이다."}, {"h": "위험한 금단", "p": "억제제는 금단이 의학적 응급이 될 수 있는 대표 계열이다. 알코올·벤조디아제핀 금단은 경련·섬망으로 생명을 위협할 수 있어, 반드시 의료 감독하에 중단해야 한다."}, {"h": "무엇을 주의하나", "p": "억제제는 불안·불면 치료에 유용하지만, 내성·의존이 생기기 쉽고 중단이 위험하다. 특히 다른 억제제·아편류와의 병용 위험을 아는 것이 안전의 핵심이다."}]'::jsonb, advanced='[{"h": "GABA 강화 기제", "p": "억제제는 억제성 신경전달물질 GABA의 작용을 강화해 신경 활동을 늦춘다. 이 공통 기제 때문에 억제제끼리, 또는 아편류와 병용 시 효과가 상승적으로 위험해진다."}, {"h": "교차내성과 금단 관리", "p": "억제제 사이에는 교차내성이 있어, 한 억제제(예: 벤조디아제핀)로 다른 억제제(알코올)의 금단을 관리하기도 한다. 이 원리가 안전한 해독의 근거가 된다."}, {"h": "병용 위험의 임상", "p": "억제제와 아편류의 병용은 과용 사망의 주요 경로다. 처방 단계에서 병용을 피하고, 불가피하면 위험을 관리하는 것이 임상적 과제로 강조된다."}]'::jsonb, updated_at=now() WHERE id='depressants';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "환각제는 지각·사고·정서를 크게 변화시켜 환각이나 의식 변형을 일으키는 물질군이다. 세로토닌계에 작용하는 고전적 환각제(LSD·실로시빈·메스칼린)와 해리성(케타민·PCP)으로 나뉜다."}, {"h": "어떤 위험이 있나", "p": "신체적 의존성은 낮은 편이나, 예측 불가능한 심리 반응(''배드 트립''), 드물게 지속되는 지각장애(HPPD), 그리고 판단력 저하로 인한 사고 위험이 있다. 기저 정신질환이 있으면 위험이 커진다."}, {"h": "세트와 세팅", "p": "환각제 경험은 개인의 심리 상태(set)와 환경(setting)에 크게 좌우된다. 같은 물질·용량도 맥락에 따라 전혀 다른 경험을 낳으며, 이 원리가 치료적 활용의 핵심 조건이 된다."}, {"h": "치료 연구", "p": "일부 고전적 환각제는 통제된 임상에서 우울·PTSD·중독 치료 가능성이 연구된다. 다만 이는 오락적 사용과 구분되는, 전문가가 동반하는 통제된 세팅에서의 활용이다."}]'::jsonb, advanced='[{"h": "세로토닌계 작용", "p": "고전적 환각제는 주로 세로토닌 5-HT2A 수용체에 작용해 지각·인지를 변형한다. 이 작용이 자아 경계의 일시적 이완과 새로운 통찰 경험의 신경적 배경으로 제시된다."}, {"h": "HPPD와 지속 효과", "p": "일부 사용자에게서 사용 후에도 지각 이상이 지속되는 HPPD가 보고되지만, 빈도·기전은 충분히 규명되지 않았다. 대부분의 지각 변화는 일시적이라는 점과 함께 신중히 다뤄진다."}, {"h": "치료 르네상스와 신중함", "p": "환각제의 치료 연구가 활발해지며 ''사이키델릭 르네상스''로 불리지만, 근거는 아직 축적 단계다. 과장된 기대와 자가 사용의 위험을 경계하며, 통제된 연구 맥락과 오락적 사용을 구분하는 것이 중요하다."}]'::jsonb, updated_at=now() WHERE id='hallucinogens';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "벤조디아제핀은 불안·불면·경련 치료에 쓰이는 진정제 계열로, GABA 작용을 강화해 빠른 진정 효과를 낸다. 단기적으로 유용하지만 의존 위험이 있다."}, {"h": "왜 주의하나", "p": "내성과 의존이 비교적 빠르게 생기고, 장기·고용량 사용 후 중단하면 반동성 불안·불면과 위험한 금단(경련 등)이 나타날 수 있다. 그래서 단기·최소 용량 사용이 원칙이다."}, {"h": "병용 위험", "p": "아편류나 알코올과 함께 쓰면 호흡억제가 가중되어 과용 사망 위험이 크게 높아진다. 벤조디아제핀은 아편류 과용 사망에 흔히 관여하는 물질이다."}, {"h": "안전한 사용", "p": "벤조디아제핀은 필요할 때 단기간, 최소 용량으로 쓰고, 중단은 서서히 감량하며 의료 감독하에 이뤄져야 한다. 장기 사용자는 갑작스러운 중단을 피해야 한다."}]'::jsonb, advanced='[{"h": "작용과 내성", "p": "벤조디아제핀은 GABA-A 수용체의 작용을 강화하며, 반복 사용 시 수용체 적응으로 내성이 생긴다. 이 적응이 반동성 증상과 금단의 생물학적 배경이다."}, {"h": "장기 처방의 문제", "p": "불안·불면에 장기 처방되면서 의존이 형성되는 사례가 많아, ''처방된 의존''이 임상적 문제로 지적된다. 특히 고령자에서 낙상·인지 문제 위험이 커진다."}, {"h": "탈처방(deprescribing)", "p": "장기 사용자의 안전한 감량·중단을 돕는 ''탈처방''이 임상 과제로 부상했다. 급작스러운 중단의 위험 때문에, 체계적이고 서서히 진행하는 감량 전략이 강조된다."}]'::jsonb, updated_at=now() WHERE id='benzodiazepines';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "바르비투르산염은 과거 진정·수면·항경련 목적으로 널리 쓰인 억제제로, GABA 작용을 강화한다. 안전 용량과 치사 용량의 차이가 좁아 과용 위험이 크다."}, {"h": "왜 대체됐나", "p": "치료 범위가 좁아 조금만 많이 복용해도 위험에 이를 수 있고, 강한 신체적 의존과 위험한 금단을 일으킨다. 이 때문에 더 안전한 벤조디아제핀 등장 이후 사용이 크게 줄었다."}, {"h": "현재의 쓰임", "p": "오늘날 바르비투르산염은 일부 항경련·마취 등 제한된 의료 목적으로만 남아 있다. 남용 대상으로서의 비중은 과거보다 크게 줄었다."}, {"h": "무엇을 기억할까", "p": "바르비투르산염은 ''더 안전한 약이 기존 약을 대체해 온'' 정신약물사의 한 사례다. 동시에 좁은 안전역이 얼마나 치명적일 수 있는지를 보여준다."}]'::jsonb, advanced='[{"h": "좁은 치료 지수", "p": "바르비투르산염은 유효 용량과 치사 용량이 가까워, 실수나 병용만으로도 치명적 과용에 이르기 쉽다. 이 특성이 벤조디아제핀으로의 대체를 이끈 핵심 이유다."}, {"h": "금단의 위험", "p": "억제제 계열답게 바르비투르산염 금단도 경련 등 생명을 위협할 수 있어, 중단 시 의료 관리가 필수다."}, {"h": "역사적 의의", "p": "바르비투르산염의 흥망은 약물 안전성 평가와 규제의 발전을 보여주는 사례로, 이후 정신약물 개발에서 안전역의 중요성을 각인시켰다."}]'::jsonb, updated_at=now() WHERE id='barbiturates';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "칸나비노이드는 대마 식물의 성분(THC·CBD 등)과 이에 작용하는 물질군으로, 뇌의 내인성 칸나비노이드 수용체에 작용한다. THC는 도취를, CBD는 비도취성 효과를 낸다."}, {"h": "천연과 합성", "p": "천연 칸나비노이드(대마 성분) 외에, 실험실에서 만든 합성 칸나비노이드가 있다. 합성 제품은 효력이 예측 불가능하고 강해, 천연 대마와 전혀 다른 급성 독성을 일으킬 수 있다."}, {"h": "합성 칸나비노이드의 위험", "p": "''합법 대마''를 표방하며 유통되던 합성 칸나비노이드는 심각한 정신증·발작·응급 상황을 일으킨 사례가 많다. 성분이 계속 바뀌어 위험 예측과 규제가 어렵다."}, {"h": "무엇을 봐야 하나", "p": "칸나비노이드는 의료적 가능성(CBD 등)부터 심각한 위험(합성 제품)까지 스펙트럼이 넓다. 천연·합성, 성분별로 위험이 크게 다르다는 점을 구분하는 것이 중요하다."}]'::jsonb, advanced='[{"h": "내인성 칸나비노이드 체계", "p": "몸에는 스스로 만드는 칸나비노이드와 그 수용체(CB1·CB2)로 이뤄진 조절 체계가 있어, 식욕·통증·기분·기억을 조절한다. 외부 칸나비노이드가 이 체계에 작용해 다양한 효과를 낸다."}, {"h": "합성 칸나비노이드의 규제 추격", "p": "합성 칸나비노이드는 규제를 피하려 화학구조를 바꿔 등장하는 대표적 신종 물질군이다. 규제가 늘 뒤따라가는 ''추격 게임'' 양상이 위험을 키운다."}, {"h": "CBD의 부상", "p": "비도취성 성분 CBD가 일부 뇌전증 등에서 치료적으로 쓰이며 주목받는다. 다만 시장의 CBD 제품은 품질·함량 편차가 커, 근거와 마케팅 사이의 간극이 지적된다."}]'::jsonb, updated_at=now() WHERE id='cannabinoids';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "흡입제는 본드·부탄·에어로졸·용제 등 흡입해 도취를 얻는 휘발성 물질군이다. 값싸고 구하기 쉬워 특히 청소년 남용이 문제된다."}, {"h": "왜 치명적인가", "p": "흡입제는 단 한 번의 사용으로도 급성 심정지(''돌연 흡입 사망'')를 일으킬 수 있다. 예측 불가능하게 치명적일 수 있다는 점이 다른 물질과 구별되는 특징이다."}, {"h": "반복 사용의 해", "p": "반복 흡입은 뇌·신경·간·신장 손상을 누적시킨다. 특히 발달 중인 청소년의 뇌에 미치는 영향이 심각하다."}, {"h": "무엇이 문제인가", "p": "흡입제는 생활용품이라 접근을 막기 어렵고, 저연령층이 첫 남용 물질로 접하기 쉽다. 예방 교육과 조기 개입이 핵심 대응이 된다."}]'::jsonb, advanced='[{"h": "돌연 흡입 사망", "p": "흡입제는 심장을 아드레날린에 과민하게 만들어, 놀람·운동 같은 자극에 치명적 부정맥을 유발할 수 있다. 이 기전이 ''한 번의 사용''도 치명적일 수 있는 이유다."}, {"h": "사회적 취약성", "p": "흡입제 남용은 빈곤·방임 등 사회적 취약성과 연관이 깊다. 값싸고 접근 쉬운 특성상, 다른 물질에 접근하기 어려운 환경의 저연령층에서 두드러진다."}, {"h": "예방의 딜레마", "p": "위험을 알리는 예방 교육이 오히려 정보를 제공할 수 있다는 딜레마가 있어, 흡입제 예방은 신중한 메시지 설계가 요구된다. 접근 통제와 취약성 해소가 함께 가야 한다."}]'::jsonb, updated_at=now() WHERE id='inhalants';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "아나볼릭 스테로이드는 근육 증대를 위해 오남용되는 남성호르몬 유사 물질이다. 다른 중독과 달리 즉각적 도취보다 신체상·수행 강박과 얽혀 사용된다."}, {"h": "어떻게 다른가", "p": "쾌락 추구보다 ''이상적 몸''에 대한 강박이 사용을 이끈다는 점이 특징이다. 이 때문에 운동중독·섭식장애·신체이형과 함께 나타나는 경우가 많다."}, {"h": "위험", "p": "장기 사용은 심혈관 질환, 호르몬계 교란, 간 손상, 정신적 변화(공격성·기분 변화)를 일으킨다. 중단 시 우울·무기력 등 금단 유사 반응이 나타난다."}, {"h": "무엇을 봐야 하나", "p": "아나볼릭 스테로이드 남용은 외모·수행에 대한 사회적 압력과 얽혀 있다. 부작용을 알면서도 멈추지 못하는 배경에 신체상 강박이 있음을 이해하는 것이 대응의 출발이다."}]'::jsonb, advanced='[{"h": "보상과 신체상", "p": "아나볼릭 스테로이드는 전형적 도취를 주지 않지만, 신체상 개선에 대한 강한 보상이 사용을 강화한다. 중독의 대상이 물질의 효과가 아니라 그것이 가져다주는 몸의 변화라는 점이 독특하다."}, {"h": "근이형증과의 관계", "p": "''충분히 크지 않다''는 왜곡된 신체상(근이형증)이 스테로이드 남용의 심리적 배경으로 지목된다. 이는 섭식장애의 신체상 왜곡과 유사한 기제로 이해된다."}, {"h": "건강 담론의 이면", "p": "건강·피트니스 담론과 SNS의 몸 이미지 문화가 스테로이드 남용을 부추길 수 있다. 개인의 문제를 넘어, 몸에 대한 사회적 압력이라는 맥락에서 볼 필요가 있다."}]'::jsonb, updated_at=now() WHERE id='anabolic-steroids';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "신종 합성마약은 규제를 피하려 기존 약물의 화학 구조를 변형해 만든 신종 물질군이다. 합성 카티논(''배스 솔트''), 합성 칸나비노이드 등이 대표적이다."}, {"h": "왜 위험한가", "p": "성분과 효력이 일정치 않아 위험을 예측하기 어렵고, 규제가 뒤따라가는 사이 급성 중독·사망 사례가 발생한다. ''합법''을 표방하며 유통되기도 해 안전하다는 오해를 부른다."}, {"h": "규제와의 추격전", "p": "한 물질이 금지되면 화학구조를 조금 바꾼 새 물질이 등장하는 ''추격 게임''이 반복된다. 이 때문에 개별 물질 금지만으로는 대응이 어렵다."}, {"h": "무엇을 봐야 하나", "p": "신종 합성마약은 ''알 수 없는 성분''이라는 점 자체가 위험이다. 사용자도 무엇을 얼마나 쓰는지 모르는 경우가 많아, 성분 검사와 신속한 위험 경보가 중요해진다."}]'::jsonb, advanced='[{"h": "규제 설계의 진화", "p": "개별 물질 금지의 한계 때문에, 유사 구조 물질을 포괄 규제하는 ''유사체(analogue) 규제''나 신속 임시 규제가 도입됐다. 그러나 이 역시 화학적 창의성을 완전히 따라잡지 못한다."}, {"h": "조기경보체계", "p": "신종 물질의 등장을 신속히 탐지·경보하는 국제·국가 조기경보체계가 중요해졌다. 사용자·의료진에게 위험을 빠르게 알리는 것이 피해를 줄이는 핵심이다."}, {"h": "성분 불확실성의 위험", "p": "신종 합성마약의 최대 위험은 성분·용량의 불확실성이다. 약물 검사 서비스가 이 위험을 줄이는 피해감소 수단으로 주목받는다."}]'::jsonb, updated_at=now() WHERE id='designer-drugs';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "처방약 오남용은 의료용 약물(아편류 진통제, 자극제, 진정제)을 처방 목적·용량과 다르게 사용하는 것을 말한다. ''의사가 준 약''이라는 인식 때문에 위험이 과소평가되기 쉽다."}, {"h": "어떤 경로로 일어나나", "p": "자신의 처방을 용량 이상 쓰거나, 가족·지인의 약을 나눠 쓰거나(''전용''), 도취 목적으로 쓰는 등 다양하다. 집에 남은 약이 시작점이 되는 경우가 흔하다."}, {"h": "왜 위험한가", "p": "처방약도 오남용하면 의존·과용을 일으킨다. 아편류 처방약 오남용은 아편류 위기의 한 축을 이뤘고, 진정제·자극제 오남용도 심각한 위험을 수반한다."}, {"h": "대응", "p": "안전한 처방·보관·폐기, 처방 모니터링, 그리고 ''처방약은 안전하다''는 오해를 바로잡는 교육이 핵심이다. 정당한 치료 필요와 오남용 위험 사이의 균형이 관건이다."}]'::jsonb, advanced='[{"h": "아편류 위기의 출발점", "p": "처방 아편류의 과잉 공급과 오남용이 북미 아편류 위기의 초기 단계였다. 이후 규제가 강화되자 일부 사용자가 헤로인·펜타닐로 옮겨간 ''풍선 효과''가 나타났다."}, {"h": "처방 모니터링의 양면", "p": "처방약 모니터링 프로그램은 오남용·중복처방을 줄이지만, 과도하면 정당한 통증 환자의 치료 접근을 막을 수 있다. 감시와 접근 사이의 균형이 정책 과제다."}, {"h": "가정 내 약물의 관리", "p": "오남용의 흔한 출발점이 가정 내에 남은 약이라는 점에서, 안전한 보관과 회수·폐기 프로그램이 예방의 실질적 수단으로 강조된다."}]'::jsonb, updated_at=now() WHERE id='prescription-misuse';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "알코올은 가장 널리 사용되고 합법적인 억제제로, 소량에서도 판단·운동 능력을 떨어뜨리고 반복·과다 사용 시 알코올사용장애로 이어진다. 세계적으로 질병 부담이 가장 큰 물질 중 하나다."}, {"h": "왜 문제 인식이 늦나", "p": "술은 사회적으로 용인되고 일상에 깊이 스며 있어, 문제를 인정하고 도움을 청하기까지 오래 걸린다. ''누구나 마시는 것''이라는 인식이 알코올사용장애의 조기 개입을 어렵게 한다."}, {"h": "금단의 위험", "p": "알코올 금단은 경련·섬망(진전섬망)으로 생명을 위협할 수 있는 대표적 위험 금단이다. 오래·많이 마신 사람은 갑자기 끊지 말고 반드시 의료 관리하에 중단해야 한다."}, {"h": "치료", "p": "알코올사용장애는 심리치료, 자조모임, 그리고 약물치료(날트렉손·아캄프로세이트 등)로 관리된다. 조기 발견과 낙인 없는 접근이 치료 진입을 높인다."}]'::jsonb, advanced='[{"h": "광범위한 건강 부담", "p": "알코올은 간질환·암·심혈관·사고·폭력 등 광범위한 건강·사회적 해악과 연관된다. ''적정 음주는 건강에 좋다''는 통념은 최근 근거에서 후퇴하고 있으며, 안전한 음주량에 대한 논쟁이 진행 중이다."}, {"h": "정책 지렛대", "p": "가격(주류세), 이용 가능성, 광고 규제가 알코올 관련 해악을 줄이는 효과적 정책 지렛대로 꼽힌다. 합법·보편 물질인 만큼, 개인 치료를 넘어선 인구 차원 정책의 역할이 크다."}, {"h": "사회적 비용", "p": "알코올의 사회적 비용은 의료비를 넘어 생산성 손실·사고·가정 붕괴로 확산된다. 합법성 때문에 위험이 과소평가되지만, 실제 질병 부담은 대부분의 불법 물질을 능가한다."}]'::jsonb, updated_at=now() WHERE id='alcohol';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "담배의 주된 중독 성분인 니코틴은 강한 의존을 만드는 자극제로, 흡연은 예방 가능한 사망의 주요 원인이다. 의존이 빠르게 형성되고 금단이 재발을 부른다."}, {"h": "왜 끊기 어려운가", "p": "니코틴 의존은 매우 강하고, 금단(짜증·갈망·집중곤란·불안)이 뚜렷하다. 흡연이 일상 습관·상황과 촘촘히 연합되어 있어, 건강 위험을 알면서도 금연에 여러 번 실패하는 경우가 흔하다."}, {"h": "변화하는 전달 형태", "p": "전자담배, 니코틴 파우치 등 니코틴 전달 형태가 다양해지고 있다. 이는 금연 보조라는 측면과 청소년 니코틴 유입이라는 측면을 동시에 낳는다."}, {"h": "치료", "p": "니코틴 대체요법(패치·껌 등), 약물치료(바레니클린·부프로피온), 상담이 금연 성공률을 높인다. 여러 번의 시도가 흔하므로, 실패를 실패로 낙인찍지 않는 것이 중요하다."}]'::jsonb, advanced='[{"h": "의존 형성의 속도", "p": "니코틴은 흡입 시 수초 안에 뇌에 도달해 강력한 강화를 일으키며, 이 빠른 전달이 강한 의존의 배경이다. 청소년기 노출은 발달 중인 뇌에 특히 큰 영향을 준다."}, {"h": "담배 규제의 성공과 과제", "p": "가격·광고 규제, 금연 구역, 경고 문구 등 담배 규제는 공중보건의 대표적 성공 사례다. 그러나 신종 니코틴 제품의 등장이 규제 대상을 계속 넓히는 새로운 과제를 낳는다."}, {"h": "피해감소 논쟁", "p": "전자담배 등을 통한 니코틴 피해감소가 금연을 도울지, 새로운 의존을 만들지에 대한 논쟁이 담배 정책의 최전선이다. 성인 흡연자와 청소년 비흡연자에게 미치는 영향이 상반될 수 있다는 점이 핵심이다."}]'::jsonb, updated_at=now() WHERE id='nicotine-tobacco';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "카페인은 세계에서 가장 널리 쓰이는 정신활성물질로, 각성을 높이는 온화한 자극제다. 커피·차·에너지음료 등에 들어 있으며 대부분 안전하게 소비된다."}, {"h": "의존과 금단", "p": "규칙적으로 섭취하면 내성과 의존이 생기며, 갑자기 중단하면 두통·피로·짜증·집중곤란 같은 금단이 나타난다. 이는 카페인이 온화하지만 엄연한 정신활성물질임을 보여준다."}, {"h": "진단적 위치", "p": "DSM은 카페인 중독(급성)과 카페인 금단을 인정하되, ''카페인사용장애''는 추가 연구가 필요한 상태로 둔다. 대부분의 사용은 문제가 되지 않지만, 일부는 통제에 어려움을 겪는다."}, {"h": "무엇을 알면 좋나", "p": "과도한 카페인은 불안·불면·심계항진을 유발할 수 있고, 특히 에너지음료의 고용량 섭취가 청소년에서 우려된다. 중단 시 금단을 완화하려면 서서히 줄이는 것이 좋다."}]'::jsonb, advanced='[{"h": "아데노신 차단", "p": "카페인은 졸음을 유발하는 아데노신 수용체를 차단해 각성을 높인다. 반복 섭취 시 수용체가 늘어나는 적응이 일어나, 이것이 내성과 금단 두통의 기전이다."}, {"h": "중독 모델의 시금석", "p": "카페인은 널리 쓰이면서 의존·금단이 명확해, ''어디까지를 중독으로 볼 것인가''를 논하는 시금석이 된다. 의존이 있다고 모두 장애는 아니라는 점을 보여주는 사례다."}, {"h": "공중보건적 관심", "p": "에너지음료의 고카페인·당 함량과 청소년 소비가 공중보건적 관심사로 부상했다. 알코올과의 혼합 소비 위험도 지적된다."}]'::jsonb, updated_at=now() WHERE id='caffeine';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "헤로인은 모르핀에서 만든 강력한 반합성 아편류로, 빠르고 강한 도취와 함께 높은 의존·과용 위험을 지닌다. 대표적 불법 아편류다."}, {"h": "어떻게 위험한가", "p": "강한 도취만큼 과용(호흡억제) 위험이 크고, 주사 사용은 HIV·간염 등 감염 위험을 더한다. 최근에는 펜타닐 혼입으로 치사 위험이 크게 높아졌다."}, {"h": "어떤 경로로 이르나", "p": "처방 아편류에 의존이 생긴 뒤 더 싸고 강한 헤로인으로 옮겨가는 경로가 흔하다. 처방약 규제 강화가 오히려 이 이동을 부추긴 측면도 있다."}, {"h": "치료", "p": "헤로인 사용장애는 메타돈·부프레노르핀 같은 약물보조치료로 효과적으로 관리되며, 날록손·안전소비시설 등 피해감소가 생명을 지킨다. 일부 국가는 헤로인 보조치료(HAT)로 만성 사용자를 관리한다."}]'::jsonb, advanced='[{"h": "빠른 전달과 의존", "p": "헤로인은 뇌에 빠르게 도달해 강한 보상을 일으키며, 이 속도가 강한 의존의 배경이다. 투여 경로(주사·흡입)에 따라 위험이 달라진다."}, {"h": "펜타닐 혼입의 위협", "p": "불법 헤로인에 펜타닐이 섞이면서, 사용자가 인지하지 못한 채 치명적 용량에 노출되는 경우가 급증했다. 이는 헤로인 사용의 위험 지형을 근본적으로 바꿨다."}, {"h": "피해감소와 HAT", "p": "헤로인 사용장애 관리에서 피해감소(날록손·주사기 교환·안전소비시설)와 헤로인 보조치료(HAT)가 근거를 축적해 왔다. 스위스 등의 HAT는 만성·치료저항 사용자에게 효과를 보였다."}]'::jsonb, updated_at=now() WHERE id='heroin';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "코카인은 코카 잎에서 추출한 강력한 자극제로, 짧고 강렬한 도취를 준다. 흡입형 크랙은 더 빠르고 강한 효과를 내 의존 위험이 높다."}, {"h": "어떻게 작동하나", "p": "코카인은 강렬한 고양감을 짧게 준 뒤 급격한 붕괴를 남긴다. 이 격차를 메우려 반복 사용하게 되며, 짧은 지속시간이 잦은 재사용을 부른다."}, {"h": "위험", "p": "심혈관 합병증(부정맥·심정지·뇌졸중)과 급성 정신증 위험이 크다. 반복 사용은 심리적 의존과 인지·정신 문제로 이어진다."}, {"h": "치료의 공백", "p": "자극제인 코카인에는 승인된 효과적 약물치료가 없어, 유관관리 같은 행동 치료가 가장 근거 있는 접근으로 꼽힌다. 심리사회적 지원이 회복의 중심이 된다."}]'::jsonb, advanced='[{"h": "도파민 재흡수 차단", "p": "코카인은 도파민 재흡수를 차단해 시냅스 도파민을 급증시킨다. 이 강렬하고 짧은 도파민 급등이 강한 보상과 잦은 재사용의 신경적 배경이다."}, {"h": "크랙과 사회적 낙인", "p": "1980년대 크랙 확산은 강한 사회적 공포와 처벌적 정책을 낳았고, 인종·계층에 따른 불평등한 형사처벌로 비판받았다. 코카인은 마약 정책의 형평성 논쟁과 얽혀 있다."}, {"h": "혼합 사용 위험", "p": "코카인을 아편류와 함께 쓰는 ''스피드볼''은 상반된 작용의 병용으로 특히 위험하다. 최근 자극제와 펜타닐의 혼합 과용이 새로운 위협으로 부상하고 있다."}]'::jsonb, updated_at=now() WHERE id='cocaine';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "메스암페타민은 지속시간이 길고 강력한 합성 자극제로, 강한 각성·다행감과 함께 심각한 신경독성을 지닌다. 끊기 매우 어려운 물질로 꼽힌다."}, {"h": "어떻게 진행되나", "p": "효과가 오래가는 만큼 며칠씩 잠을 자지 않고 사용을 이어가는 ''런'' 패턴이 나타나기도 한다. 반복 사용은 편집·환각 같은 정신증과 심한 신체 쇠약으로 이어진다."}, {"h": "위험", "p": "심혈관 위험, 급성·만성 정신증, 인지 손상, 치아·피부 등 신체 손상이 광범위하다. 신경독성으로 인한 손상 중 일부는 오래 지속된다."}, {"h": "치료", "p": "메스암페타민 사용장애도 승인된 약물치료가 없어, 유관관리·인지행동치료 등 행동 치료가 중심이다. 정신증·인지 문제의 관리와 장기적 지지가 함께 필요하다."}]'::jsonb, advanced='[{"h": "강한 도파민 방출", "p": "메스암페타민은 도파민을 대량 방출시키고 재흡수를 막아, 코카인보다 길고 강한 효과를 낸다. 이 강력한 작용이 신경독성과 강한 의존의 배경이다."}, {"h": "자극제 위기의 재부상", "p": "아편류 위기에 가려졌으나 메스암페타민 관련 과용·정신증이 늘고 있고, 아편류와의 혼합 사용도 증가한다. 효과적 약물치료의 부재가 대응을 어렵게 한다."}, {"h": "정신증과 회복", "p": "메스암페타민 유발 정신증은 중단 후에도 지속되거나 재발할 수 있다. 회복 과정에서 인지·정신 증상의 관리가 중요하며, 무쾌감·우울이 초기 회복을 특히 힘겹게 만든다."}]'::jsonb, updated_at=now() WHERE id='methamphetamine';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "암페타민은 각성·집중을 높이는 자극제 계열로, 일부는 ADHD·기면증 치료제로 처방된다. 치료 용량에서는 유용하지만 오남용 시 위험하다."}, {"h": "치료제이자 남용 대상", "p": "적절히 처방된 암페타민류는 ADHD 치료에서 효과가 크고, 치료가 오히려 중독 위험을 낮추기도 한다. 반면 학업·수행 향상 목적의 비의료적 오남용이 문제된다."}, {"h": "위험", "p": "오남용 시 의존, 불면, 심혈관 위험, 불안·정신증이 나타날 수 있다. 고용량·비경구 사용일수록 위험이 커진다."}, {"h": "무엇을 봐야 하나", "p": "암페타민은 ''치료''와 ''남용''이 갈리는 대표적 물질이다. 처방의 정당한 활용과 오남용 예방을 함께 고려하는 균형이 필요하다."}]'::jsonb, advanced='[{"h": "치료가 위험을 낮춘다", "p": "치료받지 않은 ADHD가 오히려 물질 사용 위험을 높이고, 적절한 자극제 치료가 그 위험을 낮춘다는 근거가 있다. ''치료제=중독 유발''이라는 단순 도식이 맞지 않음을 보여준다."}, {"h": "인지 향상 논쟁", "p": "건강한 사람의 ''인지 향상'' 목적 사용은 효과·윤리·안전 면에서 논쟁적이다. 실제 향상 효과는 제한적이라는 근거와, 경쟁 압력에 따른 오남용 확산 우려가 공존한다."}, {"h": "처방 관리의 균형", "p": "자극제 처방의 오남용·전용을 막으면서 정당한 환자의 접근을 보장하는 균형이 임상·정책의 과제다. 과잉·과소 처방 모두 문제가 된다."}]'::jsonb, updated_at=now() WHERE id='amphetamines';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "엑스터시(MDMA)는 자극제와 환각제의 성질을 함께 지닌 물질로, 친밀감·에너지·감각 고양을 일으켜 클럽 환경에서 오남용된다."}, {"h": "어떤 위험이 있나", "p": "과열·탈수·저나트륨혈증, 세로토닌 관련 위험이 있으며, 불법 시장의 순도 불확실성이 위험을 키운다. 사용 후 며칠간 기분 저하가 흔하다."}, {"h": "치료 연구", "p": "한편 MDMA는 통제된 임상에서 PTSD 치료 보조로 연구되는 물질이다. 이는 오락적 사용과 구분되는, 치료자가 동반하는 통제된 세팅에서의 활용이다."}, {"h": "무엇을 구분해야 하나", "p": "파티에서의 오락적 사용과 임상시험의 치료 보조는 맥락·용량·환경이 전혀 다르다. 이 구분을 흐리면 자가 사용의 위험을 과소평가하게 된다."}]'::jsonb, advanced='[{"h": "세로토닌 작용", "p": "MDMA는 세로토닌을 대량 방출시켜 친밀감·고양감을 일으키고, 이후 세로토닌 고갈이 사용 후 기분 저하의 배경이 된다. 반복 사용의 신경 영향은 논쟁적이다."}, {"h": "치료 연구의 부침", "p": "MDMA 보조 PTSD 치료는 유망한 결과를 보였으나, 규제 승인 과정에서 방법론·안전성 문제가 제기되며 부침을 겪었다. 근거의 질과 승인 판단은 계속 진화 중이다."}, {"h": "순도와 피해감소", "p": "불법 MDMA는 다른 물질이 섞이는 경우가 많아, 성분 검사가 피해감소 수단으로 활용된다. 순도 불확실성이 오락적 사용의 주요 위험이다."}]'::jsonb, updated_at=now() WHERE id='mdma-ecstasy';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "LSD는 매우 적은 양으로 강한 지각·의식 변형을 일으키는 고전적 환각제다. 신체 의존성은 낮은 편이다."}, {"h": "어떤 위험이 있나", "p": "예측 불가능한 심리 반응(''배드 트립''), 드물게 지속되는 지각장애(HPPD), 판단력 저하로 인한 사고 위험이 있다. 기저 정신질환이 있으면 위험이 커진다."}, {"h": "세트와 세팅", "p": "같은 용량이라도 심리 상태와 환경에 따라 경험이 크게 달라진다. 불안한 상태·환경에서의 사용은 공포스러운 경험으로 이어질 수 있다."}, {"h": "치료 연구", "p": "LSD를 포함한 고전적 환각제는 통제된 임상에서 우울·불안·중독 치료 가능성이 연구된다. 다만 이는 전문가가 동반하는 통제된 세팅에서의 활용이다."}]'::jsonb, advanced='[{"h": "미량 활성과 세로토닌", "p": "LSD는 마이크로그램 단위의 미량으로 세로토닌 수용체에 작용해 강한 효과를 낸다. 이 강한 활성이 예측 불가능한 심리 반응의 배경이 된다."}, {"h": "HPPD", "p": "일부 사용자에게서 지각 이상이 지속되는 HPPD가 보고되지만 빈도·기전은 불확실하다. 대부분의 지각 변화는 일시적이라는 점과 함께 신중히 다뤄진다."}, {"h": "치료 역사와 재조명", "p": "LSD는 20세기 중반 정신의학 연구에 쓰였다가 규제로 중단됐고, 최근 사이키델릭 연구 부흥 속에서 재조명되고 있다. 규제 지위와 근거는 계속 변화 중이다."}]'::jsonb, updated_at=now() WHERE id='lsd';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "실로시빈은 환각버섯의 주성분인 고전적 환각제로, 세로토닌계에 작용해 의식 변형을 일으킨다."}, {"h": "어떤 위험이 있나", "p": "야생 버섯의 오남용은 종 오인에 따른 중독 위험을 더한다. LSD와 유사하게 예측 불가능한 심리 반응과 사고 위험이 있으며, 기저 정신질환이 있으면 위험하다."}, {"h": "치료 연구", "p": "실로시빈은 통제된 임상에서 치료저항성 우울·불안·중독 치료 가능성이 활발히 연구되는 대표 물질이다. 일부 지역은 제도화를 진행 중이다."}, {"h": "무엇을 구분해야 하나", "p": "임상 연구의 실로시빈 치료는 표준화된 용량, 안전한 환경, 치료자 동반, 통합 심리치료를 포함한다. 이는 야생 버섯의 자가 사용과 근본적으로 다르다."}]'::jsonb, advanced='[{"h": "치료 연구의 최전선", "p": "실로시빈 보조치료는 사이키델릭 연구 부흥의 중심에 있으며, 여러 임상시험에서 긍정적 신호가 보고됐다. 다만 눈가림의 어려움, 장기 효과 등 방법론적 과제가 남아 있다."}, {"h": "기전 가설", "p": "실로시빈이 신경가소성을 촉진하고 경직된 자기·세계 인식을 유연하게 만들어 치료 효과를 낸다는 가설이 제시되나, 확립되지 않았다."}, {"h": "제도화와 접근성", "p": "일부 지역의 제도화는 접근성과 형평성, 안전한 시행이라는 새로운 과제를 낳는다. 치료 맥락과 오락적 사용을 명확히 구분하는 것이 핵심이다."}]'::jsonb, updated_at=now() WHERE id='psilocybin';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "모르핀은 아편에서 추출한 대표적 천연 아편류로, 강력한 진통 효과 때문에 의료에서 필수적으로 쓰인다."}, {"h": "의료적 필수성", "p": "모르핀은 말기 통증·수술 후 통증 등 심한 통증 관리에 필수적이다. WHO 필수의약품 목록에 오른, 통증 완화의 기본 약물이다."}, {"h": "위험", "p": "진통 효과와 함께 내성·의존·호흡억제 위험을 지닌다. 통증 치료의 이익과 의존 위험의 균형이 임상적 과제다."}, {"h": "무엇을 봐야 하나", "p": "모르핀은 ''필수 치료제이자 의존 위험 물질''이라는 아편류의 이중성을 대표한다. 통증 관리 접근성과 남용 예방을 함께 고려해야 한다."}]'::jsonb, advanced='[{"h": "아편류의 원형", "p": "모르핀은 이후 헤로인·반합성 아편류의 원형이 된 물질이다. 아편류의 진통·도취·호흡억제라는 공통 특성이 모르핀에서 전형적으로 나타난다."}, {"h": "통증 치료 접근성의 격차", "p": "세계적으로 많은 지역에서 모르핀 같은 아편류 진통제 접근이 부족해, 완화의료가 필요한 환자가 통증에 방치되는 문제가 있다. 남용 우려와 통증 치료 접근의 균형이 국제 보건 과제다."}, {"h": "규제와 의료의 긴장", "p": "아편류 위기에 대한 반작용이 정당한 통증 치료의 위축으로 이어질 수 있다. 모르핀은 이 규제-의료 긴장의 중심에 있는 약물이다."}]'::jsonb, updated_at=now() WHERE id='morphine';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "아편은 양귀비 열매에서 얻는 물질로, 모르핀·코데인 등 아편류의 원천이다. 인류가 오래전부터 진통·도취 목적으로 사용해 온 역사적 마약이다."}, {"h": "역사적 무게", "p": "아편은 근대의 아편 무역과 아편전쟁 등 세계사에 큰 영향을 준 물질이다. 오늘날 마약 규제·통제 체제의 역사적 뿌리가 아편을 둘러싼 국제적 대응에 있다."}, {"h": "아편류의 출발점", "p": "아편에서 모르핀이, 모르핀에서 헤로인이 만들어지는 계보의 시작이 아편이다. 오늘날 아편류 위기의 먼 기원에 이 물질이 있다."}, {"h": "무엇을 기억할까", "p": "아편은 물질과 사회·정치가 얽힌 역사를 보여준다. 마약 문제가 단지 개인의 문제가 아니라 무역·권력·규제와 얽힌 사회적 현상임을 상기시킨다."}]'::jsonb, advanced='[{"h": "국제 마약 통제의 기원", "p": "20세기 초 아편을 둘러싼 국제 협약들이 오늘날 마약 통제 체제의 토대가 됐다. 아편 규제의 역사가 현대 마약 정책의 구조를 형성했다."}, {"h": "생산과 지정학", "p": "아편(양귀비) 생산은 특정 지역의 경제·분쟁과 얽혀 있어, 공급 측 대응이 단순한 단속을 넘어 지정학·개발 문제와 연결된다. 대체작물 개발 등이 논의되는 배경이다."}, {"h": "역사적 교훈", "p": "아편전쟁 등은 물질을 둘러싼 이해관계가 국가 간 갈등으로 비화한 사례다. 마약 문제를 도덕이 아니라 역사·정치경제의 맥락에서 볼 필요를 보여준다."}]'::jsonb, updated_at=now() WHERE id='opium';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "옥시코돈은 강력한 반합성 아편류 진통제로, 처방 남용과 아편류 위기의 중심에 있었다. 통증 치료에 효과적이지만 오남용·의존 위험이 크다."}, {"h": "위기의 상징", "p": "옥시코돈 서방정은 강한 마케팅과 과잉 처방 속에 광범위하게 오남용되며, 북미 아편류 위기의 초기 단계를 상징하는 약물이 됐다."}, {"h": "어떤 경로로 이르나", "p": "통증 치료로 시작한 처방이 오남용·의존으로 이어지고, 규제 강화 후 일부 사용자가 헤로인·펜타닐로 옮겨가는 경로가 전형적이다."}, {"h": "무엇을 봐야 하나", "p": "옥시코돈은 ''정당한 진통제''와 ''위기의 도화선''이라는 두 얼굴을 지닌다. 통증 치료의 필요와 오남용 위험, 그리고 제약 마케팅의 책임까지 함께 봐야 한다."}]'::jsonb, advanced='[{"h": "제약 마케팅과 책임", "p": "옥시코돈을 둘러싼 공격적 마케팅과 의존 위험의 축소가 위기를 키웠다는 점에서, 아편류 위기는 개인 병리를 넘어 산업·규제의 책임 문제를 제기한다."}, {"h": "서방정 오남용", "p": "서서히 방출되도록 설계된 제형을 부수어 한꺼번에 흡수시키는 방식의 오남용이 문제였다. 이는 오남용 억제 제형(abuse-deterrent) 개발로 이어졌다."}, {"h": "풍선 효과", "p": "처방 규제 강화가 처방약 오남용은 줄였으나, 일부 사용자를 더 위험한 불법 아편류로 밀어낸 ''풍선 효과''가 나타났다. 공급 측 대응만의 한계를 보여주는 사례다."}]'::jsonb, updated_at=now() WHERE id='oxycodone';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "GHB는 중추 억제제로 도취·진정을 일으키며, 안전 용량과 위험 용량의 차이가 좁아 의식소실·호흡억제 위험이 크다."}, {"h": "왜 위험한가", "p": "조금만 많이 써도 의식을 잃거나 호흡이 억제될 수 있어, 오락적 사용이 특히 위험하다. 알코올 등 다른 억제제와 병용하면 위험이 급증한다."}, {"h": "약물이용범죄와의 연관", "p": "무색·무취의 특성 때문에 음료에 몰래 섞여 피해자를 무력화하는 약물이용범죄에 악용되기도 한다."}, {"h": "무엇을 주의하나", "p": "GHB는 좁은 안전역과 빠른 의식소실이라는 위험을 지닌다. 병용 위험과 약물이용범죄 가능성에 대한 인식이 중요하다."}]'::jsonb, advanced='[{"h": "좁은 안전역", "p": "GHB는 유효 용량과 위험 용량이 가까워, 정확한 용량 조절이 어렵고 실수가 치명적일 수 있다. 이 특성이 오락적 사용을 특히 위험하게 만든다."}, {"h": "의존과 금단", "p": "반복 사용 시 의존이 생기며, GHB 금단은 심각하고 위험할 수 있어 의료 관리가 필요하다. 억제제 계열의 위험한 금단 양상을 보인다."}, {"h": "범죄 악용과 대응", "p": "GHB의 약물이용범죄 악용은 피해자 비난이 아니라 가해에 초점을 두는 대응, 그리고 인식 교육의 필요를 부각한다."}]'::jsonb, updated_at=now() WHERE id='ghb';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "펜시클리딘(PCP)은 강한 해리성 물질로, 지각 왜곡과 함께 예측 불가능한 흥분·공격성·해리를 일으킬 수 있다."}, {"h": "왜 위험한가", "p": "고용량에서 심각한 정신증과 위험 행동을 유발한다. 해리 상태에서 통증·위험 인지가 둔해져 자신·타인에게 해를 끼치는 사고로 이어질 수 있다."}, {"h": "어떤 효과인가", "p": "PCP는 현실과의 단절(해리), 지각 왜곡, 그리고 예측 불가능한 정서·행동 변화를 일으킨다. 반응이 사람·상황마다 크게 달라 위험 예측이 어렵다."}, {"h": "무엇을 봐야 하나", "p": "PCP는 예측 불가능성과 공격성·정신증 위험이 특징이다. 급성 중독 시 안전 확보와 진정이 우선되는 응급 상황이 될 수 있다."}]'::jsonb, advanced='[{"h": "해리성 기제", "p": "PCP는 케타민과 유사하게 NMDA 수용체를 차단해 해리 효과를 낸다. 그러나 작용이 더 강하고 길어, 심한 정신증·흥분을 일으킬 수 있다."}, {"h": "정신증 모델", "p": "PCP가 유발하는 증상이 조현병과 유사해, 정신증 연구의 모델로 활용되기도 했다. 이는 해리성 물질과 정신증 기전의 연관을 시사한다."}, {"h": "응급 대응", "p": "PCP 급성 중독은 흥분·공격성 때문에 응급 대응이 까다롭다. 자극을 줄인 환경에서의 진정과 안전 확보가 중요하다."}]'::jsonb, updated_at=now() WHERE id='pcp';
-- ===== mechanism =====
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "중독은 해로운 결과를 알면서도 물질 사용이나 특정 행동을 강박적으로 반복하며 통제력을 잃는 만성적 상태다. 갈망, 내성, 금단, 재발을 핵심 특징으로 하며, 물질중독과 행동중독을 아우른다."}, {"h": "의지의 문제가 아니다", "p": "중독은 흔히 ''의지박약''으로 오해되지만, 반복 사용이 뇌의 보상·동기·통제 회로를 변형시킨 결과다. 스스로 멈추려는 의지가 있어도 변형된 뇌가 그것을 어렵게 만든다는 점이 핵심이다."}, {"h": "어떻게 진행되나", "p": "초기의 쾌락 추구에서 시작해, 점차 금단·고통을 피하려는 강박적 사용으로 동기가 옮겨간다. 자발적 선택이 습관적·자동적 행동으로 바뀌며 통제가 어려워진다."}, {"h": "회복 가능성", "p": "중독은 만성·재발성이지만 회복 가능한 상태다. 뇌의 가소성 덕분에 새로운 학습과 지지 환경 속에서 회복이 일어날 수 있다. 재발은 실패가 아니라 관리가 필요하다는 신호로 이해된다."}]'::jsonb, advanced='[{"h": "질병모델과 그 너머", "p": "현대 중독 이해는 중독을 뇌질환으로 보는 질병모델을 중심에 두되, 심리·사회·환경 요인을 통합하는 생물심리사회 모델로 확장돼 왔다. 순수 뇌질환 관점과 학습·맥락 관점 사이의 논쟁이 이어진다."}, {"h": "동기의 전환", "p": "중독의 핵심 전환은 ''좋아서''에서 ''필요해서''로의 이동이다. 쾌락 추구가 고통 회피로 바뀌고, 원함(wanting)과 좋아함(liking)이 분리되는 것이 중독의 역설을 설명한다."}, {"h": "낙인과 정의의 정치", "p": "무엇을 중독으로 규정할지는 과학만이 아니라 사회적 가치와 얽혀 있다. 개념의 확장(행동중독 등)과 낙인의 문제가 중독 정의를 둘러싼 지속적 쟁점이다."}]'::jsonb, updated_at=now() WHERE id='addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "갈망은 물질이나 행동을 강렬하게 원하는 주관적 충동으로, 중독의 가장 특징적인 경험이자 재발의 핵심 예측 요인이다."}, {"h": "무엇이 촉발하나", "p": "특정 장소·사람·시간·감정 같은 단서가 학습된 연합을 통해 갈망을 촉발한다. 스트레스, 부정적 정서, 소량의 재노출도 강한 갈망을 유발한다."}, {"h": "파도처럼 온다", "p": "갈망은 밀려왔다가 시간이 지나면 잦아드는 경향이 있다. 이 ''파도''를 견디는 대처 기술이 회복의 중요한 부분이 되며, 갈망이 영원하지 않다는 이해가 도움이 된다."}, {"h": "어떻게 다루나", "p": "단서 회피, 주의 전환, 마음챙김적 관찰, 지지 관계에 연락하기 등이 갈망 대처에 쓰인다. 갈망과 싸우기보다 그것과 함께 머물며 지나가게 하는 접근이 강조된다."}]'::jsonb, advanced='[{"h": "보상 예측과 도파민", "p": "갈망은 보상을 예측하는 도파민 신호의 급등과 밀접하다. 단서가 보상을 예고할 때 뇌가 ''원함''을 강하게 만들어내며, 이것이 갈망의 신경적 배경이다."}, {"h": "단서 반응성", "p": "중독자는 물질 관련 단서에 강하게 반응하는 ''단서 반응성''을 보인다. 이 반응을 소거하거나 재조건화하는 것이 갈망 관리와 재발예방의 표적이 된다."}, {"h": "원함과 좋아함의 분리", "p": "갈망은 더는 즐겁지 않은데도 강하게 원하게 되는 중독의 역설을 보여준다. 인센티브 현저성 이론은 ''원함''과 ''좋아함''의 분리로 이를 설명한다."}]'::jsonb, updated_at=now() WHERE id='craving';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "내성은 같은 효과를 얻기 위해 점점 더 많은 양이 필요해지는 현상이다. 반복 노출에 대한 신체·신경의 적응 결과다."}, {"h": "왜 위험한가", "p": "내성 때문에 사용량이 늘면 과용 위험도 함께 커진다. 특히 아편류에서 사용량 증가는 호흡억제 위험을 높인다."}, {"h": "금단과의 관계", "p": "내성이 형성되면 사용을 줄이거나 멈출 때 금단이 나타난다. 내성과 금단은 신체적 의존의 두 얼굴로, 함께 나타나는 경우가 많다."}, {"h": "무엇을 알면 좋나", "p": "내성은 그 자체가 중독은 아니다. 처방약으로 내성이 생겨도 통제 상실이 없으면 중독이 아닐 수 있어, 내성과 중독을 구분하는 것이 중요하다."}]'::jsonb, advanced='[{"h": "신경적응의 결과", "p": "내성은 반복 노출에 대응해 뇌가 수용체·신호 체계를 조정한 결과다. 이 적응이 금단·갈망의 생물학적 기초가 된다."}, {"h": "내성 감소와 과용", "p": "한동안 끊으면 내성이 떨어지는데, 이때 예전 용량으로 재사용하면 치명적 과용에 이를 수 있다. 이 ''내성 감소 후 재발''이 과용 사망의 흔한 경로다."}, {"h": "의존과 중독의 구분", "p": "내성은 신체적 의존의 지표이지 중독과 동일하지 않다. 이 구분은 통증 환자를 부당하게 낙인찍지 않기 위해 임상적으로 중요하다."}]'::jsonb, updated_at=now() WHERE id='tolerance';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "교차내성은 한 물질에 대한 내성이 유사하게 작용하는 다른 물질에도 적용되는 현상이다. 같은 계열 물질 사이에서 흔히 나타난다."}, {"h": "어떻게 나타나나", "p": "예컨대 알코올에 내성이 생긴 사람은 다른 억제제(벤조디아제핀 등)에도 어느 정도 내성을 보인다. 같은 수용체 체계에 작용하기 때문이다."}, {"h": "임상적 활용", "p": "교차내성은 위험이자 도구다. 한 억제제로 다른 억제제의 금단을 관리하는 것(예: 알코올 금단에 벤조디아제핀)이 교차내성을 활용한 안전한 해독의 원리다."}, {"h": "무엇을 주의하나", "p": "교차내성 때문에 다른 물질로 바꿔도 여전히 높은 용량이 필요해 위험이 이어질 수 있다. 계열 내 물질 전환이 안전을 보장하지 않는다."}]'::jsonb, advanced='[{"h": "수용체 수준의 공유", "p": "교차내성은 물질들이 같은 수용체·신경 체계에 작용할 때 발생한다. 이는 내성이 특정 물질이 아니라 공통 기전에 대한 적응임을 보여준다."}, {"h": "해독에서의 응용", "p": "억제제 계열의 교차내성은 대체 약물을 이용한 금단 관리의 근거가 된다. 이 원리로 위험한 금단을 더 관리 가능한 약물로 안전하게 다룬다."}, {"h": "병용과 예측 곤란", "p": "교차내성과 상호작용이 얽히면 여러 물질을 병용할 때 효과·위험을 예측하기 어려워진다. 다중물질 사용의 위험을 키우는 요인이다."}]'::jsonb, updated_at=now() WHERE id='cross-tolerance';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "금단은 의존이 형성된 물질의 사용을 줄이거나 멈출 때 나타나는 신체·심리 증상이다. 대개 그 물질의 효과와 반대되는 방향으로 나타난다."}, {"h": "왜 재발을 부르나", "p": "금단의 불편을 피하려는 동기가 사용을 지속시킨다. 초기 회복에서 금단이 재발의 주요 방아쇠가 되며, 후기 중독은 쾌락보다 금단 회피가 사용을 이끈다."}, {"h": "위험한 금단", "p": "알코올·벤조디아제핀·바르비투르산염 금단은 경련·섬망으로 생명을 위협할 수 있어 반드시 의료 감독이 필요하다. 반면 아편류 금단은 극심하지만 대개 생명을 위협하진 않는다."}, {"h": "어떻게 관리하나", "p": "금단은 물질별로 다르게 관리된다. 안전한 해독, 대체 약물, 증상 완화가 쓰이며, 금단을 넘기는 것은 회복의 시작일 뿐 지속 치료로 이어져야 한다."}]'::jsonb, advanced='[{"h": "항상성의 반동", "p": "금단은 물질에 적응한 신경계가 물질이 사라지자 균형을 잃고 반대 방향으로 튀는 반동으로 이해된다. 억제제를 쓰던 뇌가 과흥분되는 것이 대표적이다."}, {"h": "급성과 지속성 금단", "p": "급성 금단 이후에도 불안·불면·무쾌감 등이 오래 지속되는 ''지속성 금단(PAWS)''이 나타날 수 있다. 이 시기가 재발 위험이 높아 장기적 지지가 필요하다."}, {"h": "금단과 알로스타시스", "p": "반복적 금단 경험은 뇌의 스트레스 체계를 변화시켜, 기준선 자체를 낮추는 알로스타시스로 이어진다. 이것이 후기 중독의 ''고통 회피'' 동기를 설명한다."}]'::jsonb, updated_at=now() WHERE id='withdrawal';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "신경적응은 반복적 물질 노출에 대응해 뇌가 구조·기능을 조정하는 과정이다. 내성·금단·갈망의 바탕이 되는 핵심 기전이다."}, {"h": "어떻게 작동하나", "p": "뇌는 물질의 반복 자극에 맞서 수용체 수나 신호 강도를 조정해 균형을 유지하려 한다. 이 적응 때문에 같은 효과에 더 많은 양이 필요해지고(내성), 물질이 없으면 균형이 깨진다(금단)."}, {"h": "왜 중요한가", "p": "신경적응은 중독이 ''선택''이 아니라 ''뇌의 변화''임을 보여준다. 스스로 멈추기 어려운 이유가 변형된 뇌에 있다는 점을 이해하는 것이 낙인을 줄인다."}, {"h": "회복과의 관계", "p": "신경적응은 되돌릴 수 있는 부분이 있다. 사용을 멈추면 뇌가 서서히 회복되지만 시간이 걸리며, 이 회복기가 재발에 취약한 시기이기도 하다."}]'::jsonb, advanced='[{"h": "항상성과 알로스타시스", "p": "신경적응은 항상성을 지키려는 조정이지만, 반복되면 기준선 자체가 이동하는 알로스타시스로 발전한다. 이 이동이 후기 중독의 만성적 불쾌·갈망을 설명한다."}, {"h": "가역성과 시간", "p": "일부 신경적응은 사용 중단 후 회복되지만, 그 속도와 정도는 물질·기간·개인에 따라 다르다. 회복 초기의 무쾌감·인지 저하가 이 회복 과정의 일부일 수 있다."}, {"h": "가소성의 양면", "p": "신경적응은 중독을 만든 뇌 변화이자, 회복을 가능하게 하는 가소성의 이면이다. 같은 유연성이 새로운 학습으로 회복을 이끌 수 있다는 점이 희망의 근거다."}]'::jsonb, updated_at=now() WHERE id='neuroadaptation';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "중뇌변연계 도파민 경로는 복측피개영역(VTA)에서 측좌핵으로 이어지는 뇌의 핵심 보상회로로, 쾌락보다 동기·현저성·강화학습에 관여한다."}, {"h": "왜 중독의 중심인가", "p": "거의 모든 중독 물질과 강박적 행동이 이 경로의 도파민 신호를 직간접적으로 증폭시킨다. 자연적 보상보다 훨씬 강한 신호가 이 회로를 ''납치''해 중독 행동을 강화한다."}, {"h": "무엇을 학습시키나", "p": "이 경로는 보상과 연합된 단서에 ''원함''을 부여해, 그 단서가 강한 동기를 끌어내도록 학습시킨다. 이것이 단서에 의한 갈망과 재발의 기초다."}, {"h": "쾌락이 아니라 동기", "p": "흔한 오해와 달리 도파민은 ''쾌락 그 자체''라기보다 ''무언가를 원하고 추구하게 만드는'' 동기 신호다. 이 구분이 중독의 ''즐겁지 않은데도 원함''을 설명한다."}]'::jsonb, advanced='[{"h": "보상 예측 오류", "p": "도파민 뉴런은 예상보다 나은 보상에 반응하는 ''보상 예측 오류''를 신호한다. 중독 물질은 이 신호를 인위적으로 증폭해 학습을 왜곡한다."}, {"h": "현저성 귀인", "p": "이 경로는 자극에 ''두드러짐(현저성)''을 부여한다. 중독에서는 물질·단서에 과도한 현저성이 귀인되어, 다른 자연적 보상이 상대적으로 무의미해진다."}, {"h": "회로의 확장", "p": "중독은 이 보상회로만이 아니라 전전두피질(통제)·편도체(정서)·습관회로로 확장되는 과정이다. 도파민 경로는 그 시작점이자 중심 마디다."}]'::jsonb, updated_at=now() WHERE id='mesolimbic-dopamine';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "중독은 뇌의 보상·동기·통제·습관 회로가 반복 사용으로 변형된 상태다. 특정 한 부위가 아니라 여러 회로의 상호작용 변화로 이해된다."}, {"h": "어떤 회로가 변하나", "p": "보상을 느끼는 회로, 스트레스·정서를 다루는 회로, 충동을 억제하는 전전두피질, 그리고 행동을 자동화하는 습관 회로가 함께 변한다. 보상은 둔해지고 통제는 약해지며 습관은 강해진다."}, {"h": "왜 통제가 어려운가", "p": "충동을 억제하는 전전두피질의 기능이 약해지는 반면, 물질·단서에 대한 반응은 강해진다. 이 불균형이 ''멈추려 해도 멈추기 어려운'' 상태를 만든다."}, {"h": "회복과 뇌", "p": "뇌의 가소성 덕분에 사용을 멈추고 새로운 경험을 쌓으면 뇌도 서서히 회복된다. 다만 시간이 걸리며, 회복 초기의 무쾌감·인지 저하는 이 회복 과정의 일부다."}]'::jsonb, advanced='[{"h": "세 단계 회로 모델", "p": "중독을 폭식·중독(보상), 금단·부정정서(스트레스), 몰두·기대(집행기능)의 세 단계 회로로 설명하는 모델이 널리 쓰인다. 각 단계가 서로 다른 뇌 영역·신경전달과 연관된다."}, {"h": "전전두 통제의 약화", "p": "반복 사용은 판단·억제를 담당하는 전전두피질의 기능을 약화시킨다. 이 약화가 강한 갈망 앞에서 통제를 잃게 하는 핵심 기제로 지목된다."}, {"h": "질병모델 논쟁", "p": "''중독은 뇌질환''이라는 관점은 낙인을 줄이고 치료를 정당화했으나, 개인의 주체성·회복 가능성·사회적 요인을 과소평가한다는 비판도 받는다. 뇌 변화와 학습·맥락을 통합하는 관점이 요구된다."}]'::jsonb, updated_at=now() WHERE id='brain-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "보상결핍증후군은 뇌의 보상 체계가 둔감해져 정상적 자극에서 만족을 얻기 어려운 상태를 가리키는 개념이다. 이 결핍을 메우려 강한 자극(물질·행동)을 찾게 된다는 가설이다."}, {"h": "어떻게 설명하나", "p": "반복 사용으로 보상 회로가 둔해지면, 일상의 자연적 보상(음식·관계·성취)이 시시하게 느껴진다. 그 공백을 더 강한 인위적 보상으로 메우려는 악순환이 중독을 지속시킨다는 설명이다."}, {"h": "무엇을 시사하나", "p": "이 관점은 중독을 ''쾌락 추구''가 아니라 ''무너진 보상 기준선을 겨우 정상으로 되돌리려는 시도''로 재해석한다. 후기 중독의 무쾌감과 갈망을 이해하는 틀을 제공한다."}, {"h": "회복과의 관계", "p": "회복 초기의 무쾌감·공허감이 이 보상 둔감화와 관련된다. 시간이 지나며 보상 체계가 회복되지만, 그 사이 자연적 보상을 다시 쌓는 경험이 중요하다."}]'::jsonb, advanced='[{"h": "도파민 기능 저하", "p": "보상결핍증후군은 도파민 수용체 밀도·기능의 저하와 연관되는 것으로 제시된다. 이 저하가 강한 자극에 대한 갈망과 자연 보상에 대한 무감각을 낳는다는 가설이다."}, {"h": "유전·개념 논쟁", "p": "이 개념은 특정 유전자 변이와 연결짓는 주장에서 출발했으나, 근거의 일관성과 개념의 타당성을 둘러싼 논쟁이 있다. 매력적 설명력에도 불구하고 신중히 다뤄진다."}, {"h": "무쾌감과의 연결", "p": "보상결핍은 무쾌감(anhedonia)과 밀접하며, 후기 중독·회복 초기의 핵심 고통을 설명한다. 자연 보상의 회복이 이 시기를 넘기는 열쇠로 강조된다."}]'::jsonb, updated_at=now() WHERE id='reward-deficiency';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "무쾌감증은 이전에 즐거움을 주던 것에서 더는 기쁨을 느끼지 못하는 상태다. 우울증의 핵심 증상이자, 중독과 회복 과정에서 중요한 경험이다."}, {"h": "중독과의 관계", "p": "반복적 물질 사용으로 보상 체계가 둔해지면, 일상의 자연적 보상이 무의미하게 느껴지는 무쾌감이 나타난다. 이 공허를 물질로 메우려는 동기가 사용을 지속시킨다."}, {"h": "회복의 고비", "p": "회복 초기에 무쾌감이 두드러질 수 있다. ''끊었는데도 아무것도 즐겁지 않다''는 경험이 재발의 위험한 방아쇠가 되므로, 이 시기를 이해하고 견디는 것이 중요하다."}, {"h": "무엇을 알면 좋나", "p": "무쾌감은 대개 시간이 지나며 회복된다. 자연적 보상(관계·활동·성취)을 조금씩 다시 쌓는 경험이 보상 체계의 회복을 돕는다."}]'::jsonb, advanced='[{"h": "보상 처리의 둔화", "p": "무쾌감은 보상을 예측·경험·학습하는 과정의 둔화로 설명된다. 중독에서는 강한 인위적 보상에 적응한 나머지 자연 보상에 대한 반응이 약해진 결과다."}, {"h": "재발 예측 인자", "p": "회복 초기의 무쾌감은 재발을 예측하는 중요한 인자다. 즐거움의 부재가 ''무엇을 위해 참는가''라는 회의를 낳아 재발로 이어질 수 있다."}, {"h": "우울과의 중첩", "p": "무쾌감은 중독과 우울이 공존할 때 특히 두드러지며, 둘을 함께 다루는 통합 치료의 필요를 부각한다. 무쾌감의 회복이 지속적 회복의 지표가 되기도 한다."}]'::jsonb, updated_at=now() WHERE id='anhedonia';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "고전적 조건화는 중립적 자극이 보상과 반복 연합되면서, 그 자극만으로도 반응(갈망 등)을 일으키게 되는 학습이다. 파블로프의 실험에서 유래한다."}, {"h": "중독에서 어떻게 작동하나", "p": "특정 장소·사람·도구·시간이 물질 사용과 반복 연합되면, 그 단서만 마주쳐도 갈망이 일어난다. 사용 맥락이 갈망의 방아쇠가 되는 것이 이 학습의 결과다."}, {"h": "왜 중요한가", "p": "조건화된 단서는 오래 지속되어, 사용을 멈춘 뒤에도 단서 노출이 갈망과 재발을 촉발한다. 이것이 ''왜 익숙한 환경에 가면 다시 위험해지는가''를 설명한다."}, {"h": "어떻게 다루나", "p": "단서 회피, 그리고 단서에 반응하지 않도록 하는 소거·재조건화 훈련이 재발예방에 활용된다. 환경을 바꾸는 것이 회복 초기에 중요한 이유이기도 하다."}]'::jsonb, advanced='[{"h": "단서 반응성", "p": "조건화는 물질 단서에 대한 강한 생리·심리 반응(단서 반응성)을 만든다. 이 반응은 갈망·재발의 강력한 예측 인자로, 재발예방의 핵심 표적이다."}, {"h": "소거와 자발적 회복", "p": "단서 반응은 반복 노출로 소거될 수 있으나, 완전히 사라지지 않고 시간·맥락에 따라 되살아나는 ''자발적 회복''을 보인다. 이것이 오랜 뒤에도 재발이 가능한 이유다."}, {"h": "보상 예측과의 통합", "p": "고전적 조건화는 도파민의 보상 예측 신호와 통합되어, 단서가 보상을 예고하며 ''원함''을 끌어내는 기제를 이룬다. 조건화와 인센티브 현저성이 함께 작동한다."}]'::jsonb, updated_at=now() WHERE id='conditioning';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "행동 민감화는 반복 노출로 특정 자극에 대한 반응이 오히려 강해지는 현상이다. 내성(반응 감소)과 반대로, 일부 반응은 시간이 지날수록 증폭된다."}, {"h": "중독에서 어떻게 나타나나", "p": "자극제 등의 반복 사용에서, 물질·단서에 대한 ''원함''과 운동·정서 반응이 강해지는 민감화가 나타난다. 이는 오래 지속되어 재발 취약성을 높인다."}, {"h": "내성과의 공존", "p": "같은 물질에서 어떤 반응은 둔해지고(내성) 어떤 반응은 강해진다(민감화). 특히 ''원함''의 민감화가 갈망을 키우는 것으로 이해된다."}, {"h": "무엇을 시사하나", "p": "민감화는 오래 끊은 뒤에도 단서 노출 시 강한 갈망이 되살아나는 이유를 설명한다. 회복이 ''완치''가 아니라 지속 관리가 필요한 이유의 한 근거다."}]'::jsonb, advanced='[{"h": "인센티브 민감화 이론", "p": "로빈슨과 베리지의 인센티브 민감화 이론은, 반복 사용이 ''원함(wanting)''을 담당하는 회로를 민감화시켜 좋아함과 무관하게 강한 갈망을 만든다고 본다. 중독의 ''즐겁지 않은데도 원함''을 설명하는 핵심 이론이다."}, {"h": "지속성", "p": "민감화는 오래 지속되며, 장기간 금욕 후에도 단서에 의해 재활성화될 수 있다. 이 지속성이 재발 취약성의 신경적 기초로 지목된다."}, {"h": "개인차", "p": "민감화의 정도는 유전·환경·물질에 따라 개인차가 크다. 이 차이가 왜 어떤 사람이 더 쉽게 중독되고 재발하는지를 부분적으로 설명한다."}]'::jsonb, updated_at=now() WHERE id='behavioral-sensitization';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "중독의 유전은 중독 취약성에 유전적 요인이 상당 부분 기여함을 가리킨다. 쌍둥이·가족 연구는 중독 위험의 약 절반가량이 유전적임을 시사한다."}, {"h": "유전이 전부는 아니다", "p": "유전은 ''중독이 정해진다''가 아니라 ''취약성이 높다''를 의미한다. 환경·경험과의 상호작용 속에서 발현되며, 유전적 위험이 있어도 환경에 따라 중독하지 않을 수 있다."}, {"h": "무엇이 유전되나", "p": "특정 물질에 대한 대사·반응 차이, 충동성·보상 민감성 같은 기질, 정신질환 취약성 등이 유전적으로 전달되어 중독 위험에 기여한다. 단일 유전자가 아니라 다수 유전자의 작은 효과가 합쳐진다."}, {"h": "무엇을 시사하나", "p": "유전 이해는 중독이 ''의지박약''이 아님을 보여주고 낙인을 줄인다. 동시에 가족력이 있는 사람의 예방적 주의와 조기 개입의 근거가 된다."}]'::jsonb, advanced='[{"h": "다유전자성", "p": "중독은 소수의 강력한 유전자가 아니라 수많은 유전자의 작은 효과가 합쳐진 다유전자성 형질이다. 이 때문에 단일 ''중독 유전자''는 존재하지 않으며, 다유전자 위험점수 연구가 진행된다."}, {"h": "유전자-환경 상호작용", "p": "유전적 취약성은 스트레스·트라우마·물질 노출 같은 환경과 상호작용해 발현된다. 후성유전학은 환경이 유전자 발현을 조절해 중독 취약성에 영향을 줌을 보여준다."}, {"h": "물질별 특이성과 공통성", "p": "알코올 대사 관련 유전자처럼 특정 물질에 특이적인 요인과, 충동성·보상 민감성처럼 여러 중독에 공통된 요인이 함께 작용한다. 이는 중독의 공통 취약성과 특이 취약성을 함께 시사한다."}]'::jsonb, updated_at=now() WHERE id='genetics-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "충동은 즉각적 쾌를 좇는 자발적 충동이고, 강박은 불안·불편을 줄이려는 반복 행동이다. 중독은 이 둘의 성격을 함께 지닌다."}, {"h": "어떻게 전환되나", "p": "중독은 초기의 충동 주도(쾌락 추구)에서 후기의 강박 주도(고통 회피·습관)로 옮겨간다. 처음엔 재미로 시작한 것이 나중엔 하지 않으면 불안해 어쩔 수 없이 하게 되는 강박으로 바뀐다."}, {"h": "무엇을 의미하나", "p": "이 전환은 중독이 단순한 쾌락 추구가 아님을 보여준다. 후기 중독에서 사용은 즐거움이 아니라 불편·금단을 피하기 위한 것이 된다."}, {"h": "어떻게 다루나", "p": "충동 단계에서는 즉각적 보상에 대한 대처가, 강박 단계에서는 불안·습관을 다루는 접근이 필요하다. 단계에 맞는 개입이 효과적이다."}]'::jsonb, advanced='[{"h": "이중과정 모델", "p": "중독은 충동성(하향식 통제 약화)과 강박성(습관 회로 강화)이 결합된 이중과정으로 설명된다. 이 전환은 뇌의 통제 회로 약화와 습관 회로 강화로 뒷받침된다."}, {"h": "복측에서 배측으로", "p": "반복 사용은 행동 통제가 목표지향적(복측 선조체)에서 습관적·자동적(배측 선조체)으로 이동하는 것과 연관된다. 이 이동이 ''자동화된 강박''의 신경적 기초다."}, {"h": "강박장애와의 구분", "p": "중독의 강박은 강박장애(OCD)의 강박과 유사하지만 다르다. 중독의 반복은 보상·습관에 뿌리를 두는 반면, OCD의 강박은 주로 불안 감소를 목적으로 한다는 차이가 있다."}]'::jsonb, updated_at=now() WHERE id='compulsion-impulse';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "급성 중독(취함)은 물질이 체내에 작용해 나타나는 일시적인 정신·행동·신체 변화 상태다. 도취·판단력 저하·운동 실조·의식 변화 등으로 나타난다."}, {"h": "장기 중독과 다르다", "p": "급성 중독(intoxication)은 한 번의 사용으로 나타나는 일시적 상태이고, 장기 중독(addiction)은 반복으로 형성되는 만성 질환이다. 둘은 구분되는 개념이다."}, {"h": "왜 위험한가", "p": "심한 급성 중독은 사고·판단력 상실·의식소실, 나아가 과용으로 생명을 위협할 수 있다. 물질과 용량에 따라 위험의 양상이 다르다."}, {"h": "무엇을 알면 좋나", "p": "급성 중독의 위험은 물질별로 다르며, 특히 여러 물질을 함께 쓰면 예측 못 한 위험이 커진다. 급성 중독과 중독을 구분하는 것이 개념 이해의 기초다."}]'::jsonb, advanced='[{"h": "용어의 혼동", "p": "영어 ''intoxication''과 ''addiction''이 한국어로 모두 ''중독''으로 번역되며 혼동을 낳는다. 전자는 급성 상태, 후자는 만성 질환으로, 이 구분이 중독 이해의 출발점이다."}, {"h": "응급으로서의 급성 중독", "p": "심한 급성 중독은 기도 확보·호흡 관리 등이 필요한 응급 상황이 될 수 있다. 병용·과용 시 위험이 급증한다."}, {"h": "법·안전과의 연결", "p": "급성 중독 상태의 운전·행위는 안전·법적 문제와 직결된다. 약물운전·음주운전 규제가 이 상태를 겨냥한다."}]'::jsonb, updated_at=now() WHERE id='intoxication';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "과다복용은 신체가 감당할 수 있는 한계를 넘어 물질을 사용해 생명을 위협하는 급성 상태다. 아편류 과용의 호흡억제가 대표적이다."}, {"h": "무엇이 위험을 키우나", "p": "내성 감소 후 재사용, 여러 물질의 혼합, 순도·성분의 불확실성(특히 펜타닐 혼입)이 과용 위험을 크게 높인다. 예상 못 한 강한 용량이 치명적이다."}, {"h": "어떻게 대응하나", "p": "아편류 과용은 날록손으로 되돌릴 수 있어, 신속한 투여와 응급의료 연결이 생명을 구한다. 과용은 즉각적 응급 상황이다."}, {"h": "무엇을 알면 좋나", "p": "과용은 사용자만의 문제가 아니라 주변인의 신속한 대응이 생사를 가른다. 날록손 보급과 사용법 교육이 과용 사망을 줄이는 핵심이다."}]'::jsonb, advanced='[{"h": "호흡억제 기전", "p": "아편류 과용 사망의 대부분은 뇌의 호흡 중추 억제로 일어난다. 억제제·아편류의 병용은 이 억제를 가중해 위험을 배가한다."}, {"h": "내성 감소의 함정", "p": "해독·수감 등으로 한동안 끊어 내성이 떨어진 뒤 예전 용량으로 재사용하면 치명적 과용에 이르기 쉽다. 이 시기가 과용 위험이 가장 높은 때다."}, {"h": "피해감소의 표적", "p": "과용 예방은 피해감소의 핵심 표적이다. 날록손 보급, 안전소비시설, 약물 검사, ''혼자 쓰지 않기'' 교육 등이 과용 사망을 줄이는 근거 있는 수단이다."}]'::jsonb, updated_at=now() WHERE id='overdose';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "약물 상호작용은 둘 이상의 물질이 함께 작용해 효과나 위험이 달라지는 현상이다. 예상치 못한 상호작용이 과용의 흔한 원인이 된다."}, {"h": "왜 위험한가", "p": "억제제끼리, 또는 억제제와 아편류의 병용은 호흡억제를 가중해 특히 위험하다. 각각은 견딜 수 있는 용량도 함께 쓰면 치명적일 수 있다."}, {"h": "어떤 경우가 흔한가", "p": "술과 진정제·아편류, 자극제와 아편류(''스피드볼'') 등의 병용이 위험한 상호작용의 흔한 예다. 처방약과 알코올의 상호작용도 간과되기 쉽다."}, {"h": "무엇을 주의하나", "p": "여러 물질(처방약 포함)을 함께 쓸 때는 상호작용 위험을 반드시 고려해야 한다. 사용자가 인지 못 한 병용이 과용의 숨은 원인인 경우가 많다."}]'::jsonb, advanced='[{"h": "약동학·약력학 상호작용", "p": "상호작용은 물질의 대사·배설이 변하는 약동학적 유형과, 같은 표적에 함께 작용하는 약력학적 유형으로 나뉜다. 억제제 병용의 위험은 후자의 대표 사례다."}, {"h": "상승 효과의 위험", "p": "억제제·아편류의 병용은 개별 효과의 합을 넘는 상승적 위험을 낳는다. 이 비선형성 때문에 ''조금씩 여러 개''가 예상보다 치명적일 수 있다."}, {"h": "다중약물의 시대", "p": "고령화·다약제 복용이 늘며 상호작용 위험도 커진다. 처방 단계의 상호작용 점검과 사용자 교육이 안전의 관건이다."}]'::jsonb, updated_at=now() WHERE id='drug-interactions';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "다중물질 사용은 여러 물질을 함께 또는 번갈아 사용하는 것으로, 상호작용으로 위험이 커지고 치료가 복잡해진다."}, {"h": "왜 그렇게 쓰나", "p": "한 물질의 부작용을 다른 물질로 상쇄하려는 패턴이 흔하다. 자극제로 각성했다가 억제제로 잠들고, 다시 자극제를 찾는 식의 순환이 대표적이다."}, {"h": "왜 위험한가", "p": "물질 간 상호작용이 예측 못 한 위험을 만들고, 특히 억제제·아편류의 병용은 과용 위험을 크게 높인다. 최근 자극제와 펜타닐의 혼합이 새로운 위협이다."}, {"h": "치료의 어려움", "p": "여러 물질에 동시에 의존하면 해독·치료가 복잡해진다. 한 물질만 다루면 다른 물질로 옮겨갈 수 있어, 통합적 접근이 필요하다."}]'::jsonb, advanced='[{"h": "의도적·비의도적 병용", "p": "다중물질 사용은 효과를 조절하려는 의도적 병용과, 불법 약물에 다른 물질이 섞인 비의도적 병용을 모두 포함한다. 후자(펜타닐 혼입 등)가 최근 과용 위기의 핵심이다."}, {"h": "치료 설계의 과제", "p": "다중물질 사용자는 단일 물질 중심의 치료 모델에 잘 맞지 않는다. 물질별 위험을 함께 다루는 통합적·개별화된 접근이 요구된다."}, {"h": "과용의 복합성", "p": "여러 물질이 관여한 과용은 원인 물질을 특정하기 어렵고 대응도 복잡하다. 자일라진처럼 날록손이 듣지 않는 성분의 혼합이 대응을 더 어렵게 한다."}]'::jsonb, updated_at=now() WHERE id='polysubstance';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "플래시백은 환각제 사용 후 물질 없이도 과거의 지각 경험이 갑자기 되살아나는 현상이다. 트라우마의 침습적 재경험을 가리킬 때도 쓰인다."}, {"h": "어떻게 나타나나", "p": "환각제 경험 이후 한참 뒤에도 시야의 잔상·왜곡 같은 지각 이상이 불쑥 나타날 수 있다. 대개 일시적이지만 반복되면 불안을 준다."}, {"h": "지속되면", "p": "지각 이상이 지속·반복되면 지각장애(HPPD)로 이어질 수 있다. 다만 이는 상대적으로 드물고, 대부분의 지각 변화는 시간이 지나며 사라진다."}, {"h": "트라우마의 플래시백", "p": "플래시백은 PTSD에서 트라우마 기억이 생생하게 재경험되는 것을 가리키기도 한다. 이 경우 중독과 트라우마가 얽히는 지점이 된다."}]'::jsonb, advanced='[{"h": "HPPD", "p": "지속성 지각장애(HPPD)는 환각제 사용 후 지각 이상이 오래 지속되는 상태다. 빈도·기전이 충분히 규명되지 않았으나, 일부에게 상당한 고통을 준다."}, {"h": "두 가지 의미", "p": "''플래시백''은 환각제 후 지각 재현과 트라우마 재경험이라는 서로 다른 현상을 가리킨다. 맥락에 따라 의미가 다르며, 트라우마 플래시백은 중독의 자가치료 동기와 연결된다."}, {"h": "불안과의 악순환", "p": "플래시백에 대한 불안이 그 자체로 경험을 악화시킬 수 있다. 안심시키기와 불안 관리가 대처의 핵심이 된다."}]'::jsonb, updated_at=now() WHERE id='flashbacks';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "숙취는 과음 후 나타나는 두통·메스꺼움·피로·인지 저하 등의 후유 상태다. 일종의 가벼운 금단·독성 반응으로 이해된다."}, {"h": "무엇이 원인인가", "p": "탈수, 수면 방해, 알코올 대사산물(아세트알데히드 등), 염증 반응 등이 복합적으로 작용한다. 단일 원인이 아니라 여러 기제가 겹친다."}, {"h": "무엇을 의미하나", "p": "숙취는 알코올이 몸에 준 부담의 신호다. 반복되는 심한 숙취는 음주 패턴을 돌아볼 계기가 될 수 있다."}, {"h": "무엇을 알면 좋나", "p": "확실한 해소법은 없으며, 수분 보충과 휴식이 도움이 된다. ''해장술''은 금단을 잠시 미룰 뿐 문제를 키우며, 의존의 신호일 수 있다."}]'::jsonb, advanced='[{"h": "경미한 금단으로서의 이해", "p": "숙취의 일부 증상은 알코올이 빠지며 나타나는 경미한 반동(금단)으로 볼 수 있다. 이는 알코올이 온화해 보여도 신경 적응을 일으킴을 보여준다."}, {"h": "개인차", "p": "숙취의 정도는 유전(알코올 대사 관련)·수분·수면·병용 물질에 따라 개인차가 크다. 대사 효소의 차이가 숙취 취약성에 영향을 준다."}, {"h": "사회·경제적 영향", "p": "숙취로 인한 생산성 저하·사고는 상당한 사회적 비용을 낳는다. 개인의 불편을 넘어선 공중보건적 관심사이기도 하다."}]'::jsonb, updated_at=now() WHERE id='hangover';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "블랙아웃(필름 끊김)은 음주 중 의식은 있으나 그 시간의 기억이 형성되지 않는 현상이다. 알코올이 해마의 기억 저장을 방해해 발생한다."}, {"h": "어떻게 나타나나", "p": "대화·이동 등 행동은 하지만, 다음 날 그 시간을 전혀 기억하지 못한다. 부분적으로 기억이 조각나는 경우와 완전히 사라지는 경우가 있다."}, {"h": "왜 위험한가", "p": "블랙아웃 중에는 위험한 상황을 기억하지 못해 안전 문제로 이어질 수 있다. 판단·기억이 손상된 상태에서의 행동이 사고·피해로 연결된다."}, {"h": "무엇을 의미하나", "p": "블랙아웃은 혈중 알코올이 빠르게 높아졌다는 신호이며, 반복되는 블랙아웃은 위험한 음주 패턴과 알코올 관련 문제의 지표일 수 있다."}]'::jsonb, advanced='[{"h": "기억 형성의 차단", "p": "블랙아웃은 알코올이 해마의 장기기억 저장(응고화)을 방해해 발생한다. 의식·단기기억은 유지되지만 새로운 기억이 저장되지 않는 것이 특징이다."}, {"h": "혈중농도 급상승", "p": "블랙아웃은 혈중 알코올 농도가 빠르게 상승할 때 잘 발생한다. 빈속에 급히 마시거나 폭음할 때 위험이 커진다."}, {"h": "위험 지표로서의 의미", "p": "잦은 블랙아웃은 알코올사용장애 위험과 관련되며, 특히 젊은 층의 폭음에서 경고 신호로 다뤄진다. 안전·법적 문제와도 직결된다."}]'::jsonb, updated_at=now() WHERE id='blackout';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "신경가소성은 경험과 학습에 따라 뇌의 연결과 기능이 변화하는 성질이다. 뇌가 고정된 것이 아니라 계속 변한다는 원리다."}, {"h": "중독과의 관계", "p": "중독은 이 가소성이 물질·행동을 중심으로 재편된 결과다. 반복 사용이 관련 신경 연결을 강화해, 그 행동이 점점 자동화·강박화된다."}, {"h": "회복의 근거", "p": "같은 가소성이 회복도 가능하게 한다. 사용을 멈추고 새로운 경험·관계·기술을 쌓으면 뇌가 다시 변화한다. 이것이 회복이 가능하다는 신경과학적 희망의 근거다."}, {"h": "무엇을 시사하나", "p": "중독이 뇌를 바꾼 것처럼, 회복의 새로운 학습이 뇌를 다시 바꿔 갈 수 있다. 다만 변화에는 시간과 반복된 경험이 필요하다."}]'::jsonb, advanced='[{"h": "학습으로서의 중독", "p": "가소성 관점은 중독을 ''병리적 학습''으로 본다. 보상 학습이 지나치게 강화되어 굳어진 것이 중독이며, 이는 순수 질병모델과 학습모델을 잇는 관점이다."}, {"h": "회복의 재학습", "p": "회복은 기존의 병리적 연결을 약화시키고 새로운 적응적 연결을 강화하는 재학습 과정으로 이해된다. 새로운 습관·관계·의미가 이 재학습의 재료다."}, {"h": "결정적 시기와 취약성", "p": "청소년기는 가소성이 높아 학습이 빠른 만큼 중독에도 취약하다. 이 시기의 물질 노출이 특히 위험한 이유이자, 예방이 중요한 근거다."}]'::jsonb, updated_at=now() WHERE id='neuroplasticity';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "인센티브 현저성은 보상과 연합된 단서가 강한 ''원함(wanting)''을 끌어내도록 뇌가 부여하는 동기적 두드러짐이다."}, {"h": "원함과 좋아함", "p": "이 개념의 핵심은 ''원함(wanting)''과 ''좋아함(liking)''의 분리다. 좋아하지 않아도, 즐겁지 않아도 강하게 원하게 되는 것이 인센티브 현저성의 작용이다."}, {"h": "중독을 어떻게 설명하나", "p": "반복 사용이 물질·단서에 과도한 현저성을 부여해, 그것이 다른 무엇보다 강렬하게 ''원해지도록'' 만든다. 사용이 더는 즐겁지 않은데도 갈망하는 중독의 역설을 설명한다."}, {"h": "무엇을 시사하나", "p": "이 관점은 중독을 쾌락 추구가 아니라 왜곡된 동기의 문제로 본다. 그래서 회복은 즐거움의 회복만이 아니라 동기·현저성의 재조정을 포함한다."}]'::jsonb, advanced='[{"h": "이론적 배경", "p": "인센티브 현저성은 로빈슨과 베리지의 인센티브 민감화 이론의 핵심 개념이다. 반복 사용이 ''원함'' 회로를 민감화시켜, 좋아함과 무관한 강렬한 갈망을 만든다고 본다."}, {"h": "도파민의 역할", "p": "도파민은 쾌락(좋아함)보다 ''원함''과 현저성 귀인에 관여한다. 이 구분이 ''도파민=쾌락''이라는 통념을 교정하고 중독의 동기적 본질을 조명한다."}, {"h": "단서와 재발", "p": "현저성이 부여된 단서는 오래 지속되어, 금욕 후에도 강한 갈망과 재발을 촉발한다. 이 지속성이 중독을 만성 질환으로 만드는 기제의 하나다."}]'::jsonb, updated_at=now() WHERE id='incentive-salience';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "알로스타시스는 반복 사용으로 뇌의 보상·스트레스 균형점 자체가 이동해, 정상적으로 느끼기 위해 물질이 필요해지는 상태를 설명하는 이론이다."}, {"h": "어떻게 작동하나", "p": "처음엔 기분을 좋게 하려고 쓰지만, 반복되면 뇌의 기준선이 낮아진다. 나중엔 무너진 기준선을 겨우 정상으로 되돌리려 쓰게 되는 변화가 일어난다."}, {"h": "''어두운 면''", "p": "이 이론은 쾌락 추구에서 불쾌 회피로 동기가 옮겨가는 후기 중독의 ''어두운 면''을 개념화한다. 사용의 목적이 고양이 아니라 고통 회피가 되는 것이다."}, {"h": "무엇을 시사하나", "p": "알로스타시스는 후기 중독의 만성적 불쾌·갈망과, 회복 초기의 무쾌감을 이해하는 틀을 제공한다. 회복이 기준선의 회복을 포함하는 시간이 걸리는 과정임을 보여준다."}]'::jsonb, advanced='[{"h": "항상성을 넘어", "p": "알로스타시스는 항상성(고정된 기준으로의 복귀)과 달리, 기준점 자체가 이동해 새로운 ''병리적 균형''에 이르는 것을 뜻한다. 반복적 신경적응이 누적된 결과다."}, {"h": "반대 과정과 스트레스 체계", "p": "이 이론은 보상의 반대 과정(대응 반응)과 뇌 스트레스 체계(CRF 등)의 활성화를 강조한다. 이 변화가 금단의 부정 정서와 갈망을 만든다."}, {"h": "쿠브의 기여", "p": "조지 쿠브 등이 정립한 이 관점은 중독의 부적 강화(고통 회피) 차원을 조명하며, 보상 중심 모델을 보완한다. 후기 중독 이해의 중요한 축이다."}]'::jsonb, updated_at=now() WHERE id='allostasis';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "세트와 세팅은 물질 경험이 개인의 심리 상태(set)와 물리·사회적 환경(setting)에 크게 좌우된다는 개념이다. 특히 환각제에서 중요하다."}, {"h": "왜 중요한가", "p": "같은 물질·용량도 마음 상태와 환경에 따라 전혀 다른 경험을 낳는다. 안전하고 지지적인 환경에서의 경험과 불안한 환경에서의 경험이 극단적으로 달라질 수 있다."}, {"h": "치료적 함의", "p": "사이키델릭 보조치료가 통제된 환경, 준비, 치료자 동반을 강조하는 것은 세트와 세팅의 원리 때문이다. 물질 자체보다 맥락이 경험과 결과를 좌우한다."}, {"h": "무엇을 시사하나", "p": "세트와 세팅은 중독·약물 경험이 순수하게 약리적이지 않고 맥락 의존적임을 보여준다. 이는 환경을 바꾸는 것이 회복에 중요한 이유와도 통한다."}]'::jsonb, advanced='[{"h": "맥락 의존성", "p": "세트와 세팅은 약물 효과가 약리적 요인과 맥락적 요인의 상호작용임을 보여준다. 이 원리는 위약 효과, 환경에 따른 내성 변화 등 여러 현상과 연결된다."}, {"h": "치료 설계의 원리", "p": "사이키델릭 치료는 세트(준비·기대)와 세팅(안전한 공간·동반)을 정교하게 설계한다. 통제된 세트와 세팅이 치료 효과와 안전의 핵심 조건이 된다."}, {"h": "오락적 사용의 위험", "p": "통제되지 않은 세트와 세팅(불안한 상태, 위험한 환경)에서의 사용은 배드 트립·사고 위험을 높인다. 이 원리가 자가 사용의 위험을 설명한다."}]'::jsonb, updated_at=now() WHERE id='set-and-setting';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "투여 경로는 물질이 몸에 들어오는 방식(경구·흡입·주사·점막 등)이다. 같은 물질도 경로에 따라 효과의 속도·강도·위험이 크게 달라진다."}, {"h": "속도가 위험을 가른다", "p": "빠르게 뇌에 도달하는 경로일수록 도취와 의존 위험이 크다. 주사·흡입은 경구보다 빠르고 강한 효과를 내며, 그만큼 의존 위험이 높다."}, {"h": "경로별 위험", "p": "주사는 감염(HIV·간염)과 혈관 손상 위험을 더하고, 흡입은 폐 손상을, 비강 흡입은 점막 손상을 유발한다. 경로마다 고유한 부가 위험이 있다."}, {"h": "무엇을 시사하나", "p": "같은 물질도 ''어떻게 쓰느냐''가 위험을 좌우한다. 이 원리는 더 안전한 사용 방법을 안내하는 피해감소의 근거가 된다."}]'::jsonb, advanced='[{"h": "약동학과 의존", "p": "투여 경로는 물질이 뇌에 도달하는 속도(약동학)를 결정하고, 이 속도가 보상의 강도와 의존 형성에 직접 영향을 준다. 빠른 전달이 강한 강화를 낳는다."}, {"h": "경로 전환의 위험", "p": "의존이 진행되며 더 빠르고 강한 경로(경구→흡입→주사)로 전환되는 경향이 있고, 이는 위험의 증가를 의미한다. 경로 전환은 중독 심화의 신호일 수 있다."}, {"h": "피해감소와 경로", "p": "주사 사용의 감염 위험을 줄이는 주사기 교환, 흡연 도구 제공 등은 경로별 위험을 겨냥한 피해감소다. ''무엇을''만이 아니라 ''어떻게''를 다루는 접근이다."}]'::jsonb, updated_at=now() WHERE id='drug-administration';
-- ===== psychology =====
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "조작적 조건화는 행동의 결과(보상 또는 처벌)가 그 행동의 반복 가능성을 높이거나 낮추는 학습 원리다. 스키너의 실험에서 유래한다."}, {"h": "중독에서 어떻게 작동하나", "p": "물질·행동이 즉각적 쾌락이나 불편 완화라는 보상을 제공하면 그 행동이 강화된다. 이 반복된 강화가 중독 행동의 학습적 기초다."}, {"h": "즉각성이 핵심", "p": "조작적 조건화에서는 보상이 즉각적이고 확실할수록 행동이 강하게 강화된다. 중독 물질의 빠르고 확실한 보상이 강한 학습을 일으키는 이유다."}, {"h": "치료에의 응용", "p": "이 원리를 역이용해, 회복 행동에 즉각적 보상을 주는 유관관리 치료가 개발됐다. 처벌보다 바람직한 행동의 강화가 효과적임이 알려져 있다."}]'::jsonb, advanced='[{"h": "강화 스케줄", "p": "보상이 주어지는 방식(스케줄)이 행동의 강도·지속성을 좌우한다. 특히 언제 올지 모르는 변동비율 강화가 가장 끈질긴 행동을 만들며, 도박 중독의 핵심 원리다."}, {"h": "정적·부적 강화", "p": "행동은 보상 획득(정적 강화)뿐 아니라 불쾌 제거(부적 강화)로도 강화된다. 후기 중독의 금단 회피가 부적 강화의 대표 사례다."}, {"h": "행동 치료의 토대", "p": "조작적 조건화는 유관관리·재발예방 등 근거 기반 행동 치료의 이론적 토대다. 중독을 학습된 행동으로 보는 관점의 핵심이다."}]'::jsonb, updated_at=now() WHERE id='operant-conditioning';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "강화는 특정 행동의 재발 가능성을 높이는 과정이다. 보상을 얻는 정적 강화와 불쾌를 제거하는 부적 강화로 나뉜다."}, {"h": "정적 강화", "p": "정적 강화는 행동 뒤에 보상(쾌락·고양감)이 따라와 그 행동이 늘어나는 것이다. 초기 중독에서 물질의 쾌락이 사용을 강화하는 방식이다."}, {"h": "부적 강화", "p": "부적 강화는 행동이 불쾌(금단·불안·고통)를 없애줘서 늘어나는 것이다. 후기 중독에서 금단·고통을 피하려 사용하는 것이 부적 강화다."}, {"h": "무엇을 시사하나", "p": "중독은 정적 강화(쾌락 추구)에서 부적 강화(고통 회피)로 무게가 옮겨가는 과정이다. 이 전환의 이해가 후기 중독과 회복을 다루는 데 중요하다."}]'::jsonb, advanced='[{"h": "이중 강화의 전환", "p": "중독의 진행은 정적 강화 주도에서 부적 강화 주도로의 전환으로 설명된다. 이는 알로스타시스·''어두운 면'' 이론과 연결되며, 후기 중독의 만성적 고통을 조명한다."}, {"h": "처벌의 한계", "p": "처벌(정적·부적)은 행동을 억제할 수 있으나, 중독에서는 효과가 제한적이고 낙인·회피를 낳기 쉽다. 이 때문에 처벌보다 대안 강화가 강조된다."}, {"h": "자연 보상의 회복", "p": "회복은 물질의 인위적 강화를 자연적 보상(관계·성취·의미)의 강화로 대체하는 과정으로 볼 수 있다. 대안적 강화원의 회복이 지속적 회복의 열쇠다."}]'::jsonb, updated_at=now() WHERE id='reinforcement';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "자가치료 가설은 중독을 단순한 쾌락 추구가 아니라, 감당하기 힘든 정서적 고통을 스스로 다스리려는 시도로 보는 정신역동적 관점이다."}, {"h": "어떻게 설명하나", "p": "불안·우울·분노·공허 같은 고통을 완화해 주는 물질을 선택해 쓴다는 것이다. 사람마다 특정 물질에 끌리는 이유가 그 물질이 완화해 주는 정서와 맞아떨어지기 때문이라고 본다."}, {"h": "무엇을 시사하나", "p": "이 관점은 ''왜 하필 이 물질인가'', ''무엇을 달래려 하는가''에 주목한다. 중독 뒤에 있는 고통을 다루지 않으면 회복이 지속되기 어렵다는 통찰을 준다."}, {"h": "치료에의 함의", "p": "자가치료 가설은 물질 사용의 기저에 있는 정서적 고통·트라우마·정신질환을 함께 다루는 통합 치료의 근거가 된다. 증상만이 아니라 원인을 보게 한다."}]'::jsonb, advanced='[{"h": "칸치안의 이론", "p": "자가치료 가설은 칸치안 등이 정교화한 정신역동 이론으로, 물질 선택이 무작위가 아니라 개인의 정서적 고통과 맞물린다고 본다. 물질과 정서의 ''적합성''을 강조한다."}, {"h": "공존질환과의 연결", "p": "이 가설은 우울·불안·PTSD 등과 중독의 높은 공존을 설명하는 틀을 제공한다. 정신질환의 고통을 물질로 달래려는 시도가 이중진단으로 이어진다는 것이다."}, {"h": "근거와 한계", "p": "자가치료 가설은 임상적으로 설득력 있으나, 모든 중독을 설명하진 못하며 인과의 방향(고통이 사용을 부르는지, 사용이 고통을 키우는지)이 복잡하다. 보상·학습 모델과 상호보완적으로 이해된다."}]'::jsonb, updated_at=now() WHERE id='self-medication';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "애착이론과 중독은 초기 양육자와의 애착 경험이 이후 정서 조절과 관계 능력에 영향을 주며, 불안정 애착이 중독 취약성과 연결된다는 관점이다."}, {"h": "어떻게 연결되나", "p": "안정적 애착을 형성하지 못하면 정서를 스스로 달래는 능력이 약해지고, 그 공백을 물질이나 행동이 대신 메우기도 한다. 중독을 ''관계의 대체물''로 보는 시각이다."}, {"h": "무엇을 시사하나", "p": "중독이 사람과의 안정적 연결의 결핍과 관련된다는 관점은, 회복이 관계와 소속의 회복을 포함해야 함을 시사한다. ''중독의 반대는 연결''이라는 통찰과 통한다."}, {"h": "치료에의 함의", "p": "애착 관점은 치료 관계 자체가 교정적 경험이 될 수 있음을 강조한다. 안전한 관계 속에서 정서 조절을 다시 배우는 것이 회복의 일부가 된다."}]'::jsonb, advanced='[{"h": "정서 조절의 발달", "p": "애착이론은 정서 조절 능력이 초기 관계에서 발달함을 강조한다. 불안정 애착에서 자기 진정 능력이 약하게 형성되면, 외부 물질에 의존해 정서를 조절하려는 취약성이 생긴다."}, {"h": "연결로서의 회복", "p": "이 관점에서 회복은 물질과의 관계를 사람·공동체와의 안정적 관계로 대체하는 과정이다. 회복 공동체의 소속감이 치료적 힘을 갖는 이유를 설명한다."}, {"h": "트라우마와의 교차", "p": "애착 손상은 흔히 유년기 트라우마와 얽혀 있어, 애착 관점은 트라우마 기반 접근과 만난다. 관계·정서·트라우마를 함께 다루는 통합적 회복을 시사한다."}]'::jsonb, updated_at=now() WHERE id='attachment-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "유년기 부정적 경험(ACE)·트라우마는 중독의 강력한 위험 요인이다. 학대·방임·가정 역기능 같은 초기 역경이 이후 중독 취약성을 크게 높인다."}, {"h": "어떻게 연결되나", "p": "트라우마가 남긴 정서적 고통·과각성·수치심을 달래려는 시도가 물질 사용으로 이어진다. 중독이 트라우마의 고통에 대한 대처(자가치료)로 기능하는 것이다."}, {"h": "ACE 연구", "p": "대규모 ACE 연구는 유년기 역경의 수가 많을수록 이후 중독·정신질환·신체질환 위험이 비례해 높아짐을 보여준다. 초기 경험이 평생의 건강에 영향을 준다는 근거다."}, {"h": "치료에의 함의", "p": "트라우마와 중독을 함께 다루는 통합 치료가 권장된다. 트라우마를 다루지 않으면 중독 치료가 지속되기 어렵고, 그 반대도 마찬가지다."}]'::jsonb, advanced='[{"h": "트라우마 기반 돌봄", "p": "''무엇이 문제인가'' 대신 ''무슨 일이 있었는가''를 묻는 트라우마 기반 접근이 중독 치료에 확산되고 있다. 이는 안전·신뢰·선택을 강조하며 재트라우마화를 피한다."}, {"h": "신경생물학적 경로", "p": "초기 트라우마는 스트레스 반응 체계(HPA축)와 뇌 발달을 변화시켜, 정서 조절·충동 조절의 취약성을 남긴다. 이 변화가 중독 취약성의 생물학적 매개가 된다."}, {"h": "수치심과 회복", "p": "트라우마와 얽힌 중독의 핵심에는 수치심이 있다. 낙인과 수치심을 다루는 비판단적 접근이 회복의 전제가 되며, 이는 당사자·공동체 관점과 통한다."}]'::jsonb, updated_at=now() WHERE id='trauma-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "방어기제는 불안·고통스러운 감정으로부터 자신을 보호하기 위해 무의식적으로 작동하는 심리적 책략이다. 정신분석에서 유래한 개념이다."}, {"h": "중독에서 어떻게 나타나나", "p": "부정(문제 없다고 믿기), 합리화(그럴듯한 이유 대기), 최소화(별것 아니라 여기기), 투사(남 탓하기) 같은 방어가 중독 문제를 직면하지 못하게 한다."}, {"h": "왜 중요한가", "p": "방어기제는 당사자가 문제를 인정하고 도움을 청하는 것을 가로막는다. 이 방어를 이해하는 것이 저항을 다루고 변화를 돕는 데 중요하다."}, {"h": "어떻게 다루나", "p": "방어를 정면으로 깨뜨리려 하기보다, 위협을 낮추고 스스로 직면할 수 있도록 돕는 접근(동기강화상담 등)이 효과적이다. 방어는 고통에 대한 보호임을 이해하는 것이 출발이다."}]'::jsonb, advanced='[{"h": "적응과 병리의 경계", "p": "방어기제는 원래 고통을 견디게 하는 적응적 기능을 한다. 그러나 중독에서는 이 방어가 문제 직면과 회복을 가로막는 병리적 역할을 하게 된다."}, {"h": "성숙도의 스펙트럼", "p": "방어는 부정·투사 같은 미성숙한 것부터 승화·유머 같은 성숙한 것까지 스펙트럼을 이룬다. 회복 과정은 미성숙한 방어에서 성숙한 대처로의 이동을 포함한다."}, {"h": "저항의 재해석", "p": "현대적 관점은 ''저항''을 당사자의 문제가 아니라 위협에 대한 자연스러운 반응이자 상담 관계의 신호로 재해석한다. 방어를 존중하며 다루는 것이 변화를 촉진한다."}]'::jsonb, updated_at=now() WHERE id='defense-mechanisms';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "부정은 중독 문제의 존재나 심각성을 인정하지 않는 심리 상태다. 중독의 대표적 특징이자 회복의 첫 장벽으로 꼽힌다."}, {"h": "왜 나타나나", "p": "문제를 인정하는 것이 주는 수치심·두려움·상실감으로부터 자신을 보호하려는 무의식적 방어다. 또 중독 자체가 판단·자각 능력을 손상시켜 부정을 강화한다."}, {"h": "어떻게 나타나나", "p": "''나는 언제든 끊을 수 있다'', ''남들만큼 마신다'', ''문제는 다른 데 있다'' 같은 형태로 나타난다. 명백한 피해에도 문제를 축소·부인한다."}, {"h": "어떻게 다루나", "p": "부정을 비난하거나 강제로 깨려 하면 저항만 키운다. 위협을 낮추고 스스로 모순을 자각하도록 돕는 접근(동기강화상담)이 효과적이다."}]'::jsonb, advanced='[{"h": "방어이자 증상", "p": "부정은 심리적 방어인 동시에, 중독이 손상시킨 자기 인식(질병인식결여)의 결과이기도 하다. 순수한 ''거짓말''이 아니라 실제로 문제를 지각하지 못하는 측면이 있다."}, {"h": "직면 논쟁", "p": "과거의 강한 직면(confrontation) 방식은 부정을 깨려 했으나, 저항과 관계 손상을 낳는다는 비판을 받았다. 현대에는 공감적·비대립적 접근이 더 효과적으로 여겨진다."}, {"h": "양가감정으로 보기", "p": "부정을 완고한 벽이 아니라 변화에 대한 양가감정으로 이해하면, 그 안의 변화 동기를 끌어낼 여지가 보인다. 이것이 동기강화상담의 핵심 통찰이다."}]'::jsonb, updated_at=now() WHERE id='denial';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "강박적 반복은 고통스러운 경험이나 관계 패턴을 무의식적으로 반복하는 경향을 가리키는 정신분석 개념이다. 프로이트가 제시했다."}, {"h": "중독과 어떻게 연결되나", "p": "중독의 반복적·자기파괴적 사용은 강박적 반복의 한 형태로 해석되기도 한다. 해가 되는 줄 알면서도 같은 패턴을 반복하는 것이 이 개념과 맞물린다."}, {"h": "무엇을 시사하나", "p": "이 관점은 중독의 반복을 단순한 보상 추구를 넘어, 해결되지 않은 심리적 갈등이나 트라우마의 재연으로 본다. 반복 뒤에 있는 무의식적 의미에 주목한다."}, {"h": "치료에의 함의", "p": "강박적 반복 관점은 반복되는 패턴의 의미를 탐색하고, 무의식적으로 재연되던 것을 의식화해 다루는 접근을 시사한다. 통찰이 반복의 고리를 끊는 데 도움이 될 수 있다."}]'::jsonb, advanced='[{"h": "정신분석적 기원", "p": "강박적 반복은 프로이트가 쾌락원칙을 넘어서는 현상으로 제시한 개념이다. 쾌락만으로는 설명되지 않는 고통스러운 반복의 존재를 가리킨다."}, {"h": "트라우마 재연", "p": "이 개념은 트라우마의 무의식적 재연과 연결된다. 해결되지 않은 초기 경험이 관계·행동에서 반복적으로 재연된다는 관점은 트라우마 기반 접근과 만난다."}, {"h": "현대적 재해석", "p": "강박적 반복은 오늘날 습관 회로의 자동화, 조건화된 반응 등 학습·신경과학 개념과 함께 재해석되기도 한다. 정신역동적 의미와 행동적 기제가 상호보완적으로 논의된다."}]'::jsonb, updated_at=now() WHERE id='repetition-compulsion';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "쾌락원칙은 즉각적 쾌락을 추구하고 고통을 피하려는 심리 경향이고, 현실원칙은 현실의 요구에 맞춰 만족을 지연·조절하는 능력이다. 프로이트의 개념이다."}, {"h": "중독과 어떻게 연결되나", "p": "중독은 쾌락원칙이 현실원칙을 압도한 상태로 볼 수 있다. 즉각적 만족(물질)이 장기적 결과에 대한 고려를 밀어내는 것이다."}, {"h": "무엇을 시사하나", "p": "이 관점은 중독을 ''만족을 지연하는 능력의 약화''로 이해한다. 지금의 쾌락이 미래의 대가를 압도하는 불균형이 중독의 핵심이라는 통찰을 준다."}, {"h": "발달과의 관계", "p": "현실원칙은 발달 과정에서 형성되는 능력이다. 이 능력을 키우는 것—만족을 지연하고 충동을 조절하는 법을 배우는 것—이 회복과 예방의 한 축이 된다."}]'::jsonb, advanced='[{"h": "지연 할인과의 연결", "p": "쾌락원칙 대 현실원칙의 긴장은 현대의 ''지연 할인'' 개념으로 이어진다. 미래 보상의 가치를 급격히 낮게 평가하는 경향이 중독에서 두드러진다."}, {"h": "자아 기능으로서의 조절", "p": "현실원칙은 정신분석에서 자아의 기능으로, 충동과 현실을 중재한다. 중독은 이 중재 기능(신경적으로는 전전두 통제)의 약화와 연결된다."}, {"h": "이론적 다리", "p": "쾌락원칙/현실원칙은 정신분석 개념과 신경과학의 보상·통제 회로 논의를 잇는 다리 역할을 한다. 오래된 개념이 현대 중독 이해와 공명하는 지점이다."}]'::jsonb, updated_at=now() WHERE id='pleasure-principle';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "지연 할인은 미래의 보상보다 즉각적 보상을 훨씬 높게 평가하는 경향이다. 만족을 지연하지 못하고 지금의 작은 보상을 택하는 것이다."}, {"h": "중독과 어떻게 연결되나", "p": "중독자는 흔히 미래 보상의 가치를 급격히 할인해, 장기적 손해를 알면서도 즉각적 물질 보상을 택한다. 높은 지연 할인율이 중독의 특징적 인지 패턴이다."}, {"h": "무엇을 시사하나", "p": "이 개념은 중독을 ''의지박약''이 아니라 ''보상을 평가하는 방식의 왜곡''으로 이해하게 한다. 미래가 현재보다 지나치게 평가절하되는 것이 문제의 핵심이다."}, {"h": "측정과 활용", "p": "지연 할인은 실험으로 측정 가능하며, 중독의 심각도·재발 위험과 연관된다. 만족 지연 능력을 훈련하는 것이 개입의 한 방향이 된다."}]'::jsonb, advanced='[{"h": "충동성의 지표", "p": "높은 지연 할인율은 충동성의 행동경제학적 지표로, 여러 중독에 걸쳐 관찰된다. 이는 중독의 공통 취약성으로서 충동성의 역할을 뒷받침한다."}, {"h": "상태와 특성", "p": "지연 할인은 안정적 기질(특성)이면서 동시에 갈망·박탈 상태에서 더 가팔라지는 상태 의존적 측면도 있다. 이 이중성이 개입의 여지를 시사한다."}, {"h": "개입 가능성", "p": "일부 연구는 미래를 구체적으로 상상하게 하는 훈련(에피소드적 미래 사고) 등이 지연 할인을 완화할 수 있음을 보고한다. 인지 훈련을 통한 개입 가능성이 탐색되고 있다."}]'::jsonb, updated_at=now() WHERE id='delay-discounting';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "사회학습이론은 사람이 타인의 행동을 관찰·모방하고, 그 결과를 보며 학습한다는 이론이다. 반두라가 제시했다."}, {"h": "중독에서 어떻게 작동하나", "p": "가족·또래의 물질 사용을 관찰·모방하고, 그것이 보상받는 것을 보며 사용을 학습한다. 특히 또래 영향은 청소년기 물질 사용 시작의 강력한 요인이다."}, {"h": "무엇을 시사하나", "p": "중독이 개인의 문제만이 아니라 사회적 환경 속에서 학습됨을 보여준다. 롤모델, 또래, 미디어의 영향이 사용 행동에 크게 작용한다."}, {"h": "예방에의 함의", "p": "사회학습 관점은 또래·미디어 환경, 거절 기술 훈련, 건강한 롤모델의 중요성을 강조한다. 개인만이 아니라 사회적 맥락을 겨냥한 예방의 근거가 된다."}]'::jsonb, advanced='[{"h": "관찰학습과 모델링", "p": "사회학습은 직접 경험 없이도 타인을 관찰함으로써 학습이 일어남을 강조한다. 물질 사용이 보상받는 것을 보는 것만으로도 사용 기대와 행동이 형성될 수 있다."}, {"h": "자기효능감과의 연결", "p": "반두라의 이론은 자기효능감 개념으로 확장된다. ''내가 유혹을 견딜 수 있다''는 믿음이 행동을 좌우하며, 이는 재발예방의 핵심 표적이 된다."}, {"h": "미디어와 규범", "p": "사회학습 관점은 미디어의 물질 묘사와 사회적 규범이 사용에 미치는 영향을 조명한다. 음주·흡연을 정상화하는 문화적 메시지가 학습 환경의 일부다."}]'::jsonb, updated_at=now() WHERE id='social-learning';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "결과기대는 특정 물질·행동이 어떤 결과를 가져올 것이라는 개인의 믿음이다. ''이걸 마시면 긴장이 풀린다'' 같은 기대가 행동을 이끈다."}, {"h": "중독에서 어떻게 작동하나", "p": "물질에 대한 긍정적 기대(이완·즐거움·자신감)가 사용 동기를 높이고, 이 기대가 실제 경험을 형성하기도 한다. 기대 자체가 효과의 일부가 되는 것이다."}, {"h": "무엇을 시사하나", "p": "같은 물질도 무엇을 기대하는지에 따라 경험과 사용 패턴이 달라진다. 왜곡된 기대(예: ''술이 문제를 해결해 준다'')가 사용을 지속시킨다."}, {"h": "치료에의 함의", "p": "비현실적 긍정 기대를 검토하고 수정하는 것이 인지행동치료의 한 부분이다. 기대를 바꾸는 것이 행동 변화로 이어질 수 있다."}]'::jsonb, advanced='[{"h": "기대가 효과를 만든다", "p": "알코올 기대 연구는 사람들이 술을 마셨다고 ''믿을'' 때(실제로는 아니어도) 기대에 부합하는 행동을 보임을 밝혔다. 이는 위약 효과와 통하는, 기대의 강력한 힘을 보여준다."}, {"h": "기대의 발달", "p": "물질 기대는 사용 이전부터 사회학습을 통해 형성된다. 어린 시절부터 형성된 기대가 이후 사용 시작과 패턴에 영향을 준다는 점에서 예방의 표적이 된다."}, {"h": "양가적 기대", "p": "사용자는 흔히 긍정·부정 기대를 동시에 지닌다. 이 양가성을 다루는 것이 동기강화상담·인지행동치료에서 변화를 끌어내는 지점이 된다."}]'::jsonb, updated_at=now() WHERE id='expectancy';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "자기효능감은 특정 상황을 스스로 다룰 수 있다는 자신의 능력에 대한 믿음이다. 반두라가 제시했다."}, {"h": "중독 회복에서 왜 중요한가", "p": "''유혹 상황에서 사용하지 않을 수 있다''는 효능감이 재발을 예측하는 강력한 요인이다. 자신의 대처 능력을 믿을수록 고위험 상황을 더 잘 넘긴다."}, {"h": "어떻게 키우나", "p": "작은 성공 경험의 누적, 대리 경험(타인의 회복 목격), 지지적 격려, 정서 관리가 효능감을 키운다. 위기 상황을 한 번 잘 넘긴 경험이 ''나도 견딜 수 있다''는 믿음으로 이어진다."}, {"h": "무엇을 시사하나", "p": "회복은 의지의 문제가 아니라 다룰 수 있다는 믿음과 실제 기술의 문제다. 효능감을 키우는 경험을 쌓는 것이 회복의 핵심 전략이 된다."}]'::jsonb, advanced='[{"h": "재발예방의 핵심 변인", "p": "자기효능감은 말렛의 재발예방 모델에서 핵심 변인이다. 고위험 상황에서 효능감이 높으면 대처 반응이 나오고, 낮으면 재발로 이어지기 쉽다."}, {"h": "네 가지 원천", "p": "반두라는 효능감의 원천으로 성취 경험, 대리 경험, 언어적 설득, 정서적 각성 상태를 든다. 회복 지원은 이 원천들을 활용해 효능감을 키운다."}, {"h": "절제 위반 효과와의 관계", "p": "한 번의 실수 후 효능감이 급락하면, ''역시 나는 안 된다''는 절제 위반 효과가 재발을 키운다. 실수를 효능감 붕괴로 이어지지 않게 하는 것이 관건이다."}]'::jsonb, updated_at=now() WHERE id='self-efficacy';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "학습된 무기력은 통제할 수 없는 상황을 반복 경험하면서 ''무엇을 해도 소용없다''고 믿게 되어 시도조차 포기하는 상태다. 셀리그먼의 실험에서 유래한다."}, {"h": "중독과 어떻게 연결되나", "p": "반복된 회복 실패나 통제 불능의 경험이 ''나는 회복할 수 없다''는 무기력을 학습시킬 수 있다. 이 무기력이 회복 시도 자체를 접게 만든다."}, {"h": "재발과의 관계", "p": "재발 후 ''역시 안 된다''는 학습된 무기력이 회복 포기로 이어질 수 있다. 재발을 실패로 낙인찍는 것이 이 무기력을 강화한다."}, {"h": "어떻게 다루나", "p": "작은 통제 경험과 성공을 쌓아 ''나도 바꿀 수 있다''는 믿음(효능감)을 회복하는 것이 무기력을 푸는 열쇠다. 비판단적 지지가 이 과정을 돕는다."}]'::jsonb, advanced='[{"h": "귀인 양식", "p": "학습된 무기력은 실패를 ''내적·안정적·전반적'' 원인으로 귀인하는 비관적 양식과 연결된다. 이 귀인 양식을 바꾸는 것이 무기력과 우울을 다루는 인지적 표적이다."}, {"h": "우울과의 관계", "p": "학습된 무기력 이론은 우울증 이해로 확장됐고, 중독과 우울의 공존을 설명하는 한 틀이 된다. 무기력과 무쾌감이 겹쳐 회복을 어렵게 한다."}, {"h": "희망의 재학습", "p": "무기력이 학습되는 것처럼, 통제감과 희망도 재학습될 수 있다. 회복 공동체의 ''먼저 회복한 이들''의 존재가 대리 경험으로 무기력을 반박하는 힘이 된다."}]'::jsonb, updated_at=now() WHERE id='learned-helplessness';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "감정조절은 자신의 정서를 인식하고 다루는 능력이다. 이 능력의 결함이 중독의 발생과 유지에 핵심적 역할을 한다."}, {"h": "중독과 어떻게 연결되나", "p": "강한 부정 정서를 스스로 달래는 능력이 부족하면, 그 조절을 물질이나 행동에 의존하게 된다. 중독이 ''외주화된 감정조절''로 기능하는 것이다."}, {"h": "악순환", "p": "물질로 정서를 조절하면 스스로 조절하는 능력은 더 약해지고, 물질에 대한 의존은 커진다. 게다가 물질 사용 자체가 정서 문제를 악화시켜 악순환을 이룬다."}, {"h": "치료에의 함의", "p": "회복은 물질 없이 정서를 다루는 기술을 (다시) 배우는 과정을 포함한다. 마음챙김, 고통 감내, 정서 인식 같은 기술 훈련이 중독 치료의 핵심 요소가 된다."}]'::jsonb, advanced='[{"h": "결함이자 원인", "p": "정서조절 곤란은 중독의 원인이자 결과다. 취약성으로 선행하기도 하고, 물질 사용이 조절 능력을 더 손상시키기도 한다. 이 양방향성이 치료를 복잡하게 한다."}, {"h": "변증법적 행동치료", "p": "경계선 성격장애·중독에서 쓰이는 변증법적 행동치료(DBT)는 고통 감내·정서조절 기술을 핵심으로 한다. 정서조절을 명시적 치료 표적으로 삼는 대표 접근이다."}, {"h": "부적 강화와의 연결", "p": "정서조절 관점은 부적 강화(불쾌 완화)와 자가치료 가설을 잇는다. 조절되지 않는 고통을 물질이 잠시 달래주는 것이 사용을 강화하는 기제다."}]'::jsonb, updated_at=now() WHERE id='emotion-regulation';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "대처는 스트레스와 어려움에 대응하는 방식이다. 대처 방식의 종류와 유연성이 중독 취약성과 회복에 영향을 준다."}, {"h": "중독과 어떻게 연결되나", "p": "물질 사용이 스트레스에 대한 주된 대처 수단이 되면, 다른 건강한 대처가 발달하지 못한다. 어려움이 닥칠 때마다 물질을 찾는 좁은 대처 목록이 중독을 지속시킨다."}, {"h": "문제중심과 정서중심", "p": "대처는 문제 자체를 바꾸는 문제중심 대처와, 그로 인한 감정을 다루는 정서중심 대처로 나뉜다. 상황에 맞는 유연한 대처가 건강한 적응의 특징이다."}, {"h": "치료에의 함의", "p": "회복은 물질을 대신할 건강한 대처 기술을 넓히는 과정이다. 갈망·스트레스·고위험 상황에 쓸 구체적 대처 목록을 갖추는 것이 재발예방의 핵심이다."}]'::jsonb, advanced='[{"h": "회피 대처의 함정", "p": "물질 사용은 대표적 회피 대처로, 단기적으로 불편을 줄이지만 장기적으로 문제를 키운다. 회피에서 접근·문제해결 대처로의 전환이 회복의 방향이다."}, {"h": "대처 레퍼토리", "p": "건강한 적응은 다양한 대처를 상황에 맞게 유연하게 쓰는 능력이다. 중독은 이 레퍼토리가 물질 하나로 좁아진 상태로 볼 수 있다."}, {"h": "재발예방과의 연결", "p": "재발예방은 고위험 상황별 대처 계획을 미리 마련하는 것을 핵심으로 한다. 대처 기술의 확보가 자기효능감을 높이고 재발을 줄인다."}]'::jsonb, updated_at=now() WHERE id='coping';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "인지행동 모델은 생각(인지)·감정·행동이 서로 영향을 주며, 왜곡된 생각과 학습된 행동이 중독을 유지시킨다고 본다. 인지행동치료(CBT)의 토대다."}, {"h": "중독을 어떻게 설명하나", "p": "''스트레스엔 술이 답이다'', ''한 번쯤은 괜찮다'' 같은 자동적 생각과 왜곡이 사용을 정당화하고, 조건화된 단서와 습관이 행동을 유지시킨다는 것이다."}, {"h": "어떻게 치료하나", "p": "왜곡된 생각을 알아차리고 검토·수정하며(인지 재구성), 고위험 상황의 대처 기술과 거절 기술을 훈련한다. 생각과 행동 양쪽을 함께 다룬다."}, {"h": "무엇을 시사하나", "p": "인지행동 모델은 중독을 학습된, 따라서 다시 배울 수 있는 것으로 본다. 근거가 두터운 실용적 접근으로, 재발예방의 이론적 기반이 된다."}]'::jsonb, advanced='[{"h": "근거 기반의 핵심", "p": "CBT는 중독을 포함한 여러 정신건강 문제에서 근거가 가장 두터운 심리치료 중 하나다. 재발예방·대처기술 훈련이 그 핵심 구성요소다."}, {"h": "제3의 물결", "p": "전통적 CBT에 마음챙김·수용을 결합한 ''제3의 물결''(마음챙김 기반 재발예방, 수용전념치료 등)이 발전했다. 갈망과 싸우기보다 그것과 함께 머무는 접근을 더한다."}, {"h": "인지 왜곡의 다양성", "p": "중독을 유지하는 인지 왜곡에는 허용적 신념, 통제 착각, 절제 위반 효과 등이 있다. 이들을 식별하고 다루는 것이 CBT의 구체적 작업이다."}]'::jsonb, updated_at=now() WHERE id='cognitive-behavioral';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "변화단계 모델은 행동 변화가 한 번에 일어나지 않고 여러 단계를 거친다고 본다. 전숙고·숙고·준비·실행·유지 단계로 나뉜다."}, {"h": "각 단계", "p": "전숙고(문제 인식 없음), 숙고(양가감정), 준비(변화 결심), 실행(변화 시도), 유지(변화 지속)로 진행된다. 재발은 이 순환의 일부로 이해된다."}, {"h": "왜 중요한가", "p": "사람마다 변화의 단계가 다르므로, 단계에 맞는 개입이 필요하다. 아직 문제를 인정하지 않는 사람에게 실행을 요구하면 저항만 커진다."}, {"h": "치료에의 함의", "p": "변화단계 모델은 동기강화상담과 결합해, 각 단계에 맞춰 접근을 조율하는 근거가 된다. ''지금 어느 단계인가''를 파악하는 것이 개입의 출발이다."}]'::jsonb, advanced='[{"h": "범이론적 모델", "p": "변화단계는 프로차스카·디클레멘테의 범이론적 모델의 일부로, 변화 과정·의사결정 균형·자기효능감과 함께 작동한다. 여러 치료 이론을 아우르려는 통합적 틀이다."}, {"h": "비선형적 진행", "p": "변화는 단계를 직선으로 밟기보다, 나선형으로 오가며 진행된다. 재발은 실패가 아니라 순환의 한 부분으로, 다음 시도의 학습이 된다는 관점을 준다."}, {"h": "비판과 유용성", "p": "모델의 단계 구분이 임의적이라는 비판도 있으나, 개입을 개인의 준비도에 맞추게 한다는 실용적 가치로 널리 쓰인다. 특히 동기강화상담과의 결합에서 유용하다."}]'::jsonb, updated_at=now() WHERE id='stages-of-change';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "중독성 성격은 특정 성격 유형이 중독에 특히 취약하다는 대중적 개념이다. 그러나 모든 중독자에게 공통된 단일한 ''중독 성격''의 존재는 과학적으로 논쟁적이다."}, {"h": "무엇이 사실인가", "p": "단일한 중독 성격은 없지만, 충동성·감각추구·부정 정서성 같은 일부 기질이 여러 위험 행동과 함께 중독 위험을 높이는 것은 사실이다. 이는 ''유형''이 아니라 ''특성''의 문제다."}, {"h": "왜 오해가 위험한가", "p": "''중독 성격''이라는 개념은 개인을 낙인찍는 도구로 오용되기 쉽고, ''나는 원래 그런 사람''이라는 체념을 부를 수 있다. 성격을 고정된 운명으로 보게 하는 것이 위험하다."}, {"h": "무엇을 봐야 하나", "p": "중독 취약성은 단일 성격이 아니라 여러 기질·환경·경험의 상호작용에서 나온다. 개인을 유형화하기보다, 구체적 위험 요인과 강점을 함께 보는 것이 유용하다."}]'::jsonb, advanced='[{"h": "단일 유형의 신화", "p": "연구는 모든 중독자에게 공통된 단일 성격 프로파일을 지지하지 않는다. ''중독 성격''은 과학적 구성개념이라기보다 대중적 통념에 가깝다."}, {"h": "기질 차원의 기여", "p": "대신 충동성, 감각추구, 부정 정서성, 낮은 성실성 같은 기질 차원이 중독 위험에 부분적으로 기여한다. 이들은 연속적 특성이지 이분법적 유형이 아니다."}, {"h": "낙인의 도구가 될 위험", "p": "''중독 성격''이라는 명칭은 개인을 본질화·낙인화하고, 회복 가능성에 대한 비관을 부추길 수 있다. 신중한 사용이 요구되는 이유다."}]'::jsonb, updated_at=now() WHERE id='addictive-personality';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "대상관계·자기심리학은 초기 관계 경험이 내면화되어 자기 구조와 관계 방식을 형성한다고 보는 정신분석 학파다. 중독을 이 관계·자기 구조의 문제로 이해한다."}, {"h": "중독을 어떻게 보나", "p": "불안정한 초기 관계로 자기를 진정하고 통합하는 능력이 약하게 형성되면, 그 결핍을 물질이 대신 메운다고 본다. 물질이 ''위안을 주는 대상''의 대체물로 기능하는 것이다."}, {"h": "무엇을 시사하나", "p": "이 관점은 중독의 뿌리에 관계·자기 구조의 취약성이 있다고 본다. 물질 사용 아래에 있는 공허·자기 결핍을 다루지 않으면 회복이 어렵다는 통찰을 준다."}, {"h": "치료에의 함의", "p": "치료 관계 자체가 손상된 자기 구조를 회복하는 교정적 경험이 될 수 있다. 안정적 관계 속에서 자기를 진정하고 통합하는 능력을 다시 기르는 것이 회복의 일부다."}]'::jsonb, advanced='[{"h": "자기심리학의 관점", "p": "코헛의 자기심리학은 중독을 결핍된 자기대상 기능(자기를 지지·진정해 주는 기능)을 물질로 대체하려는 시도로 본다. 물질이 관계가 주어야 할 것을 대신한다는 것이다."}, {"h": "정서 조절과의 연결", "p": "대상관계 관점은 애착이론·정서조절 논의와 만난다. 초기 관계에서 형성되지 못한 자기 진정 능력의 결핍이 중독 취약성의 공통 뿌리로 지목된다."}, {"h": "관계로서의 회복", "p": "이 관점에서 회복은 물질과의 관계를 사람·공동체와의 안정적 관계로 대체하고, 손상된 자기를 관계 속에서 회복하는 과정이다. 회복 공동체의 치료적 힘을 설명하는 이론적 근거가 된다."}]'::jsonb, updated_at=now() WHERE id='object-relations';
-- ===== diagnosis =====
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "섭식장애는 음식·체중·체형과 관련된 심각한 심리·행동 문제로, 신경성 식욕부진증·신경성 폭식증·폭식장애 등을 포함한다. 생명을 위협할 수 있는 정신질환이다."}, {"h": "중독과의 접점", "p": "일부 섭식장애, 특히 폭식은 통제 상실·강박·정서조절 실패라는 점에서 중독과 유사한 기제를 공유한다. ''음식중독'' 개념도 이 접점에서 논의된다."}, {"h": "무엇이 핵심인가", "p": "섭식장애의 뿌리에는 흔히 낮은 자존감, 완벽주의, 통제 욕구, 정서적 고통이 있다. 음식·체형은 그 고통이 드러나는 표면일 때가 많다."}, {"h": "도움 받기", "p": "섭식장애는 전문적 치료가 필요한 심각한 질환이다. 혼자 해결하려 하기보다 의료·심리 전문가의 도움을 받는 것이 중요하며, 주변의 비판단적 지지가 회복에 큰 힘이 된다."}]'::jsonb, advanced='[{"h": "높은 위험성", "p": "신경성 식욕부진증은 정신질환 중에서도 사망 위험이 높은 편에 속한다. 신체적 합병증과 자살 위험이 함께 있어, 조기의 전문적 개입이 특히 중요하다."}, {"h": "중독 모델의 적용 논쟁", "p": "폭식을 중독의 틀로 볼지, 섭식장애 고유의 문제로 볼지에 대한 논쟁이 있다. 중독 모델이 통찰을 주기도 하지만, 섭식장애의 복잡성을 단순화할 위험도 지적된다."}, {"h": "통합적 이해", "p": "섭식장애는 생물학적 취약성, 심리적 요인, 사회문화적 압력(외모 규범)이 얽힌 다요인 질환이다. 회복은 음식 문제만이 아니라 그 아래의 정서·관계·자기 가치를 함께 다룰 때 지속된다."}]'::jsonb, updated_at=now() WHERE id='eating-disorders';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "충동조절장애는 자신이나 타인에게 해가 되는 충동을 억제하지 못하는 장애군이다. 병적 도벽, 방화벽, 간헐적 폭발장애 등이 포함된다."}, {"h": "중독과의 관계", "p": "충동조절장애는 행동중독과 개념적으로 겹친다. 실제로 도박장애는 과거 충동조절장애에 속했다가 중독 범주로 이동했다. 충동 억제의 실패라는 공통점이 있다."}, {"h": "어떻게 나타나나", "p": "행동 전에 긴장·충동이 고조되고, 행동하는 순간 안도·쾌감을 느끼는 패턴이 흔하다. 이는 중독의 갈망-사용-완화 순환과 유사하다."}, {"h": "무엇을 봐야 하나", "p": "충동조절장애와 중독의 경계는 유동적이며, 분류가 계속 재편되고 있다. 핵심은 충동을 억제하지 못해 반복되는 해로운 행동을 어떻게 이해하고 다루느냐다."}]'::jsonb, advanced='[{"h": "중독과의 재분류", "p": "도박장애가 충동조절장애에서 중독 범주로 옮겨간 것은, 두 범주의 경계가 유동적임을 보여준다. 어떤 반복 행동을 충동조절 문제로, 어떤 것을 중독으로 볼지가 계속 논의된다."}, {"h": "충동성과 강박성", "p": "충동조절장애는 충동성(즉각적 행동)과 강박성(반복)의 스펙트럼에서 이해된다. 중독처럼, 초기의 충동 주도에서 후기의 강박 주도로 이동하는 양상을 보일 수 있다."}, {"h": "치료의 공통성", "p": "충동조절장애와 중독은 인지행동치료, 충동 대처 훈련 등 유사한 치료 접근을 공유한다. 이 공통성이 두 범주의 근친성을 뒷받침한다."}]'::jsonb, updated_at=now() WHERE id='impulse-control-disorder';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "병적 도벽은 필요하지도, 금전적 가치 때문도 아닌데 물건을 훔치려는 충동을 억제하지 못하는 충동조절장애다."}, {"h": "어떻게 나타나나", "p": "훔치기 전 긴장이 고조되고, 훔치는 순간 안도·쾌감을 느끼며, 이후 죄책감이 따르는 순환이 반복된다. 이는 중독의 갈망-행동-완화 패턴과 유사하다."}, {"h": "일반 절도와 다르다", "p": "병적 도벽은 이득을 위한 계획적 절도와 다르다. 훔친 물건이 필요 없거나 버려지기도 하며, 행동 자체의 충동이 핵심이다."}, {"h": "무엇을 봐야 하나", "p": "병적 도벽은 드물지만 실재하는 장애로, 수치심 때문에 숨겨지기 쉽다. 도덕적 비난보다 충동조절 문제로 이해하고 전문적 도움을 받는 것이 필요하다."}]'::jsonb, advanced='[{"h": "행동중독과의 유사성", "p": "병적 도벽의 긴장-행동-완화 순환은 행동중독·충동조절장애와 기제를 공유한다. 이 때문에 중독의 틀로 이해·치료하려는 접근이 있다."}, {"h": "공존질환", "p": "병적 도벽은 우울·불안·다른 충동조절 문제와 흔히 공존한다. 단독으로 오기보다 다른 정신건강 문제와 얽혀 있는 경우가 많다."}, {"h": "치료", "p": "인지행동치료와 일부 약물치료가 시도되며, 충동 대처와 기저 정서 문제를 다룬다. 수치심을 낮추고 도움을 청할 수 있게 하는 것이 치료의 전제다."}]'::jsonb, updated_at=now() WHERE id='kleptomania';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "강박장애(OCD)는 원치 않는 반복적 사고(강박사고)와 그 불안을 줄이려는 반복 행동(강박행동)이 특징인 불안 관련 장애다."}, {"h": "중독과 무엇이 다른가", "p": "중독과 OCD 모두 반복 행동을 보이지만 동기가 다르다. OCD의 강박행동은 주로 불안을 줄이려는 것이고, 중독의 반복은 보상·쾌락과 습관에 뿌리를 둔다."}, {"h": "왜 함께 논의되나", "p": "둘 다 ''멈추고 싶어도 멈추지 못하는'' 반복이라는 점, 그리고 강박성이라는 공통 요소 때문에 함께 논의된다. 중독의 후기 강박적 사용은 OCD의 강박과 표면적으로 유사하다."}, {"h": "무엇을 봐야 하나", "p": "강박장애와 중독의 구분은 ''무엇을 위해 반복하는가''에 있다. 이 구분이 정확한 진단과 치료의 방향을 정한다."}]'::jsonb, advanced='[{"h": "강박성 스펙트럼", "p": "일부 학자는 OCD와 중독을 ''강박성 스펙트럼''에서 함께 본다. 그러나 신경회로와 동기 구조의 차이 때문에 완전히 동일시하기는 어렵다."}, {"h": "자아 이질성의 차이", "p": "OCD의 강박행동은 대개 원치 않는 것(자아 이질적)인 반면, 중독 초기의 사용은 원하는 것(자아 동질적)이다. 이 차이가 두 장애를 구분하는 핵심이다."}, {"h": "공존과 치료", "p": "OCD와 중독이 공존할 수 있으며, 이 경우 통합적 접근이 필요하다. 두 장애 모두 노출·반응 방지, 인지행동치료 요소를 활용하지만 세부 전략은 다르다."}]'::jsonb, updated_at=now() WHERE id='obsessive-compulsive';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "이중진단(공존질환)은 중독과 다른 정신질환(우울·불안·PTSD·조현병 등)이 함께 있는 상태다. 중독 인구에서 매우 흔하다."}, {"h": "왜 흔한가", "p": "정신질환의 고통을 물질로 달래거나(자가치료), 물질 사용이 정신 문제를 유발·악화시키거나, 공통의 취약성이 둘을 함께 일으키는 등 여러 경로로 공존이 생긴다."}, {"h": "왜 중요한가", "p": "한쪽만 치료하면 다른 쪽이 재발을 부르는 악순환이 생긴다. 우울을 다루지 않은 중독 치료, 중독을 다루지 않은 우울 치료 모두 지속되기 어렵다."}, {"h": "어떻게 치료하나", "p": "두 문제를 동시에·통합적으로 다루는 접근이 권장된다. 중독 치료와 정신과 치료가 분리되지 않고 하나의 팀·계획 안에서 이뤄지는 것이 효과적이다."}]'::jsonb, advanced='[{"h": "인과의 복잡성", "p": "이중진단에서 무엇이 원인이고 결과인지는 복잡하다. 자가치료, 물질 유발, 공통 취약성이 얽혀 있어, 단순한 선후 관계로 환원하기 어렵다."}, {"h": "치료 체계의 분절 문제", "p": "중독 서비스와 정신건강 서비스가 분리되어 있으면, 이중진단 환자가 두 체계 사이에서 방치되기 쉽다. 통합 치료 체계의 필요가 정책 과제로 지적된다."}, {"h": "예후와 통합 접근", "p": "이중진단은 단일 진단보다 예후가 나쁘고 재발 위험이 높다. 이 때문에 통합적·장기적 접근과 지속 관리가 특히 중요하다."}]'::jsonb, updated_at=now() WHERE id='dual-diagnosis';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "정신질환은 사고·감정·행동의 임상적으로 유의한 장애로, 중독과 밀접히 얽혀 있다. 중독 자체도 정신질환으로 분류된다."}, {"h": "중독과의 관계", "p": "우울·불안·조현병처럼 서로 다른 질환이 중독과 하나의 표준 진단체계 안에서 분류되고, 서로 공존하며 영향을 주고받는다. 중독과 정신질환은 흔히 함께 나타난다."}, {"h": "낙인의 공통점", "p": "중독과 다른 정신질환은 모두 낙인의 대상이 되기 쉽다. ''의지의 문제''로 오해받고 도움을 청하기 어렵다는 점에서 공통의 어려움을 겪는다."}, {"h": "무엇을 봐야 하나", "p": "중독을 정신질환의 하나로 이해하는 것은 낙인을 줄이고 치료를 정당화한다. 동시에 다른 정신질환과의 공존을 고려한 통합적 접근이 필요하다."}]'::jsonb, advanced='[{"h": "분류 체계 안의 중독", "p": "DSM·ICD 같은 표준 진단체계는 중독을 다른 정신질환과 함께 분류한다. 이는 중독을 도덕 문제가 아니라 치료 대상인 질환으로 규정하는 근거가 된다."}, {"h": "공통 취약성", "p": "중독과 여러 정신질환은 유전·신경·환경적 취약성을 상당 부분 공유한다. 이 공통 기반이 높은 공존율과 함께, 통합적 이해의 필요를 뒷받침한다."}, {"h": "질병 모델의 함의와 한계", "p": "중독을 정신질환으로 보는 것은 낙인 감소·치료 접근에 기여하지만, 사회적 요인과 회복 주체성을 과소평가할 위험도 있다. 의학적 관점과 사회적 관점의 균형이 요구된다."}]'::jsonb, updated_at=now() WHERE id='mental-disorders';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "DSM(정신질환 진단 및 통계 편람)은 미국정신의학회가 발간하는 정신질환 진단 기준서로, 중독 진단의 대표적 기준이다. 현행판은 DSM-5-TR이다."}, {"h": "무엇이 바뀌었나", "p": "DSM-5부터 ''남용/의존''의 이분법을 폐기하고 ''물질사용장애''로 통합했으며, 증상 개수로 심각도(경도·중등도·고도)를 구분한다. 도박장애를 중독 범주에 포함한 것도 중요한 변화다."}, {"h": "어떻게 진단하나", "p": "통제력 상실, 사회적 손상, 위험한 사용, 약리적 지표(내성·금단) 등 11개 기준 중 해당하는 개수로 진단·심각도를 판단한다. 사용량 자체가 아니라 기능 손상이 초점이다."}, {"h": "무엇을 알면 좋나", "p": "DSM은 진단의 공통 언어를 제공해 연구·치료·소통을 돕는다. 다만 진단 기준은 사회·과학의 변화에 따라 계속 개정되는 ''합의''이지 고정된 진리가 아니다."}]'::jsonb, advanced='[{"h": "ICD와의 관계", "p": "DSM과 함께 WHO의 ICD가 국제적으로 널리 쓰인다. 두 체계는 대체로 수렴하지만 세부에서 차이가 있으며(예: 게임장애 지위), 이 차이가 진단·정책 논쟁을 낳기도 한다."}, {"h": "진단의 사회적 성격", "p": "DSM의 개정은 과학적 근거뿐 아니라 사회적 합의·논쟁의 산물이다. 무엇을 장애로 포함·제외할지가 임상·연구·보험·낙인에 큰 영향을 주기에, 개정마다 논쟁이 따른다."}, {"h": "범주 대 차원 논쟁", "p": "DSM은 ''있다/없다''의 범주적 진단을 기본으로 하나, 중독을 심각도의 연속선(차원)으로 보는 관점이 강해지고 있다. 심각도 구분 도입이 이 흐름을 반영한다."}]'::jsonb, updated_at=now() WHERE id='dsm';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "불안장애는 과도하고 지속적인 불안·공포가 특징인 정신질환군으로, 중독과 매우 흔히 공존한다."}, {"h": "중독과 어떻게 연결되나", "p": "불안을 완화해 주는 물질(알코올·진정제 등)에 의존하게 되는 자가치료 경로가 흔하다. 불안을 달래려 시작한 사용이 의존으로 이어진다."}, {"h": "악순환", "p": "물질은 단기적으로 불안을 낮추지만, 금단·반동으로 불안을 다시 키운다. 특히 진정제·알코올은 이 악순환이 두드러져, 끊으려 하면 불안이 심해진다."}, {"h": "치료에의 함의", "p": "불안과 중독을 함께 다루는 통합 치료가 필요하다. 불안을 물질 없이 다루는 기술(인지행동치료·이완·마음챙김)을 익히는 것이 회복의 일부가 된다."}]'::jsonb, advanced='[{"h": "자가치료의 대표 경로", "p": "불안장애는 자가치료 가설이 가장 잘 들어맞는 공존질환 중 하나다. 불안의 고통을 물질로 달래려는 시도가 두 문제를 얽히게 한다."}, {"h": "진정제 의존의 함정", "p": "불안 치료에 쓰이는 벤조디아제핀이 오히려 의존을 낳는 역설이 있다. 반동성 불안 때문에 끊기 어려워지므로, 단기 사용과 대안 치료가 강조된다."}, {"h": "통합 치료의 근거", "p": "불안과 중독을 순차적으로 다루면 재발하기 쉬워, 동시에 다루는 통합 치료가 권장된다. 불안 관리 기술의 습득이 물질 의존을 줄이는 핵심 경로다."}]'::jsonb, updated_at=now() WHERE id='anxiety-disorders';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "질병모델은 중독을 도덕적 결함이나 의지의 문제가 아니라, 뇌에 기반한 만성·재발성 질환으로 보는 관점이다. 현대 중독 이해의 주류 틀이다."}, {"h": "무엇을 주장하나", "p": "반복 사용이 뇌의 보상·통제 회로를 변형시켜 통제력을 손상시킨다는 것이다. 따라서 중독은 치료가 필요한 질환이며, 재발도 질환의 특성으로 이해된다."}, {"h": "무엇에 기여했나", "p": "질병모델은 중독을 도덕 문제에서 의학 문제로 옮겨, 낙인을 줄이고 치료·보험 적용을 정당화했다. ''의지박약''이라는 비난에 맞서는 근거가 됐다."}, {"h": "비판도 있다", "p": "한편 질병모델이 개인의 주체성·회복 가능성을 과소평가하고, 사회·환경적 원인을 가린다는 비판도 있다. 중독을 ''평생 질병''으로 고정한다는 우려도 제기된다."}]'::jsonb, advanced='[{"h": "역사적 전환", "p": "질병모델은 벤저민 러시, 옐리네크를 거쳐 현대 뇌과학(볼코 등)으로 발전하며 중독 이해를 도덕에서 의학으로 전환시켰다. AA의 질병 개념도 대중적 확산에 기여했다."}, {"h": "비판적 관점", "p": "스탠턴 필 등은 질병모델이 중독을 지나치게 생물학화하고, 학습·맥락·선택의 역할과 자연 회복의 가능성을 가린다고 비판한다. ''질병 대 학습''의 논쟁이 이어진다."}, {"h": "통합을 향해", "p": "오늘날은 순수 질병모델과 순수 학습·선택 모델의 이분법을 넘어, 생물·심리·사회를 통합하는 관점이 요구된다. 뇌 변화도, 주체성도, 사회 환경도 함께 보는 것이다."}]'::jsonb, updated_at=now() WHERE id='disease-model';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "신체적 의존(내성·금단)은 약물에 대한 신체 적응이고, 중독은 통제 상실과 강박적 사용을 핵심으로 한다. 둘은 겹치지만 같지 않다."}, {"h": "왜 구분이 중요한가", "p": "처방약으로 신체 의존이 생겨도 중독이 아닐 수 있고, 그 반대도 가능하다. 이 구분은 통증 환자를 부당하게 ''중독자''로 낙인찍지 않기 위해 중요하다."}, {"h": "어떻게 다른가", "p": "의존은 ''몸이 약물에 적응한 상태''이고, 중독은 ''통제를 잃고 해로운데도 강박적으로 사용하는 상태''다. 의존은 중독의 한 요소일 수 있지만 전부는 아니다."}, {"h": "무엇을 봐야 하나", "p": "통증 치료로 아편류에 신체 의존이 생긴 환자를 곧바로 중독자로 보는 것은 부정확하다. 통제 상실과 강박적 사용이 있는지가 중독 판단의 핵심이다."}]'::jsonb, advanced='[{"h": "용어의 혼란사", "p": "DSM-IV까지 ''의존(dependence)''이 중독의 의미로 쓰이면서 신체적 의존과 혼동을 낳았다. DSM-5가 ''물질사용장애''로 용어를 바꾼 데는 이 혼란을 줄이려는 의도가 있었다."}, {"h": "통증 치료와 낙인", "p": "의존과 중독의 혼동은 정당한 통증 환자에게 낙인을 씌우고 치료 접근을 막을 수 있다. 이 구분은 아편류 처방의 임상·윤리에서 특히 중요하다."}, {"h": "가성중독과의 연결", "p": "통증이 조절되지 않아 약을 더 요구하는 행동(가성중독)이 중독처럼 보일 수 있다. 의존·중독·가성중독의 구분이 통증 관리의 정확성을 좌우한다."}]'::jsonb, updated_at=now() WHERE id='dependence-vs-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "가성중독은 통증이 충분히 조절되지 않아 약을 더 요구하는 행동이 중독처럼 보이지만, 실제로는 치료 부족이 원인인 상태를 가리키는 개념이다."}, {"h": "어떻게 구분하나", "p": "통증이 제대로 관리되면 약 요구 행동이 사라진다면, 그것은 중독이 아니라 통증 조절 부족의 신호였음을 시사한다. 이것이 가성중독의 핵심 논리다."}, {"h": "왜 중요한가", "p": "가성중독 개념은 통증 환자의 정당한 약 요구를 중독으로 오인해 치료를 박탈하는 것을 막으려는 취지에서 나왔다."}, {"h": "비판도 있다", "p": "그러나 이 개념이 아편류 과잉처방을 정당화하는 데 오용됐다는 비판이 있다. 그래서 오늘날은 신중하게, 근거와 함께 다뤄진다."}]'::jsonb, advanced='[{"h": "취지와 오용", "p": "가성중독은 통증 환자 보호라는 정당한 취지에서 출발했으나, 제약 마케팅 등에 의해 과잉처방을 합리화하는 데 오용됐다는 비판을 받는다. 개념 자체의 근거 기반이 약하다는 지적도 있다."}, {"h": "아편류 위기와의 관계", "p": "가성중독 개념의 오용은 아편류 위기의 한 배경으로 거론된다. ''중독처럼 보여도 통증 때문''이라는 논리가 위험 신호를 무시하게 만들 수 있었다."}, {"h": "균형의 필요", "p": "가성중독은 통증 치료와 중독 예방 사이의 긴장을 보여준다. 정당한 통증 요구를 존중하되, 실제 중독 위험도 놓치지 않는 균형 잡힌 판단이 요구된다."}]'::jsonb, updated_at=now() WHERE id='pseudoaddiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "ADHD(주의력결핍 과잉행동장애)는 부주의·과잉행동·충동성이 특징인 신경발달장애로, 중독의 대표적 위험 요인이자 공존질환이다."}, {"h": "어떻게 연결되나", "p": "ADHD의 충동성과 보상 민감성이 물질·행동 중독 위험을 높인다. 또 치료받지 못한 ADHD 성인이 각성 효과를 얻으려 물질을 자가치료적으로 쓰기도 한다."}, {"h": "치료가 위험을 낮춘다", "p": "적절한 ADHD 치료가 오히려 중독 위험을 낮춘다는 연구가 있다. 방치된 ADHD가 더 위험하며, 진단과 치료가 중독 예방에 기여할 수 있다."}, {"h": "무엇을 봐야 하나", "p": "ADHD와 중독이 공존하면 통합 치료가 필요하다. 자극제 치료제의 오남용 관리와 ADHD 자체의 치료를 균형 있게 다뤄야 한다."}]'::jsonb, advanced='[{"h": "공통 신경 기반", "p": "ADHD와 중독은 보상·실행기능 회로의 취약성을 공유한다. 이 공통 기반이 높은 공존율과 함께, ADHD를 중독 위험 요인으로 만드는 신경적 배경이다."}, {"h": "치료제 오남용의 딜레마", "p": "ADHD 치료에 쓰이는 자극제가 오남용될 수 있다는 우려와, 치료가 중독 위험을 낮춘다는 근거가 긴장한다. 처방 관리와 적절한 치료 사이의 균형이 임상 과제다."}, {"h": "과소진단의 문제", "p": "특히 성인 ADHD가 과소진단되어 방치되면, 자가치료적 물질 사용으로 이어질 수 있다. 정확한 진단이 중독 예방의 한 경로가 된다."}]'::jsonb, updated_at=now() WHERE id='adhd-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "PTSD(외상후스트레스장애)는 트라우마 경험 후 침습·회피·과각성 증상이 지속되는 장애로, 중독과 매우 흔히 공존한다."}, {"h": "어떻게 연결되나", "p": "침습적 기억·악몽·과각성의 고통을 달래려 물질에 의존하는 자가치료 경로가 대표적이다. 트라우마의 고통과 중독이 서로를 얽히게 한다."}, {"h": "악순환", "p": "물질은 단기적으로 PTSD 증상을 무디게 하지만, 장기적으로 회복을 방해하고 증상을 악화시킨다. 두 문제가 서로를 강화하는 악순환을 이룬다."}, {"h": "치료에의 함의", "p": "트라우마와 중독을 함께 다루는 통합 치료가 권장된다. 어느 하나만 다루면 재발하기 쉬우며, 안전을 확보한 뒤 트라우마를 다루는 단계적 접근이 쓰인다."}]'::jsonb, advanced='[{"h": "높은 공존율", "p": "PTSD와 물질사용장애는 서로의 위험을 크게 높이는 대표적 공존 조합이다. 특히 참전군인·폭력 피해자 등에서 두드러진다."}, {"h": "통합 치료 모델", "p": "''안전기반치료(Seeking Safety)'' 등 PTSD와 중독을 동시에 다루는 통합 모델이 개발됐다. 안전 확보를 우선하고, 재트라우마화를 피하는 것이 핵심 원칙이다."}, {"h": "트라우마 기반 관점", "p": "PTSD-중독 공존은 ''무엇이 문제인가''가 아니라 ''무슨 일이 있었는가''를 묻는 트라우마 기반 접근의 필요를 잘 보여준다. 고통의 뿌리를 다루는 것이 지속적 회복의 조건이다."}]'::jsonb, updated_at=now() WHERE id='ptsd-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "우울증은 지속적 우울감·무쾌감·기능 저하가 특징인 정신질환으로, 중독과 상호 악화하는 흔한 공존질환이다."}, {"h": "어떻게 연결되나", "p": "우울의 무기력·공허를 달래려는 물질 사용이, 다시 우울을 심화시키는 악순환을 만든다. 무쾌감이라는 공통 경험이 둘을 얽히게 한다."}, {"h": "무엇이 먼저인가", "p": "우울이 중독을 부르기도, 중독이 우울을 부르기도 하며, 공통 취약성이 둘을 함께 일으키기도 한다. 인과가 단순하지 않아 통합적 이해가 필요하다."}, {"h": "치료에의 함의", "p": "한쪽만 치료하면 재발하기 쉬워, 우울과 중독을 함께 다루는 통합 접근이 권장된다. 회복 초기의 무쾌감·우울 관리가 재발 방지에 중요하다."}]'::jsonb, advanced='[{"h": "무쾌감의 교차점", "p": "우울과 중독은 무쾌감(anhedonia)이라는 공통 증상에서 만난다. 보상 체계의 둔화가 두 문제의 공유된 신경 기반으로 지목된다."}, {"h": "자살 위험", "p": "우울-중독 공존은 자살 위험을 크게 높이는 조합이다. 이 때문에 통합 치료에서 안전 평가와 위기 관리가 특히 중요하다. (어려움을 겪고 있다면 전문기관의 도움을 받을 수 있다.)"}, {"h": "통합 치료의 근거", "p": "우울과 중독을 순차적으로 다루면 재발하기 쉬워, 동시에 다루는 통합 치료가 권장된다. 항우울제·심리치료와 중독 치료의 결합이 예후를 개선한다."}]'::jsonb, updated_at=now() WHERE id='depression-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "품행장애는 아동·청소년기의 반복적 규범 위반·공격 행동 패턴으로, 이후 물질사용장애와 반사회성 발달의 위험 요인이다."}, {"h": "어떻게 연결되나", "p": "이른 시기의 심한 품행 문제가 청소년기 물질 사용으로 이어지는 발달 경로가 확인된다. 충동성·규범 위반 성향이 물질 사용 위험을 높인다."}, {"h": "왜 중요한가", "p": "품행장애는 이후 중독·반사회성 성격장애로 이어질 수 있어, 발달 초기의 신호로 주목된다. 조기 개입이 이후 경로를 바꿀 수 있다."}, {"h": "무엇을 봐야 하나", "p": "품행 문제를 단순한 ''비행''이 아니라 개입이 필요한 발달적 신호로 볼 때, 이후 중독을 포함한 여러 문제를 예방할 여지가 생긴다."}]'::jsonb, advanced='[{"h": "발달 경로", "p": "품행장애–물질사용–반사회성으로 이어지는 발달 경로는 종단 연구로 확인돼 왔다. 이른 발현일수록 예후가 나쁜 경향이 있어 조기 개입이 강조된다."}, {"h": "공통 취약성", "p": "품행장애와 중독은 충동성, 정서조절 곤란, 불우한 환경 같은 취약성을 공유한다. 이 공통 기반이 둘의 연관을 설명한다."}, {"h": "조기 개입의 효과", "p": "가족 개입, 사회적 기술 훈련 등 조기 개입이 품행장애의 진행과 이후 중독 위험을 낮출 수 있다. 예방적 관점에서 아동기 개입의 가치가 강조된다."}]'::jsonb, updated_at=now() WHERE id='conduct-disorder';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "성격장애는 지속적이고 경직된 사고·감정·행동 패턴이 기능을 손상시키는 장애군이다. 경계선·반사회성 성격장애 등이 중독과 흔히 공존한다."}, {"h": "어떻게 연결되나", "p": "경계선 성격장애의 정서 조절 곤란, 반사회성 성격장애의 충동성·규범 위반이 중독과 얽힌다. 극심한 정서 기복이나 충동을 다루기 어려워 물질에 의존하기도 한다."}, {"h": "왜 치료가 복잡한가", "p": "성격장애는 관계·자기 구조의 문제가 얽혀 있어, 중독과 공존하면 치료가 특히 복잡하다. 통합적·장기적 접근이 요구된다."}, {"h": "무엇을 봐야 하나", "p": "성격장애-중독 공존은 낙인받기 쉽지만, 둘 다 치료 가능한 문제다. 정서 조절과 관계를 다루는 장기적 접근이 회복의 열쇠가 된다."}]'::jsonb, advanced='[{"h": "경계선 성격장애와 DBT", "p": "경계선 성격장애와 중독의 공존에는 변증법적 행동치료(DBT)가 근거를 보인다. 정서 조절·고통 감내 기술이 두 문제에 공통으로 작용한다."}, {"h": "반사회성과 치료 저항", "p": "반사회성 성격장애는 중독과 흔히 공존하며 치료 참여·유지가 어렵다. 동기·관계를 다루는 접근과 현실적 기대 설정이 필요하다."}, {"h": "자기·관계의 뿌리", "p": "성격장애-중독 공존은 대상관계·애착 관점에서 자기 구조와 관계 능력의 취약성이라는 공통 뿌리로 이해되기도 한다. 관계 속에서의 장기적 회복이 강조된다."}]'::jsonb, updated_at=now() WHERE id='personality-disorders';
-- ===== policy =====
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "규제물질법은 물질을 남용 가능성과 의료적 유용성에 따라 등급(스케줄)으로 분류·규제하는 법 체계다. 미국의 CSA가 대표적이다."}, {"h": "어떻게 작동하나", "p": "각 물질을 여러 등급으로 나누어, 등급에 따라 연구·처방·유통·처벌을 다르게 규율한다. 남용 위험이 높고 의료 가치가 없다고 분류된 물질일수록 엄격히 통제된다."}, {"h": "왜 중요한가", "p": "스케줄 분류는 어떤 물질을 연구할 수 있고, 처방할 수 있고, 소지 시 어떤 처벌을 받는지를 좌우한다. 법적 분류가 의료·연구·형사사법에 광범위한 영향을 준다."}, {"h": "논쟁", "p": "과학적 근거와 분류가 어긋난다는 비판이 있다. 의료적 활용 가능성이 논의되는 물질(대마·일부 환각제)이 엄격한 등급에 묶여 연구가 제약되는 것이 대표적 쟁점이다."}]'::jsonb, advanced='[{"h": "분류와 과학의 괴리", "p": "일부 물질의 스케줄 분류가 최신 과학적 근거와 어긋난다는 비판이 지속된다. 엄격한 분류가 치료 가능성 연구 자체를 가로막는 ''규제의 역설''이 지적된다."}, {"h": "형사처벌과의 연결", "p": "스케줄 분류는 처벌 수위와 직결되어, 분류의 형평성이 형사사법 불평등과 연결된다. 물질별·집단별 처벌 격차 논쟁이 이 법제와 얽혀 있다."}, {"h": "개정의 정치", "p": "물질의 재분류는 과학뿐 아니라 정치·산업·여론이 얽힌 과정이다. 대마 재분류 논의처럼, 분류 변경은 광범위한 사회적 파장을 낳는다."}]'::jsonb, updated_at=now() WHERE id='controlled-substances-act';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "마약류 분류는 물질의 위험성·의료 가치에 따라 법적 등급을 매기는 제도로, 규제·연구·의료 접근의 틀을 정한다."}, {"h": "국가마다 다르다", "p": "같은 물질도 나라마다 분류가 달라, 한 나라에선 엄격히 금지된 물질이 다른 나라에선 의료용으로 허용되기도 한다. 분류가 과학이 아니라 정책적 선택임을 보여준다."}, {"h": "무엇에 영향을 주나", "p": "분류는 처방 가능성, 연구 허용, 처벌 수위를 결정한다. 엄격한 분류는 오남용을 억제하지만 동시에 정당한 의료·연구 접근을 제약할 수 있다."}, {"h": "무엇을 봐야 하나", "p": "마약류 분류는 위험 통제와 의료·연구 접근 사이의 균형 문제다. 분류가 근거에 기반하는지, 그리고 그 사회적 결과가 무엇인지를 함께 봐야 한다."}]'::jsonb, advanced='[{"h": "국제 협약과 국내법", "p": "마약류 분류는 유엔 마약 통제 협약의 틀 안에서 각국이 국내법으로 구현한다. 국제 규범과 국내 정책 사이의 조율·긴장이 분류를 둘러싸고 나타난다."}, {"h": "신종 물질의 도전", "p": "신종 합성마약은 기존 분류를 우회하려 화학구조를 바꿔 등장한다. 이 ''추격전''이 개별 물질 분류의 한계를 드러내며, 포괄 규제 방식을 촉발했다."}, {"h": "재분류의 파급", "p": "물질의 재분류(예: 의료용 허용)는 연구·산업·형사사법에 큰 파급을 낳는다. 분류 변경은 단순한 행정이 아니라 사회적 합의의 문제다."}]'::jsonb, updated_at=now() WHERE id='drug-scheduling';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "금주법은 20세기 초 미국의 주류 제조·판매 금지 정책으로, 전면 금지 정책의 한계를 보여주는 역사적 사례로 자주 인용된다."}, {"h": "무슨 일이 있었나", "p": "음주는 일부 줄었으나, 불법 주류 시장과 조직범죄가 크게 성장했다. 수요가 사라지지 않은 채 공급만 불법화되자 지하 시장이 번성한 것이다."}, {"h": "무엇을 시사하나", "p": "금주법은 ''전면 금지가 수요를 없애기보다 지하 시장과 범죄를 키운다''는 교훈으로 인용된다. 오늘날 마약 정책 논쟁에서 자주 소환되는 준거다."}, {"h": "무엇을 봐야 하나", "p": "금주법의 실패는 금지 정책의 의도와 실제 결과가 다를 수 있음을 보여준다. 다만 알코올과 다른 물질의 차이를 고려한 신중한 적용이 필요하다."}]'::jsonb, advanced='[{"h": "금지의 의도치 않은 결과", "p": "금주법은 정책의 의도치 않은 결과를 보여주는 고전적 사례다. 조직범죄 성장, 위험한 밀조주, 법 경시 등이 금지의 부작용으로 나타났다."}, {"h": "마약 정책에의 유비", "p": "금주법은 ''마약과의 전쟁'' 비판에서 자주 유비로 쓰인다. 다만 알코올의 광범위한 사용과 마약의 차이 때문에, 유비의 적절성에 대한 논쟁도 있다."}, {"h": "규제된 합법화의 논거", "p": "금주법 폐지 후 알코올이 규제·과세된 합법 시장으로 돌아간 것은, 일부 물질의 ''규제된 합법화'' 논거로 인용된다. 금지와 방임 사이의 제3의 길에 대한 논의다."}]'::jsonb, updated_at=now() WHERE id='prohibition';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "마약과의 전쟁은 공급 차단과 형사처벌을 앞세운 강경 마약 정책 기조로, 수십 년간 세계 마약 정책을 지배했다."}, {"h": "무엇을 했나", "p": "마약의 생산·유통·사용을 범죄로 강력히 단속하고, 처벌을 강화했다. 1971년 미국에서 선언된 이후 세계로 확산되며 마약 정책의 지배적 패러다임이 됐다."}, {"h": "어떤 비판을 받나", "p": "수감 급증과 막대한 사회적 비용에 비해 사용 감소 효과가 제한적이라는 비판이 크다. 특정 인종·계층에 대한 불평등한 처벌도 문제로 지적된다."}, {"h": "무엇으로 이동하나", "p": "한계가 드러나면서, 처벌 중심에서 예방·치료·피해감소 중심으로의 전환이 논의된다. 포르투갈·스위스 등의 보건 중심 접근이 대안으로 주목받는다."}]'::jsonb, advanced='[{"h": "대량 수감의 유산", "p": "마약과의 전쟁은 대량 수감과 그에 따른 사회적 비용을 남겼다. 특히 형사처벌의 인종·계층 간 불평등이 정의의 문제로 비판받는다."}, {"h": "풍선 효과", "p": "공급 차단은 문제를 없애기보다 생산·유통을 다른 지역으로 이동시키는 ''풍선 효과''를 낳았다. 단속 중심 접근의 구조적 한계를 보여준다."}, {"h": "패러다임 전환의 논쟁", "p": "보건 중심으로의 전환이 논의되지만, 처벌의 억제 효과를 강조하는 관점과 첨예하게 대립한다. 마약 정책은 근거와 가치가 충돌하는 대표적 장이다."}]'::jsonb, updated_at=now() WHERE id='war-on-drugs';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "마약 정책은 물질 사용에 대한 사회의 대응 전체를 아우르는 영역으로, 금지·처벌 중심부터 보건·피해감소 중심까지 스펙트럼을 이룬다."}, {"h": "어떤 스펙트럼인가", "p": "한쪽 끝에는 강경한 처벌·금지가, 다른 쪽 끝에는 피해감소·회복 지원이 있다. 대부분의 정책은 그 사이 어딘가에 위치하며, 시대와 정치에 따라 이동한다."}, {"h": "무엇이 쟁점인가", "p": "같은 문제를 두고 처벌 강화와 치료 확대라는 상반된 방향이 경쟁한다. 근거 기반 정책과 도덕·정치적 가치가 충돌하는 대표적 장이다."}, {"h": "무엇을 봐야 하나", "p": "마약 정책은 효과성뿐 아니라 그 사회가 어떤 가치를 우선하는지를 드러낸다. 정책의 이름보다 그것을 뒷받침하는 인프라와 실제 결과를 함께 봐야 한다."}]'::jsonb, advanced='[{"h": "근거와 가치의 충돌", "p": "마약 정책은 근거만으로 결정되지 않는다. ''마약 청정 사회''라는 도덕적 가치와 ''해악 최소화''라는 실용적 가치가 충돌하며, 같은 데이터가 다르게 해석된다."}, {"h": "정책 이전의 어려움", "p": "한 나라에서 성공한 정책이 다른 곳에서 실패하기도 한다. 인프라·문화·물질 환경의 차이 때문에, 정책의 단순 이식은 위험하다."}, {"h": "행동중독으로의 확장", "p": "기존 마약 정책 논의는 물질에 집중돼 왔으나, 도박·게임 등 행동중독으로의 확장이 과제로 남아 있다. 사행산업 규제·디지털 환경 설계가 새로운 정책 영역이다."}]'::jsonb, updated_at=now() WHERE id='drug-policy';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "약물검사는 체액 등에서 물질 사용을 확인하는 검사로, 직장·사법·치료 현장에서 쓰인다."}, {"h": "어디에 쓰이나", "p": "고용, 형사사법(보호관찰 등), 치료 프로그램(유관관리 등)에서 사용을 확인하는 데 활용된다. 억제 효과와 함께 치료의 도구로도 기능한다."}, {"h": "어떤 논쟁이 있나", "p": "사생활 침해, 정확성(오탐 가능성), 낙인 문제가 논란이다. 검사가 사용을 억제하는 효과와 개인의 권리·공정성 사이의 긴장이 있다."}, {"h": "무엇을 봐야 하나", "p": "약물검사는 목적(안전·치료·처벌)에 따라 정당성이 다르게 평가된다. 검사 결과의 한계(사용 시점·양을 알기 어려움)와 오탐 가능성을 이해하는 것이 중요하다."}]'::jsonb, advanced='[{"h": "치료 도구로서의 검사", "p": "유관관리에서 약물검사는 처벌이 아니라 회복 행동을 강화하는 도구로 쓰인다. 음성 결과에 보상을 연결하는 방식이 대표적이다."}, {"h": "정확성과 오탐", "p": "약물검사는 위양성·위음성 가능성이 있고, 검출 기간이 물질마다 달라 해석에 주의가 필요하다. 단일 검사 결과를 절대시하는 것의 위험이 지적된다."}, {"h": "권리와 감시의 긴장", "p": "특히 고용 약물검사는 사생활·차별 문제와 얽힌다. 안전이 중요한 직무와 그렇지 않은 경우의 구분, 검사의 비례성이 쟁점이다."}]'::jsonb, updated_at=now() WHERE id='drug-testing';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "약물운전은 물질의 영향 아래 운전하는 것으로, 음주운전과 함께 중대한 공중 안전 문제다."}, {"h": "왜 위험한가", "p": "대마·처방약·불법 약물 등의 영향으로 판단력·반응 속도·주의력이 떨어져 사고 위험이 커진다. 여러 물질의 병용은 위험을 더한다."}, {"h": "단속의 어려움", "p": "알코올과 달리, 물질별로 ''얼마부터 위험한가''의 기준과 검출 방법이 달라 단속·입증이 까다롭다. 체내 잔류와 실제 손상 정도가 일치하지 않는 경우도 있다."}, {"h": "무엇을 봐야 하나", "p": "약물운전은 대마 합법화 등으로 새로운 정책 과제가 됐다. 정확한 손상 판정 기준과 검사법의 개발이 공중 안전의 관건이다."}]'::jsonb, advanced='[{"h": "손상 판정의 과학적 난제", "p": "혈중 물질 농도가 실제 운전 손상과 비례하지 않는 경우가 많아, ''얼마부터 위험한가''의 법적 기준 설정이 과학적으로 어렵다. 대마가 특히 그렇다."}, {"h": "합법화와 새로운 과제", "p": "대마 합법화 지역에서 약물운전 관리가 새로운 정책 과제로 부상했다. 음주운전 모델을 그대로 적용하기 어려운 특성이 있다."}, {"h": "검사 기술의 한계", "p": "현장에서 손상을 신속·정확히 판정하는 검사 기술이 아직 미비하다. 이 공백이 단속과 예방을 어렵게 하는 핵심 요인이다."}]'::jsonb, updated_at=now() WHERE id='drugged-driving';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "간접흡연은 비흡연자가 타인의 담배 연기에 노출되는 것으로, 명백한 건강 피해가 입증되어 금연 구역·실내 흡연 규제의 근거가 되었다."}, {"h": "무엇을 보여주나", "p": "간접흡연은 개인의 행동(흡연)이 타인의 건강에 해를 끼치는 대표 사례다. 이 ''타인에 대한 해악''이 흡연 규제를 정당화하는 핵심 논거가 됐다."}, {"h": "어떤 규제로 이어졌나", "p": "간접흡연의 피해 입증은 공공장소·실내 금연, 실내 흡연 규제 등 강력한 정책으로 이어졌다. 흡연을 개인의 자유에서 공공 보건의 문제로 전환시켰다."}, {"h": "무엇을 봐야 하나", "p": "간접흡연 규제는 개인의 자유와 타인의 건강권이 충돌할 때 사회가 어떻게 균형을 잡는지를 보여주는 사례다. 3차 흡연(잔류물) 등 새로운 관심도 등장한다."}]'::jsonb, advanced='[{"h": "타인 위해 원칙", "p": "간접흡연 규제는 ''타인에게 해를 끼치는 행위''에 대한 규제라는 점에서, 개인 사용에 대한 규제와 다른 강한 정당성을 갖는다. 자유와 위해 방지의 고전적 긴장을 보여준다."}, {"h": "정책의 성공 사례", "p": "간접흡연 규제와 금연 정책은 흡연율을 낮춘 공중보건의 성공 사례로 꼽힌다. 근거 축적이 정책 변화로 이어진 모범 경로다."}, {"h": "3차 흡연과 새 논의", "p": "최근에는 표면·먼지에 남은 담배 잔류물(3차 흡연)의 위해가 논의된다. 담배 위해에 대한 이해가 계속 확장되고 있음을 보여준다."}]'::jsonb, updated_at=now() WHERE id='secondhand-smoke';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "낙인은 중독을 도덕적 결함으로 보는 사회적 편견으로, 당사자의 수치심을 키우고 도움 요청·치료를 가로막는 회복의 큰 장벽이다."}, {"h": "어떻게 작동하나", "p": "''의지가 약해서''라는 시선이 당사자를 수치스럽게 만들어 문제를 숨기게 하고, 도움을 청하지 못하게 한다. 낙인이 두려워 치료가 늦어지는 것이 흔한 경로다."}, {"h": "어떤 해를 끼치나", "p": "낙인은 치료 접근을 막고, 회복을 어렵게 하며, 정책에도 영향을 준다. 중독자를 처벌 대상으로 보게 만들어 보건 중심 접근을 가로막기도 한다."}, {"h": "어떻게 줄이나", "p": "질병·회복 중심의 언어와 서사, 사람 중심 표현(''중독자'' 대신 ''중독을 가진 사람'')이 낙인을 줄이는 데 기여한다. 회복한 사람들의 이야기가 낙인을 반박하는 힘이 된다."}]'::jsonb, advanced='[{"h": "낙인의 층위", "p": "낙인은 사회적 낙인(타인의 편견), 자기 낙인(내면화된 수치심), 구조적 낙인(제도·정책의 차별)으로 나뉜다. 회복을 위해선 이 여러 층위를 함께 다뤄야 한다."}, {"h": "언어의 힘", "p": "''중독자'', ''깨끗하다/더럽다'' 같은 표현이 낙인을 강화한다는 인식에서, 사람 중심·비낙인 언어로의 전환이 국제적으로 권고된다. 언어가 태도와 정책에 영향을 준다."}, {"h": "당사자 관점", "p": "회복 당사자에게 낙인은 회복의 가장 큰 장벽 중 하나다. 당사자가 자기 이야기를 드러내고 서로를 지지하는 회복 공동체는, 낙인에 맞서 정체성을 회복하는 장이 된다."}]'::jsonb, updated_at=now() WHERE id='stigma';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "약물이용범죄 물질은 피해자를 무력화하는 데 악용되는 물질(무색·무취의 진정제 등)을 가리킨다."}, {"h": "어떻게 악용되나", "p": "음료에 몰래 섞여 피해자의 의식·저항을 무력화하는 데 쓰인다. GHB, 일부 진정제 등이 무색·무취 특성 때문에 악용된다."}, {"h": "무엇이 중요한가", "p": "이 문제의 핵심은 피해자 비난이 아니라 가해에 초점을 두는 것이다. ''조심했어야 한다''가 아니라 ''악용한 것이 범죄''라는 관점이 중요하다."}, {"h": "어떻게 대응하나", "p": "인식 교육, 음료 관리 등 예방과 함께, 피해자 지원과 가해 처벌에 초점을 둔 대응이 필요하다. 피해자를 탓하지 않는 사회적 태도가 중요하다."}]'::jsonb, advanced='[{"h": "가해 중심의 관점", "p": "약물이용범죄 대응의 핵심은 피해자 행동이 아니라 가해 행위에 초점을 두는 것이다. 피해자 비난은 신고를 위축시키고 2차 피해를 낳는다."}, {"h": "검출의 어려움", "p": "일부 물질은 체내에서 빠르게 대사되어 사후 검출이 어렵다. 이 특성이 입증과 처벌을 어렵게 하며, 신속한 대응과 증거 확보의 중요성을 부각한다."}, {"h": "예방과 지원의 균형", "p": "예방 교육은 필요하지만, 그것이 피해자에게 책임을 돌리는 방식이 되지 않도록 주의해야 한다. 안전 정보 제공과 가해 책임 강조의 균형이 요구된다."}]'::jsonb, updated_at=now() WHERE id='predatory-drugs';
-- ===== program =====
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "익명의 알코올중독자(AA)는 1935년 시작된 세계 최대의 알코올 회복 상호원조 모임으로, 12단계와 후원자·모임 공동체를 통해 단주를 돕는다."}, {"h": "어떻게 작동하나", "p": "정기 모임에서 자신의 이야기를 나누고, 먼저 회복한 후원자(스폰서)의 안내를 받으며 12단계를 밟는다. ''같은 경험을 가진 동료''가 서로를 돕는 것이 핵심이다."}, {"h": "무엇이 특별한가", "p": "전문가가 아니라 당사자들이 서로를 돕고, 무료이며 어디에나 있다. 소속감과 정체성의 회복을 제공하며, 이후 수많은 12단계 프로그램의 원형이 됐다."}, {"h": "한계와 다양성", "p": "영적 틀이 모두에게 맞는 것은 아니어서, SMART 리커버리 같은 세속적 대안이 함께 활용된다. 회복의 길이 하나가 아니라는 인식이 넓어지고 있다."}]'::jsonb, advanced='[{"h": "확산과 영향", "p": "AA는 NA·GA 등 수많은 12단계 모임의 모태가 됐고, 중독 회복 문화 전반에 큰 영향을 미쳤다. 상호원조와 당사자 회복이라는 패러다임을 대중화했다."}, {"h": "효과 근거", "p": "오랫동안 일화적이라는 비판이 있었으나, 근래 통제된 연구들은 AA·12단계 촉진 치료가 단주 유지에서 효과적임을 보고한다. 참여도·소속감이 효과를 좌우한다."}, {"h": "신앙 공동체와의 접점", "p": "AA의 영적 차원은 신앙 기반 회복 공동체와 자연스럽게 맞닿는다. 무력함의 인정, 자기를 넘어선 것에의 의탁이라는 요소가 신앙적 회복 서사와 공명한다."}]'::jsonb, updated_at=now() WHERE id='alcoholics-anonymous';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "익명의 약물중독자(NA)는 약물 전반의 회복을 위해 12단계를 적용한 상호원조 모임으로, AA 모델을 물질 일반으로 확장했다."}, {"h": "어떻게 작동하나", "p": "AA와 마찬가지로 정기 모임, 후원자, 12단계를 통해 회복을 지지한다. 특정 물질이 아니라 ''중독''이라는 공통 경험을 중심으로 모인다는 점이 특징이다."}, {"h": "무엇을 강조하나", "p": "동료 지지와 정체성 회복을 강조하며, 어떤 약물이든 중독의 본질은 같다는 관점에 선다. 회복한 동료가 다음 사람을 돕는 구조다."}, {"h": "무엇을 봐야 하나", "p": "NA는 약물 사용장애 회복에서 접근성 높은 자조 자원이다. 12단계가 맞지 않는 사람을 위한 대안과 함께, 회복 경로의 다양성 속에서 이해된다."}]'::jsonb, advanced='[{"h": "AA 모델의 확장", "p": "NA는 AA의 12단계를 물질 일반으로 확장하며, 약물 사용장애 회복의 대표적 자조 모임이 됐다. 물질을 가리지 않는 ''중독'' 정체성이 특징이다."}, {"h": "약물보조치료와의 긴장", "p": "일부 12단계 전통은 단약을 강조해, 약물보조치료(MAT)를 받는 사람과 긴장을 빚기도 했다. 근래에는 MAT를 받는 회복자를 포용하려는 움직임이 있다."}, {"h": "접근성의 가치", "p": "NA는 무료이고 널리 퍼져 있어, 치료 자원이 부족한 곳에서도 접근 가능한 회복 지원이 된다. 이 접근성이 자조 모임의 핵심 강점이다."}]'::jsonb, updated_at=now() WHERE id='narcotics-anonymous';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "단도박 모임(GA)은 도박 문제 회복을 위한 12단계 기반 상호원조 모임으로, 도박장애의 재정·관계 피해 회복을 함께 다룬다."}, {"h": "어떻게 작동하나", "p": "AA·NA와 같은 12단계·후원자·모임 구조를 도박 문제에 적용한다. 도박으로 무너진 삶을 함께 회복해 가는 동료 지지가 핵심이다."}, {"h": "무엇이 특별한가", "p": "도박장애는 물질이 아닌 행동중독이지만, GA는 통제 상실·강박이라는 공통 경험 위에서 회복을 지지한다. 재정 문제 정리 같은 도박 특유의 과제도 다룬다."}, {"h": "무엇을 봐야 하나", "p": "GA는 행동중독에 12단계 회복 모델이 적용된 사례다. 도박의 재정·법률·관계 피해가 크기에, 자조 모임과 함께 실질적 문제 해결 지원이 병행되면 효과적이다."}]'::jsonb, advanced='[{"h": "행동중독으로의 적용", "p": "GA는 물질중독의 12단계 모델이 행동중독에 적용될 수 있음을 보여준다. 이는 물질·행동 중독의 공통 기제에 대한 실천적 방증이기도 하다."}, {"h": "도박 특유의 과제", "p": "도박장애는 재정 파탄·부채·법적 문제가 두드러져, GA는 이런 실질적 피해의 회복도 다룬다. 관계 회복(가족)도 중요한 부분이다."}, {"h": "근거와 보완", "p": "GA의 효과 근거는 AA에 비해 제한적이며, 인지행동치료 등 전문 치료와 병행될 때 더 효과적이라는 지적이 있다. 자조와 전문 치료의 결합이 권장된다."}]'::jsonb, updated_at=now() WHERE id='gamblers-anonymous';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "알아넌은 중독자의 가족·친지를 위한 상호원조 모임으로, 동반의존에서 벗어나 자신의 삶을 돌보도록 돕는다."}, {"h": "무엇을 다루나", "p": "중독자를 바꾸는 법이 아니라, 가족 자신이 건강한 경계를 세우고 스스로를 돌보는 법을 배운다. ''내가 통제할 수 없는 것''을 내려놓는 것을 강조한다."}, {"h": "왜 필요한가", "p": "중독은 당사자만이 아니라 가족 전체에 영향을 주고, 가족도 회복이 필요하다. 알아넌은 회복이 당사자만의 과제가 아님을 보여준다."}, {"h": "무엇을 봐야 하나", "p": "알아넌은 가족의 회복이 당사자의 회복과 별개로, 그리고 그것을 지지하는 방식으로 필요함을 보여준다. 가족의 소진과 동반의존을 다루는 자조 자원이다."}]'::jsonb, advanced='[{"h": "가족 회복의 제도화", "p": "알아넌은 ''가족도 회복이 필요하다''는 인식을 제도화한 대표 사례다. 중독을 개인이 아니라 가족 체계의 문제로 보는 관점과 통한다."}, {"h": "동반의존 다루기", "p": "알아넌은 가족이 중독자의 문제에 과도하게 얽매이는 동반의존에서 벗어나도록 돕는다. 건강한 경계와 자기 돌봄이 핵심 주제다."}, {"h": "가족치료와의 관계", "p": "알아넌 같은 가족 자조 모임은 전문 가족치료와 상호보완적이다. 가족을 회복의 자원으로 전환한다는 점에서 공동체적 회복의 일부를 이룬다."}]'::jsonb, updated_at=now() WHERE id='al-anon';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "평온을 비는 기도는 바꿀 수 없는 것을 받아들이는 평온, 바꿀 수 있는 것을 바꾸는 용기, 그 둘을 분별하는 지혜를 구하는 짧은 기도로, 12단계 회복에서 널리 낭송된다."}, {"h": "무엇을 담고 있나", "p": "통제할 수 없는 것에 대한 집착을 내려놓고, 지금 할 수 있는 것에 집중하며, 그 둘을 분별하는 지혜를 구한다. 수용과 통제 가능성의 분별이라는 회복의 태도를 담는다."}, {"h": "왜 회복에 쓰이나", "p": "중독 회복에서 통제할 수 없는 것(과거·타인·결과)에 매달리는 것은 고통과 재발을 부른다. 이 기도는 그 집착을 내려놓고 할 수 있는 것에 집중하도록 돕는 지침이 된다."}, {"h": "무엇을 봐야 하나", "p": "평온을 비는 기도는 종교적 형식을 넘어, 수용과 행동의 균형이라는 보편적 회복 지혜를 담는다. 이 분별의 태도가 회복 실천의 핵심이 된다."}]'::jsonb, advanced='[{"h": "수용과 행동의 균형", "p": "이 기도의 핵심은 수용(바꿀 수 없는 것)과 행동(바꿀 수 있는 것)의 균형, 그리고 둘을 분별하는 지혜다. 이는 인지행동치료의 통제 가능성 구분과도 통한다."}, {"h": "영성과 보편성", "p": "특정 종교의 기도에서 출발했으나, 그 지혜는 종교를 넘어 보편적으로 받아들여진다. 세속적 회복에서도 그 태도가 유용하게 활용된다."}, {"h": "실천으로서의 분별", "p": "무엇을 받아들이고 무엇을 바꿀지 분별하는 것은 회복의 일상적 실천이다. 이 기도는 그 분별을 매 순간 상기시키는 도구로 기능한다."}]'::jsonb, updated_at=now() WHERE id='serenity-prayer';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "시나논은 1950년대 등장한 초기 치료공동체로, 강한 동료 대면을 특징으로 하며 이후 치료공동체 운동에 큰 영향을 주었으나 후기의 통제적 변질로 논란이 된 역사적 사례다."}, {"h": "무엇을 했나", "p": "공동생활 속에서 강한 상호 대면(''게임'')을 통해 회복을 시도했다. 전문가가 아니라 당사자 공동체가 치료의 주체가 되는 모델을 개척했다."}, {"h": "무엇이 문제였나", "p": "초기의 혁신적 영향에도 불구하고, 시나논은 후기에 폐쇄적·권위적 집단으로 변질되며 통제와 학대 논란에 휩싸였다. 공동체의 힘이 위험으로 바뀐 사례다."}, {"h": "무엇을 남겼나", "p": "시나논은 공동체 기반 회복의 가능성과 위험을 동시에 보여준다. 치료공동체 운동에 영감을 주는 한편, 권력·통제의 위험을 경계하게 하는 교훈을 남겼다."}]'::jsonb, advanced='[{"h": "치료공동체의 뿌리", "p": "시나논은 현대 치료공동체 운동의 중요한 뿌리다. 당사자 공동체가 회복의 도구가 된다는 발상이 이후 여러 프로그램으로 이어졌다."}, {"h": "공동체의 명암", "p": "시나논의 역사는 강한 공동체가 지지와 통제라는 양면을 지님을 보여준다. 소속과 변화를 주는 힘이, 견제되지 않으면 억압으로 변질될 수 있다."}, {"h": "경계해야 할 교훈", "p": "시나논의 변질은 회복 공동체가 폐쇄성·카리스마적 권위·외부 견제 부재로 흐를 때의 위험을 경고한다. 건강한 공동체의 조건을 성찰하게 하는 사례다."}]'::jsonb, updated_at=now() WHERE id='synanon';
-- ===== figures =====
UPDATE encyclopedia_terms SET body='[{"h": "누구인가", "p": "빌 윌슨(빌 W.)은 익명의 알코올중독자(AA)의 공동 창립자로, 자신의 회복 경험을 바탕으로 12단계와 상호원조 모델을 정립했다."}, {"h": "무엇을 했나", "p": "알코올 문제로 고통받다 회복을 경험한 뒤, 한 알코올중독자가 다른 이를 돕는 상호원조의 원리를 세웠다. 이 원리가 AA와 12단계의 토대가 됐다."}, {"h": "무엇이 중요한가", "p": "빌 W.는 당사자의 회복 경험을 회복의 핵심 자원으로 삼은 흐름의 상징이다. 전문가가 아니라 회복한 당사자가 다음 사람을 돕는 모델을 개척했다."}, {"h": "무엇을 남겼나", "p": "그가 세운 상호원조 모델은 세계적 회복 운동의 토대가 됐고, 이후 수많은 12단계 프로그램으로 확장됐다. 개인의 회복 경험이 사회적 운동이 된 사례다."}]'::jsonb, advanced='[{"h": "경험 기반 회복의 상징", "p": "빌 W.는 ''전문 지식''이 아니라 ''회복 경험''이 회복을 도울 수 있다는 패러다임의 상징이다. 이는 오늘날 또래 지지·회복 코치의 뿌리가 된다."}, {"h": "영적 각성과 융의 영향", "p": "그의 회복 서사에는 영적 각성이 중심에 있으며, 카를 융의 견해가 영향을 준 것으로 알려져 있다. 이 영적 차원이 AA의 성격을 형성했다."}, {"h": "유산과 한계", "p": "빌 W.의 모델은 거대한 영향을 미쳤으나, 영적 틀이 모두에게 맞지는 않는다는 한계도 함께 남겼다. 회복 경로의 다양성 논의는 그 유산에 대한 성찰이기도 하다."}]'::jsonb, updated_at=now() WHERE id='bill-w';
UPDATE encyclopedia_terms SET body='[{"h": "누구인가", "p": "닥터 밥(로버트 스미스)은 AA의 공동 창립자로, 빌 윌슨과 함께 한 알코올중독자가 다른 이를 돕는 상호원조 원리를 실천으로 세웠다."}, {"h": "무엇을 했나", "p": "의사이자 알코올 문제 당사자였던 그는 빌 W.와의 만남을 통해 회복했고, 함께 AA의 토대를 놓았다. 동료가 동료를 돕는 회복을 몸소 실천했다."}, {"h": "무엇이 중요한가", "p": "닥터 밥은 초기부터 상호원조 회복을 실천으로 구현한 인물이다. 이론이 아니라 실제 돕는 관계 속에서 회복이 일어남을 보여줬다."}, {"h": "무엇을 남겼나", "p": "그와 빌 W.의 협력은 AA의 출발점이 됐다. 두 사람의 만남이 세계적 회복 운동의 씨앗이 되었다는 점에서 상징적이다."}]'::jsonb, advanced='[{"h": "실천으로서의 회복", "p": "닥터 밥은 상호원조를 실천으로 구현한 인물로 기억된다. 그의 역할은 회복이 추상적 원리가 아니라 구체적 돕는 관계임을 보여준다."}, {"h": "의료와 자조의 만남", "p": "의사이면서 당사자였던 그의 이중 위치는, 전문 의료와 당사자 자조가 만나는 지점을 상징한다. 이는 이후 미네소타 모델 등으로 이어지는 흐름의 전조이기도 하다."}, {"h": "협력의 상징", "p": "닥터 밥과 빌 W.의 협력은 회복이 혼자가 아니라 관계 속에서 이뤄짐을 보여주는 원형적 사례다. AA의 근본 원리가 이 만남에서 나왔다."}]'::jsonb, updated_at=now() WHERE id='dr-bob';
UPDATE encyclopedia_terms SET body='[{"h": "누구인가", "p": "E. M. 옐리네크는 알코올중독을 단계적으로 진행하는 질병으로 체계화한 초기 연구자로, 질병모델의 학문적 토대를 놓았다."}, {"h": "무엇을 했나", "p": "알코올중독의 진행을 단계로 설명하는 ''옐리네크 곡선''을 제시하고, 알코올중독을 질병으로 개념화하는 연구를 수행했다. 중독 연구를 학문의 영역으로 끌어올렸다."}, {"h": "무엇이 중요한가", "p": "그의 연구는 중독을 도덕 문제가 아니라 진행성 질병으로 바라보게 한 학문적 전환의 기점이 됐다. 질병모델의 대중화·제도화에 기여했다."}, {"h": "무엇을 남겼나", "p": "옐리네크 곡선은 중독의 진행과 회복을 단계로 이해하는 틀을 제공했다. 다만 그의 유형화는 이후 단순화·일반화의 한계도 지적받았다."}]'::jsonb, advanced='[{"h": "질병모델의 학문적 정초", "p": "옐리네크는 중독의 질병 개념에 학문적 체계를 부여했다. 그의 작업은 벤저민 러시의 초기 통찰과 현대 뇌과학을 잇는 중간 고리로 볼 수 있다."}, {"h": "유형화와 그 한계", "p": "그가 제시한 알코올중독의 유형·단계 구분은 영향력이 컸으나, 이후 지나친 일반화와 근거의 한계가 지적됐다. 모든 사례를 단일 진행 경로로 보기 어렵다는 것이다."}, {"h": "연구 방법의 시대적 제약", "p": "옐리네크의 초기 연구는 제한된 표본과 방법의 시대적 제약을 안고 있었다. 그럼에도 중독을 체계적 연구 대상으로 정립한 역사적 의의는 크다."}]'::jsonb, updated_at=now() WHERE id='jellinek';
UPDATE encyclopedia_terms SET body='[{"h": "누구인가", "p": "벤저민 러시는 18~19세기 미국의 의사로, 만성 과음을 도덕적 타락이 아니라 일종의 질병으로 본 초기 인물이다."}, {"h": "무엇을 했나", "p": "당시 지배적이던 도덕적 관점에 맞서, 습관적 과음을 의지로 통제하기 어려운 질병적 상태로 이해하려 했다. 중독의 의학적 이해의 아주 이른 씨앗을 뿌렸다."}, {"h": "무엇이 중요한가", "p": "러시는 중독을 질병으로 보는 관점의 역사적 선구로 언급된다. 도덕에서 의학으로의 전환이 그에게서 이미 시작됐다."}, {"h": "무엇을 남겼나", "p": "그의 통찰은 이후 옐리네크와 현대 질병모델로 이어지는 긴 흐름의 출발점이 됐다. 중독 이해의 역사적 뿌리를 보여주는 인물이다."}]'::jsonb, advanced='[{"h": "질병모델의 먼 기원", "p": "벤저민 러시는 중독 질병모델의 아주 이른 역사적 뿌리로 인용된다. 그의 관점은 시대를 앞선 것이었으나, 당대에는 널리 받아들여지지 않았다."}, {"h": "시대적 맥락", "p": "러시의 견해는 계몽주의적 의학의 맥락에서 나왔다. 그의 일부 다른 의학적 견해는 오늘날 기준으로 낡았으나, 중독에 대한 통찰은 선구적이었다."}, {"h": "도덕에서 의학으로", "p": "러시의 의의는 중독을 도덕적 실패가 아니라 치료 대상인 상태로 보려 한 관점의 전환에 있다. 이 전환이 이후 수 세기에 걸쳐 발전한다."}]'::jsonb, updated_at=now() WHERE id='benjamin-rush';
UPDATE encyclopedia_terms SET body='[{"h": "누구인가", "p": "카를 융은 심층심리학자로, 알코올중독의 회복에 영적 전환이 필요할 수 있다는 견해가 AA의 형성에 영향을 준 것으로 알려져 있다."}, {"h": "무엇을 했나", "p": "한 알코올중독 환자에 대해, 의학적 치료를 넘어선 영적 각성이 회복에 필요할 수 있다는 견해를 전한 것으로 전해진다. 이 생각이 AA 초기 형성에 영향을 줬다."}, {"h": "무엇이 중요한가", "p": "융의 견해는 중독 회복에서 의미·영적 차원의 중요성을 시사한다. 회복이 단지 증상 제거가 아니라 삶의 전환일 수 있음을 조명한다."}, {"h": "무엇을 남겼나", "p": "융을 통해 중독과 영성·의미의 연결이 회복 담론에 들어왔다. 이는 12단계의 영적 차원과 신앙 기반 회복의 사상적 배경이 됐다."}]'::jsonb, advanced='[{"h": "영성과 회복의 연결", "p": "융의 견해는 중독 회복에서 영적·의미 차원의 역할을 조명한다. 이는 순수 의학적 관점으로 환원되지 않는 회복의 측면을 시사한다."}, {"h": "AA에의 간접적 영향", "p": "융의 견해가 빌 W.를 통해 AA의 영적 틀 형성에 영향을 준 것으로 전해진다. 심층심리학과 회복 운동이 만나는 흥미로운 지점이다."}, {"h": "의미의 회복", "p": "융의 관점은 회복을 증상 제거를 넘어 의미·전체성의 회복으로 본다. 이는 회복을 삶의 재건으로 이해하는 현대적 관점과 공명한다."}]'::jsonb, updated_at=now() WHERE id='carl-jung';
UPDATE encyclopedia_terms SET body='[{"h": "누구인가", "p": "노라 볼코는 중독의 뇌과학을 이끈 대표적 연구자로, 도파민·보상회로와 전전두피질 조절 손상을 통해 중독을 뇌질환으로 규명하는 연구를 주도해 왔다."}, {"h": "무엇을 했나", "p": "뇌영상 연구를 통해 중독이 뇌의 보상·동기·통제 회로를 어떻게 변화시키는지를 밝혔다. 질병모델의 현대 신경과학적 근거를 제시하고 대중화했다."}, {"h": "무엇이 중요한가", "p": "볼코의 연구는 ''중독은 뇌의 병''이라는 이해를 과학적으로 뒷받침해, 낙인을 줄이고 치료를 정당화하는 데 기여했다."}, {"h": "무엇을 봐야 하나", "p": "볼코의 뇌질환 관점은 큰 영향을 미쳤으나, 사회·환경적 요인과 회복 주체성을 함께 봐야 한다는 보완적 논의도 이어진다. 그의 연구는 통합적 이해의 한 축이다."}]'::jsonb, advanced='[{"h": "뇌질환 모델의 대변자", "p": "볼코는 현대 뇌질환 모델을 과학적으로 정립하고 대중화한 대표 인물이다. 그의 뇌영상 연구가 이 모델의 핵심 근거를 제공했다."}, {"h": "낙인 감소의 기여", "p": "''중독은 도덕적 실패가 아니라 뇌질환''이라는 메시지는 낙인을 줄이고 치료 접근을 넓히는 데 기여했다. 이는 공중보건적으로 중요한 함의를 지닌다."}, {"h": "비판과 균형", "p": "한편 뇌질환 모델이 사회적 결정 요인과 회복 가능성·주체성을 과소평가한다는 비판도 있다. 볼코 자신도 최근 사회·환경 요인의 통합을 강조하는 방향으로 논의를 넓혀왔다."}]'::jsonb, updated_at=now() WHERE id='nora-volkow';
UPDATE encyclopedia_terms SET body='[{"h": "누구인가", "p": "조지 쿠브는 중독의 스트레스·부적 강화 차원을 강조한 신경과학자로, 알로스타시스와 ''중독의 어두운 면'' 개념으로 후기 중독을 설명했다."}, {"h": "무엇을 했나", "p": "중독이 쾌락 추구에서 고통 회피로 옮겨가는 후기 단계를, 뇌 스트레스 체계의 변화와 보상 기준선의 이동(알로스타시스)으로 설명했다."}, {"h": "무엇이 중요한가", "p": "쿠브의 연구는 중독을 쾌락 추구로만 보는 관점을 넘어, 후기 중독의 만성적 고통과 부적 강화를 조명했다. 중독 동기의 전환을 이해하는 틀을 제공했다."}, {"h": "무엇을 남겼나", "p": "알로스타시스와 ''어두운 면'' 개념은 후기 중독·회복 초기의 무쾌감을 이해하는 핵심 틀이 됐다. 보상 중심 모델을 스트레스 차원으로 보완했다."}]'::jsonb, advanced='[{"h": "부적 강화의 조명", "p": "쿠브의 기여는 중독의 부적 강화(고통 회피) 차원을 신경과학적으로 정립한 데 있다. 이는 보상 중심 설명이 놓친 후기 중독의 동기를 채운다."}, {"h": "알로스타시스 이론", "p": "그의 알로스타시스 개념은 반복 사용이 뇌의 균형점 자체를 이동시켜 만성적 불쾌를 낳는다고 본다. 이 이론이 후기 중독의 ''어두운 면''을 설명한다."}, {"h": "스트레스 체계의 역할", "p": "쿠브는 뇌 스트레스 체계(CRF 등)가 금단·갈망·재발에 하는 역할을 강조했다. 이는 스트레스가 재발의 강력한 방아쇠인 임상 현실과 부합한다."}]'::jsonb, updated_at=now() WHERE id='george-koob';
UPDATE encyclopedia_terms SET body='[{"h": "누구인가", "p": "스탠턴 필은 질병모델을 비판하며 중독을 학습된·맥락적 경험으로 이해해야 한다고 주장한 심리학자다."}, {"h": "무엇을 주장하나", "p": "중독은 고정된 뇌질환이라기보다, 개인의 삶의 맥락 속에서 학습된 경험이며 자연스럽게 회복될 수도 있다고 본다. 중독 이해의 다원적 관점을 강조한다."}, {"h": "무엇이 중요한가", "p": "필의 비판은 ''한 번 중독은 영원한 질병''이라는 관점에 도전하며, 회복의 다양성과 자연 회복의 가능성을 부각했다. 질병모델에 대한 중요한 반론을 제기했다."}, {"h": "무엇을 봐야 하나", "p": "필의 관점은 논쟁적이지만, 중독을 순수 생물학으로 환원하는 것의 한계를 상기시킨다. 뇌 변화와 학습·맥락·주체성을 함께 보는 통합적 이해에 기여한다."}]'::jsonb, advanced='[{"h": "질병모델 비판의 대표", "p": "필은 질병모델 비판의 대표적 목소리다. 그는 질병 개념이 중독을 지나치게 생물학화하고 개인의 주체성·회복 가능성을 가린다고 본다."}, {"h": "자연 회복의 강조", "p": "필은 많은 사람이 공식 치료 없이 회복(자연 회복)한다는 점을 강조한다. 이는 ''중독=평생 질병''이라는 서사에 대한 실증적 반론으로 제시된다."}, {"h": "논쟁의 생산성", "p": "필의 관점은 논쟁적이지만, 질병모델의 과잉을 견제하고 회복의 다양성을 조명하는 생산적 긴장을 만든다. 오늘날 통합적 관점은 이 논쟁의 산물이기도 하다."}]'::jsonb, updated_at=now() WHERE id='stanton-peele';
-- ===== society =====
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "동반의존은 중독자와의 관계에서 상대의 문제에 과도하게 얽매여, 자신의 필요를 희생하고 중독을 의도치 않게 지속시키는 관계 패턴이다."}, {"h": "어떻게 나타나나", "p": "중독자를 대신해 책임을 떠안고, 문제를 감추고, 뒷수습을 반복하는 것이 대표적이다. 돕는다는 것이 오히려 당사자가 결과를 직면할 기회를 없앤다."}, {"h": "왜 문제인가", "p": "동반의존은 중독자의 회복을 방해할 뿐 아니라, 가족 자신의 삶과 건강도 무너뜨린다. 돌봄이 자기 소진과 통제로 변질되는 것이다."}, {"h": "어떻게 다루나", "p": "건강한 경계를 세우고, 자신을 돌보며, ''통제할 수 없는 것''을 내려놓는 것이 회복의 방향이다. 알아넌 같은 자조 모임과 가족치료가 도움이 된다."}]'::jsonb, advanced='[{"h": "개념의 유용성과 한계", "p": "동반의존은 가족의 어려움을 조명하는 유용한 개념이지만, 지나치게 넓게 적용되어 정상적 돌봄까지 병리화한다는 비판도 있다. 신중한 사용이 요구된다."}, {"h": "가능하게 하기(enabling)", "p": "동반의존의 핵심 행동인 ''가능하게 하기''는 선의의 도움이 중독을 지속시키는 역설을 보여준다. 돕는 방식의 전환이 회복 지원의 관건이다."}, {"h": "가족 회복과 공동체", "p": "동반의존 개념은 가족도 회복이 필요함을 강조한다. 이는 가족치료·가족 자조 모임, 나아가 가족을 품는 회복 공동체의 필요로 이어진다."}]'::jsonb, updated_at=now() WHERE id='codependency';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "중독의 사회적 비용은 중독이 개인을 넘어 사회 전체에 부과하는 경제적·사회적 부담을 가리킨다. 의료비, 생산성 손실, 형사사법 비용 등을 포함한다."}, {"h": "어떤 비용인가", "p": "치료·응급 의료비, 노동 생산성 저하, 범죄·형사사법 비용, 가정 붕괴와 아동 피해, 사고 등 광범위하다. 직접 비용뿐 아니라 눈에 덜 띄는 간접 비용이 크다."}, {"h": "무엇을 시사하나", "p": "중독의 비용이 막대하다는 것은, 예방·치료에 대한 투자가 사회적으로 이득임을 시사한다. ''치료가 처벌보다 비용효과적''이라는 논거의 근거가 된다."}, {"h": "무엇을 봐야 하나", "p": "사회적 비용 계산은 정책 우선순위를 정하는 근거가 된다. 다만 비용을 강조하다 당사자를 ''부담''으로만 보는 시각으로 흐르지 않도록 균형이 필요하다."}]'::jsonb, advanced='[{"h": "투자로서의 치료", "p": "여러 분석은 치료·예방에 대한 투자가 이후의 의료·사법·생산성 비용을 절감해, 비용효과적임을 보여준다. 이는 보건 중심 접근의 경제적 논거다."}, {"h": "비용의 분포", "p": "중독의 비용은 개인·가족·지역사회·국가에 불균등하게 분포한다. 특히 아동·가족이 지는 보이지 않는 비용이 과소평가되기 쉽다."}, {"h": "계산의 관점 문제", "p": "무엇을 비용으로 계산하느냐는 관점에 따라 달라지며, 비용 담론이 당사자를 ''사회적 부담''으로 낙인찍는 데 오용될 위험도 있다. 인간적 관점과의 균형이 요구된다."}]'::jsonb, updated_at=now() WHERE id='costs-of-addiction';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "예방은 중독이 발생하기 전에 위험을 줄이는 개입이다. 대상과 시점에 따라 보편적·선택적·지표적 예방으로 나뉜다."}, {"h": "어떤 종류가 있나", "p": "전체 인구를 대상으로 한 보편적 예방, 위험군을 겨냥한 선택적 예방, 이미 초기 신호를 보이는 이를 위한 지표적 예방으로 구분된다. 대상에 맞는 접근이 효과적이다."}, {"h": "무엇이 효과적인가", "p": "단순한 ''겁주기''식 교육은 효과가 제한적이며, 사회적 기술·거절 기술·규범 형성, 그리고 위험 환경 개선이 더 효과적이다. 개인과 환경을 함께 겨냥해야 한다."}, {"h": "왜 중요한가", "p": "예방은 발생한 중독을 치료하는 것보다 비용효과적이며, 특히 청소년기 개입이 중요하다. 위험 요인을 줄이고 보호 요인을 키우는 것이 핵심이다."}]'::jsonb, advanced='[{"h": "근거 기반 예방", "p": "공포 조장·정보 전달 위주 예방은 효과가 약하거나 역효과를 낼 수 있다. 사회정서 기술, 규범 교정, 환경 개입을 결합한 근거 기반 예방이 효과적이다."}, {"h": "위험·보호 요인", "p": "예방은 위험 요인(트라우마·또래 영향 등)을 줄이고 보호 요인(안정적 관계·유능감 등)을 키우는 것을 겨냥한다. 발달 초기의 개입이 특히 효과적이다."}, {"h": "환경적 예방", "p": "개인 교육을 넘어, 가격·접근성·광고 규제 같은 환경적 예방이 인구 차원에서 큰 효과를 낸다. 개인 책임과 환경 설계를 함께 다루는 것이 중요하다."}]'::jsonb, updated_at=now() WHERE id='prevention';
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "관문 약물은 특정 물질(대마·니코틴·알코올 등)의 사용이 이후 더 강한 물질 사용으로 이어지는 ''관문''이 된다는 가설과 관련된 개념이다."}, {"h": "무엇을 주장하나", "p": "비교적 접근하기 쉬운 물질의 조기 사용이 이후 다른 물질 사용의 문턱을 낮춘다는 것이다. 청소년 예방 논의에서 자주 등장한다."}, {"h": "논쟁이 있다", "p": "관문 가설은 상관을 인과로 오해할 수 있다는 비판을 받는다. 조기 물질 사용과 이후 사용이 공통의 취약성(환경·기질)에서 비롯될 수 있기 때문이다."}, {"h": "무엇을 봐야 하나", "p": "관문 개념은 조기 사용 예방의 중요성을 시사하지만, 단순한 인과 도식으로 받아들이면 오해를 낳는다. 상관과 인과, 공통 요인을 구분해 보는 신중함이 필요하다."}]'::jsonb, advanced='[{"h": "상관과 인과의 문제", "p": "관문 가설의 핵심 논쟁은 상관을 인과로 볼 수 있는가다. 조기 사용자가 이후 다른 물질을 쓸 확률이 높은 것은 사실이나, 그것이 ''관문 물질 때문''인지는 불분명하다."}, {"h": "공통 취약성 설명", "p": "대안적 설명은 조기 물질 사용과 이후 사용이 공통의 취약성(충동성·불우한 환경·또래)에서 함께 비롯된다는 것이다. 이 관점에서 관문 물질은 원인이 아니라 지표다."}, {"h": "정책적 함의의 신중함", "p": "관문 가설은 특정 물질 규제의 논거로 쓰이지만, 인과가 불확실한 만큼 정책적 적용에 신중함이 요구된다. 조기 사용 예방의 중요성은 별개로 인정된다."}]'::jsonb, updated_at=now() WHERE id='gateway-drugs';
COMMIT;
-- 확인:
SELECT category, count(*) FILTER (WHERE jsonb_array_length(body)>0) AS with_body, count(*) AS total FROM encyclopedia_terms GROUP BY category ORDER BY category;
